","dynacomp/adaptive.py":""""Target-budgeted coordinate enrichment using exact rational box envelopes."""
from .rational import matrix, q, mul, encoded, mv
from .bounds import box_horizon_bound, usable_horizon
import heapq


def coordinate_candidate(model, selected):
    selected = tuple(selected)
    n = len(model.A)
    if not selected or len(set(selected)) != len(selected) or any(type(i) is not int or not 0 <= i < n for i in selected):
        raise ValueError("Need distinct valid coordinate indices")
    e = matrix([[int(j == i) for j in range(n)] for i in selected])
    v = matrix([[int(j == i) for i in selected] for j in range(n)])
    return {"selected": list(selected), "E": encoded(e), "V": encoded(v),
            "G": encoded(mul(mul(e, model.A), v)), "H": encoded(mul(e, model.B)),
            "D": encoded(mul(model.C, v))}


def adaptive_coordinates(model, initial_center, initial_radius, input_radii, tolerance,
                         initial_coordinates=None, max_rank=None, coordinate_costs=None):
    """Greedy target-error improvement per added-coordinate cost.

    Stopping is uniform over supplied boxes. Greedy selection is not globally
    rank-optimal, and costs are user-supplied estimates rather than timings.
    """
    n = len(model.A)
    tol = q(tolerance)
    if tol < 0:
        raise ValueError("Tolerance must be nonnegative")
    max_rank = n if max_rank is None else max_rank
    if type(max_rank) is not int or not 1 <= max_rank <= n:
        raise ValueError("Rank budget must lie between 1 and n")
    costs = [q(v) for v in (coordinate_costs if coordinate_costs is not None else [1]*n)]
    if len(costs) != n or any(v <= 0 for v in costs):
        raise ValueError("Coordinate costs must be strictly positive")
    selected = sorted(set(initial_coordinates if initial_coordinates is not None else
                          [j for j in range(n) if any(row[j] for row in model.C)]))
    if not selected or len(selected) > max_rank:
        raise ValueError("Initial coordinates exceed budget or are empty")
    # Validate once even when initial-coordinate indices are malformed.
    coordinate_candidate(model, selected)
    trace = []

    def assess(indices):
        candidate = coordinate_candidate(model, indices)
        bound = box_horizon_bound(model, candidate["V"], candidate["E"], candidate["G"], candidate["H"],
                                  initial_center, initial_radius, input_radii)
        worst = max(q(v) for v in bound["bound"])
        return candidate, bound, worst

    candidate, bound, worst = assess(selected)
    while True:
        trace.append({"selected": list(selected), "rank": len(selected), "worst_bound": str(worst),
                      "usable_horizon": usable_horizon(bound["bound"], tol)})
        if worst <= tol:
            status = "tolerance_met"
            break
        if len(selected) == max_rank:
            status = "rank_budget_exhausted"
            break
        trials = []
        for j in range(n):
            if j not in selected:
                c, b, w = assess(sorted(selected+[j]))
                score = (worst-w)/costs[j]
                trials.append((score, -w, -costs[j], -j, c, b, w))
        best = max(trials, key=lambda row: row[:4])
        _, _, _, neg_j, candidate, bound, worst = best
        selected = sorted(selected+[-neg_j])
        trace[-1]["chosen_coordinate"] = -neg_j
        trace[-1]["improvement_per_cost"] = str(best[0])
        trace[-1]["trials"] = [{"coordinate": -row[3], "worst_bound": str(row[6]),
                                 "improvement_per_cost": str(row[0])} for row in trials]
    return {"schema": "dynacomp.adaptive/1", "status": status, "tolerance": str(tol),
            "candidate": candidate, "box_bound": bound, "trace": trace,
            "cost": str(sum(costs[i] for i in selected)),
            "model": {k: encoded(getattr(model,k)) for k in ("A","B","C")},
            "domain": {"initial_center": [str(q(v)) for v in initial_center],
                       "initial_radius": [str(q(v)) for v in initial_radius],
                       "input_radii": [[str(q(v)) for v in u] for u in input_radii]},
            "max_rank": max_rank, "coordinate_costs": [str(v) for v in costs],
            "scope": "greedy coordinate family; uniform stated box and input budgets"}


def replay_adaptive(packet):
    """Replay the chosen candidate and bound, without rerunning greedy search."""
    from .linear import LinearModel
    if packet.get("schema") != "dynacomp.adaptive/1":
        raise ValueError("Unknown schema")
    model = LinearModel.from_rows(**packet["model"])
    candidate = coordinate_candidate(model, packet["candidate"]["selected"])
    if candidate != packet["candidate"]:
        raise ValueError("Candidate does not match selected coordinates")
    domain = packet["domain"]
    bound = box_horizon_bound(model, candidate["V"],candidate["E"],candidate["G"],candidate["H"],
                              domain["initial_center"],domain["initial_radius"],domain["input_radii"])
    if bound != packet["box_bound"]:
        raise ValueError("Uniform box bound does not match")
    tolerance = q(packet["tolerance"])
    budget = packet["max_rank"]
    costs = [q(v) for v in packet["coordinate_costs"]]
    if tolerance < 0 or type(budget) is not int or not 1 <= budget <= len(model.A):
        raise ValueError("Invalid tolerance/rank budget")
    if len(costs) != len(model.A) or any(v <= 0 for v in costs):
        raise ValueError("Invalid coordinate costs")
    if q(packet["cost"]) != sum(costs[i] for i in candidate["selected"]):
        raise ValueError("Reported cost does not match")
    rank = len(candidate["selected"])
    success = max(q(v) for v in bound["bound"]) <= tolerance
    if rank > budget or packet["status"] != ("tolerance_met" if success else "rank_budget_exhausted"):
        raise ValueError("Reported status does not follow from tolerance")
    if not success and rank != budget:
        raise ValueError("Rank budget not exhausted")
    return True


def optimal_coordinates(model, initial_center, initial_radius, input_radii, tolerance,
                        required_coordinates=None, max_rank=None, coordinate_costs=None,
                        max_evaluations=10000):
    """Best-first exact least-cost search within a specified coordinate family.

    The first feasible popped subset has minimum additive cost among subsets
    meeting this particular conservative box-envelope criterion. No monotonic
    error assumption or simulated-trace extrapolation is used.
    """
    n=len(model.A)
    required=tuple(sorted(set(required_coordinates if required_coordinates is not None else
                             [j for j in range(n) if any(row[j] for row in model.C)])))
    coordinate_candidate(model,required)
    limit=n if max_rank is None else max_rank
    if type(limit) is not int or not len(required)<=limit<=n:
        raise ValueError("Invalid rank limit")
    if type(max_evaluations) is not int or max_evaluations<1:
        raise ValueError("Positive evaluation budget required")
    tol=q(tolerance)
    costs=[q(v) for v in (coordinate_costs if coordinate_costs is not None else [1]*n)]
    if tol<0 or len(costs)!=n or any(v<=0 for v in costs):
        raise ValueError("Invalid tolerance or coordinate costs")
    missing=[i for i in range(n) if i not in required]
    heap=[(sum(costs[i] for i in required),len(required),(),0)]
    evaluations=[]
    while heap and len(evaluations)<max_evaluations:
        cost,rank,extra,start=heapq.heappop(heap)
        selected=sorted(required+extra)
        candidate=coordinate_candidate(model,selected)
        bound=box_horizon_bound(model,candidate['V'],candidate['E'],candidate['G'],candidate['H'],
                                initial_center,initial_radius,input_radii)
        worst=max(q(v) for v in bound['bound'])
        evaluations.append({'selected':selected,'cost':str(cost),'worst_bound':str(worst)})
        if worst<=tol:
            return {'schema':'dynacomp.coordinate-search/1','status':'optimal_for_bound_criterion',
                    'candidate':candidate,'box_bound':bound,'cost':str(cost),'evaluations':evaluations,
                    'criterion':'least additive cost among bound-accepted coordinate sets containing required coordinates',
                    'required_coordinates':list(required),'tolerance':str(tol),
                    'frontier_lower_cost':str(heap[0][0]) if heap else None}
        if rank<limit:
            for j in range(start,len(missing)):
                index=missing[j]
                heapq.heappush(heap,(cost+costs[index],rank+1,extra+(index,),j+1))
    return {'schema':'dynacomp.coordinate-search/1',
            'status':'evaluation_budget_exhausted' if heap else 'no_bound_accepted_subset',
            'evaluations':evaluations,'tolerance':str(tol),'required_coordinates':list(required),
            'frontier_lower_cost':str(heap[0][0]) if heap else None,
            'scope':'failure of bounded search or envelope criterion is not impossibility for the true dynamics'}
","dynacomp/binary64.py":""""Portable binary64 bits, exact integer accumulation and round-to-nearest-even.

No arithmetic operation here depends on the host floating point rounding mode.
Finite inputs only for arithmetic; NaN payloads survive bits/from_bits transport.
Exact zero sums round to +0. Negative nonzero underflow rounds to -0.
"""
import struct
from fractions import Fraction

SIGN = 1 << 63
FRAC = (1 << 52) - 1
INF = 0x7ff0000000000000
MAX_FINITE = INF - 1


def _word(word):
    if type(word) is not int or not 0 <= word < 1 << 64:
        raise ValueError('Expected an unsigned 64-bit integer')
    return word


def bits(value):
    if type(value) is not float:
        raise TypeError('Expected a Python binary64 float')
    return int.from_bytes(struct.pack('>d', value), 'big')


def from_bits(word):
    return struct.unpack('>d', _word(word).to_bytes(8, 'big'))[0]


def classify(word):
    word = _word(word)
    e, f = (word >> 52) & 2047, word & FRAC
    return ('nan' if f else 'infinity') if e == 2047 else (
        ('subnormal' if f else 'zero') if e == 0 else 'normal')


def dyadic(word):
    """Signed integer m and exponent e with exact stored value m*2**e."""
    word = _word(word)
    exponent, fraction = (word >> 52) & 2047, word & FRAC
    if exponent == 2047:
        raise ValueError('Nonfinite operand')
    m, e = ((1 << 52) | fraction, exponent - 1075) if exponent else (fraction, -1074)
    if word & SIGN:
        m = -m
    if m:
        shift = (abs(m) & -abs(m)).bit_length() - 1
        m >>= shift
        e += shift
    return m, e


def exact(word):
    m, e = dyadic(word)
    return Fraction(m << e) if e >= 0 else Fraction(m, 1 << -e)


def _even_ratio(n, d):
    a, r = divmod(n, d)
    return a + int(2*r > d or (2*r == d and a & 1))


def round_bits(value):
    """Correctly round an exact rational, including subnormals and overflow."""
    if isinstance(value, float):
        raise TypeError('Use exact rationals, or bits() for existing floats')
    x = Fraction(value)
    sign = SIGN if x < 0 else 0
    n, d = abs(x.numerator), x.denominator
    if not n:
        return 0
    e = n.bit_length() - d.bit_length()
    if (n < d << e) if e >= 0 else (n << -e < d):
        e -= 1
    if e > 1023:
        return sign | INF
    unit = max(-1074, e - 52)
    m = _even_ratio(n, d << unit) if unit >= 0 else _even_ratio(n << -unit, d)
    if m == 1 << 53:
        m >>= 1
        unit += 1
    if unit > 971:
        return sign | INF
    if m < 1 << 52:
        return sign | m
    return sign | ((unit + 1075) << 52) | (m - (1 << 52))


def round_dyadic(m, e):
    if type(m) is not int or type(e) is not int:
        raise TypeError('Integer significand and exponent required')
    return round_bits(Fraction(m << e) if e >= 0 else Fraction(m, 1 << -e))


def exact_dot(left, right):
    """Integer superaccumulator: exact sum of products of stored operands."""
    left, right = tuple(left), tuple(right)
    if len(left) != len(right):
        raise ValueError('Dot dimensions differ')
    terms = []
    for a, b in zip(left, right):
        m, e = dyadic(a)
        n, f = dyadic(b)
        if m and n:
            terms.append((m*n, e+f))
    if not terms:
        return Fraction(0)
    exponent = min(e for _, e in terms)
    integer = sum(m << (e-exponent) for m, e in terms)
    return Fraction(integer << exponent) if exponent >= 0 else Fraction(integer, 1 << -exponent)


def dot_bits(left, right):
    """One final rounding, not a BLAS, sequential-dot, or FMA contract."""
    return round_bits(exact_dot(left, right))


def order_key(word):
    word = _word(word)
    if classify(word) == 'nan':
        raise ValueError('NaNs have no numeric order')
    return ((~word) & ((1 << 64)-1)) if word & SIGN else word | SIGN


def next_up(word):
    word = _word(word)
    if classify(word) == 'nan':
        raise ValueError('NaN has no next number')
    if word == INF:
        return word
    if word == SIGN:
        return 1
    return word - 1 if word & SIGN else word + 1


def next_down(word):
    return next_up(_word(word) ^ SIGN) ^ SIGN


def _root(n, degree):
    low, high = 0, 1 << ((n.bit_length()+degree-1)//degree)
    while low < high:
        mid = (low+high+1)//2
        if mid**degree <= n:
            low = mid
        else:
            high = mid-1
    return low


def power_certificate(word, degree):
    """Exact rational d-th power of the stored value; no decimal-intent claim."""
    word = _word(word)
    if type(degree) is not int or not 2 <= degree <= 4096:
        raise ValueError('Power degree must be between 2 and 4096')
    m, e = dyadic(word)
    root = _root(abs(m), degree)
    yes = not m or ((m > 0 or degree % 2) and e % degree == 0 and root**degree == abs(m))
    result = None
    if yes:
        root = -root if m < 0 else root
        k = e//degree if m else 0
        result = Fraction(root << k) if k >= 0 else Fraction(root, 1 << -k)
    return {'schema': 'exact.binary64-power/1', 'word': word, 'hex': f'{word:016x}',
            'degree': degree, 'classification': classify(word), 'odd_significand': m,
            'exponent': e, 'is_power': bool(yes), 'root': None if result is None else str(result),
            'scope': 'exact rational value stored in the finite binary64 word'}


def replay_power(packet):
    if packet != power_certificate(packet['word'], packet['degree']):
        raise ValueError('Binary64 power certificate does not reconstruct')
    return True
","dynacomp/bounds.py":""""Exact rational output-error envelopes for approximate lifted dynamics.

Bounds are algebraic finite-horizon inequalities, not floating-point estimates.
They need no asymptotic stability assumption and include hidden initial state.
"""
from .rational import matrix, mul, sub, mv, identity, norm_inf, vector_norm, q, addv, encoded


def finite_horizon_bound(model, V, G, H, x0, inputs):
    v, g, h = matrix(V), matrix(G), matrix(H)
    n, r = len(model.A), len(g)
    if len(v) != n or len(v[0]) != r or len(g[0]) != r:
        raise ValueError("Expected V[n,r], G[r,r]")
    if len(h) != r or len(h[0]) != len(model.B[0]):
        raise ValueError("Expected H[r,m]")
    # Initial reduced state is supplied separately via projection by caller.
    if not isinstance(x0, dict) or set(x0) != {"full", "reduced"}:
        raise ValueError("x0 must contain full and reduced initial states")
    full0 = tuple(q(x) for x in x0["full"])
    z = tuple(q(x) for x in x0["reduced"])
    e0 = tuple(a-b for a, b in zip(full0, mv(v, z)))
    if len(full0) != n:
        raise ValueError("Wrong full initial dimension")
    residual = sub(mul(model.A, v), mul(v, g))
    forcing = sub(model.B, mul(v, h))
    us = [tuple(q(x) for x in u) for u in inputs]
    zs = [z]
    for u in us:
        zs.append(addv(mv(g, zs[-1]), mv(h, u)))
    targets = [model.C]
    for _ in us:
        targets.append(mul(targets[-1], model.A))
    transition_norms = [norm_inf(mul(ca, residual)) for ca in targets]
    input_norms = [norm_inf(mul(ca, forcing)) for ca in targets]
    # e_t=A^t e0 + sum A^(t-1-j)(R z_j + S u_j).
    envelopes = []
    for t in range(len(us)+1):
        bound = vector_norm(mv(targets[t], e0))
        for j in range(t):
            lag = t-1-j
            bound += transition_norms[lag]*vector_norm(zs[j])
            bound += input_norms[lag]*vector_norm(us[j])
        envelopes.append(bound)
    return {"schema": "dynacomp.bound/1", "arithmetic": "rational",
            "bound": [str(x) for x in envelopes],
            "reduced_states": [[str(x) for x in z] for z in zs],
            "transition_residual": encoded(residual), "input_residual": encoded(forcing)}


def usable_horizon(bounds, tolerance):
    """Largest prefix whose every bound meets tolerance; -1 if t=0 fails."""
    tol = q(tolerance)
    if tol < 0:
        raise ValueError("Tolerance must be nonnegative")
    for t, b in enumerate(bounds):
        if q(b) > tol:
            return t-1
    return len(bounds)-1


def absolute_apply(a, radii):
    """Componentwise envelope |a x| <= |a| radii, if |x| <= radii."""
    radii = tuple(q(v) for v in radii)
    if len(a[0]) != len(radii) or any(v < 0 for v in radii):
        raise ValueError("Nonnegative radius vector with matching dimension required")
    return tuple(sum(abs(v)*r for v, r in zip(row, radii)) for row in a)


def box_horizon_bound(model, V, E, G, H, initial_center, initial_radius, input_radii):
    """Uniform output bound for a full initial-state box and arbitrary bounded inputs.

    Reduced initial state is E x0. Every input sequence satisfying the given
    componentwise bounds is covered, not only retained simulation traces.
    """
    v, e, g, h = (matrix(a) for a in (V, E, G, H))
    n, r = len(model.A), len(g)
    if len(v) != n or len(v[0]) != r or len(e) != r or len(e[0]) != n or len(g[0]) != r:
        raise ValueError("Expected V[n,r], E[r,n], G[r,r]")
    if len(h) != r or len(h[0]) != len(model.B[0]):
        raise ValueError("Expected H[r,m]")
    if mul(e, v) != identity(r):
        raise ValueError("Candidate must satisfy EV=I")
    center = tuple(q(x) for x in initial_center)
    radius = tuple(q(x) for x in initial_radius)
    if len(center) != n or len(radius) != n or any(x < 0 for x in radius):
        raise ValueError("Initial box must have n coordinates and nonnegative radii")
    us = [tuple(q(x) for x in u) for u in input_radii]
    if any(len(u) != len(model.B[0]) or any(x < 0 for x in u) for u in us):
        raise ValueError("Invalid input-radius vectors")
    residual = sub(mul(model.A, v), mul(v, g))
    forcing = sub(model.B, mul(v, h))
    initial_map = sub(identity(n), mul(v, e))
    initial_center_error = mv(initial_map, center)
    initial_radius_error = absolute_apply(initial_map, radius)
    zcenter = mv(e, center)
    zradius = absolute_apply(e, radius)
    zs = [tuple(abs(c)+a for c, a in zip(zcenter, zradius))]
    for u in us:
        zs.append(addv(absolute_apply(g, zs[-1]), absolute_apply(h, u)))
    # Store C A^k directly: output space can be much smaller than state space.
    ca = [model.C]
    for _ in us:
        ca.append(mul(ca[-1], model.A))
    envelopes = []
    for t in range(len(us)+1):
        values = addv(tuple(abs(x) for x in mv(ca[t], initial_center_error)),
                      absolute_apply(ca[t], initial_radius_error))
        for j in range(t):
            values = addv(values, absolute_apply(mul(ca[t-1-j], residual), zs[j]))
            values = addv(values, absolute_apply(mul(ca[t-1-j], forcing), us[j]))
        envelopes.append(values)
    return {"schema": "dynacomp.box-bound/1", "arithmetic": "rational",
            "coverage": "all initial states in the box and all inputs within componentwise radii",
            "bound": [str(vector_norm(v)) for v in envelopes],
            "output_bounds": [[str(x) for x in v] for v in envelopes],
            "reduced_state_radii": [[str(x) for x in v] for v in zs],
            "transition_residual": encoded(residual), "input_residual": encoded(forcing)}
