        return certify_sequential(*(spec[k] for k in ('E','G','H','D')),spec['initial_center'],spec['initial_radius'],spec['input_radii'],spec['tolerance'],spec.get('input_centers'))
    if kind == 'sequential_composition':
        return compose_sequential(compile_spec(spec['source']),spec['tolerance'])
    if kind == 'rational_gf':
        return RationalGF(spec['numerator'], spec['denominator']).packet()
    if kind == 'recurrence_gf':
        return from_recurrence(spec['coefficients'], spec['initial']).packet()
    if kind == 'state_gf':
        return from_state(spec['A'], spec['initial'], spec['C']).packet()
    if kind == 'binomial_tail':
        return binomial_tail(spec['alpha'], spec['argument'], spec['count'])
    if kind == 'rational_gf_tail':
        return RationalGF(spec['numerator'], spec['denominator']).tail(spec['argument'], spec['radius'], spec['count'])
    if kind == 'binary64_power':
        return power_certificate(spec['word'], spec['degree'])
    if kind == 'binary64_execution':
        return certify_execution(*(spec[k] for k in ('E','G','H','D')), spec['initial_center'],
                                 spec['initial_radius'], spec['input_radii'], spec['tolerance'], spec.get('input_centers'))
    if kind == 'machine_composition':
        return compose_execution(compile_spec(spec['source']), spec['tolerance'])
    if kind == "spectral_subset":
        return compress_spectral_modes(compile_spec(spec["source"]), spec["keep"], spec["tolerance"])
    if kind == "ramanujan_value":
        return ramanujan_value(spec["t"], spec.get("bits", 80))
    if kind == "spectral":
        return compile_spectral(spec["family"], spec["modes"], spec["tolerance"], spec.get("bits", 80))
    if kind == "spectral_composition":
        source = compile_spec(spec["source"])
        return compose_spectral(source, *(spec[k] for k in ("E", "G", "H", "D")),
                                spec["horizon"], spec["tolerance"], **spec.get("options", {}))
    if kind == "validated_box":
        return validated_box(SparseLinearModel.from_spec(spec['model']),spec['E'],spec['G'],spec['H'],spec['D'],spec['initial_center'],spec['initial_radius'],spec['input_radii'],spec['tolerance'],input_centers=spec.get('input_centers'),**spec.get('options',{}))
    if kind == "switching_enrichment":
        return switching_enrichment(spec["modes"], spec["C"], spec["initial_center"], spec["initial_radius"], spec["input_radii"], spec["tolerance"], input_centers=spec.get("input_centers"), **spec.get("options", {}))
    if kind == "uniform_enrichment":
        return uniform_enrichment(SparseLinearModel.from_spec(spec["model"]), spec["initial_center"], spec["initial_radius"], spec["input_radii"], spec["tolerance"], input_centers=spec.get("input_centers"), **spec.get("options", {}))
    if kind == "sparse_family":
        return compile_sparse_family(spec["modes"], spec["C"], spec.get("max_rank",128))
    if kind == "linear":
        return compile_linear(LinearModel.from_rows(spec["A"], spec["B"], spec["C"])).packet()
    if kind == "memory":
        return compile_output_memory(LinearModel.from_rows(spec["A"], spec["B"], spec["C"]))
    if kind == "family":
        return compile_family([LinearModel.from_rows(item["A"], item["B"], spec["C"]) for item in spec["coefficients"]])
    if kind == "adaptive":
        model = LinearModel.from_rows(spec["A"], spec["B"], spec["C"])
        return adaptive_coordinates(model, spec["initial_center"], spec["initial_radius"],
                                    spec["input_radii"], spec["tolerance"], **spec.get("options", {}))
    if kind == "finite":
        return compile_finite(FiniteModel(tuple(spec["observations"]), tuple(tuple(r) for r in spec["transitions"])))
    if kind == "polynomial":
        n = spec["variables"]
        update = [unpack(p, n) for p in spec["update"]]
        targets = [unpack(p, n) for p in spec["targets"]]
        if len(update) != n:
            raise ValueError("Update count must match variables")
        return compile_polynomial(update, targets, **spec.get("limits", {}))
    if kind == "sparse":
        op = SparseOperator.from_entries(spec["n"], spec["entries"])
        return compile_sparse(op, spec["B"], spec["C"], spec.get("max_rank", 128))
    if kind == "controlled_polynomial":
        n, k = spec["variables"], spec["inputs"]
        update = [unpack(p, n+k) for p in spec["update"]]
        targets = [unpack(p, n) for p in spec["targets"]]
        if len(update) != n:
            raise ValueError("Update count must match variables")
        return compile_controlled_polynomial(update, targets, k, **spec.get("limits", {}))
    if kind == "realization":
        return minimal_realization(LinearModel.from_rows(spec["A"], spec["B"], spec["C"]))
    if kind == "switched":
        return compile_switched(spec["modes"], spec["C"], spec.get("inputs"))
    if kind == "automaton":
        return minimize_automaton(WeightedAutomaton.from_spec(spec))
    if kind == "equivalence":
        return check_equivalence(WeightedAutomaton.from_spec(spec["first"]),
                                 WeightedAutomaton.from_spec(spec["second"]))
    if kind == "parametric":
        return parametric_analysis(spec["A"], spec["B"], spec["C"])
    if kind == "enrichment":
        model = LinearModel.from_rows(spec["A"], spec["B"], spec["C"])
        scenarios = [(s["x0"], s["inputs"]) for s in spec["scenarios"]]
        return greedy_enrichment(model, scenarios, spec["tolerance"], spec.get("max_dimension"))
    if kind == "stability":
        if spec.get("time", "discrete") == "continuous":
            return continuous_certificate(spec["A"])
        return quadratic_certificate(spec["A"])
    if kind == "common_quadratic":
        return common_quadratic_certificate(spec["modes"])
    if kind == "all_time":
        return all_time_enrichment(SparseLinearModel.from_spec(spec["model"]), spec["initial_center"],
                                   spec["initial_radius"], spec["input_center"], spec["input_radius"],
                                   spec["tolerance"], spec.get("max_rank"))
    if kind == "zonotope":
        model = SparseLinearModel.from_spec(spec["model"])
        v, e, g, h, _ = _project(model, spec["encoder"])
        return sharp_zonotope_bound(model, v, e, g, h, spec["x0_center"], spec["input_centers"], spec["generators"])
    raise ValueError("Unknown model kind")


def replay(packet):
    if packet.get('schema') == 'dynacomp.sequential-binary64/1':
        return replay_sequential(packet)
    if packet.get('schema') == 'dynacomp.sequential-composition/1':
        return replay_sequential_composition(packet)
    if packet.get('schema') in ('exact.rational-gf/1','exact.rational-gf-tail/1','exact.binomial-tail/1'):
        return replay_generating(packet)
    if packet.get('schema') == 'exact.binary64-power/1':
        return replay_power(packet)
    if packet.get('schema') == 'dynacomp.binary64-execution/1':
        return replay_execution(packet)
    if packet.get('schema') == 'dynacomp.machine-composition/1':
        return replay_machine_composition(packet)
    if packet.get("schema") == "dynacomp.spectral-subset/1":
        return replay_spectral_subset(packet)
    if packet.get("schema") == "dynacomp.ramanujan-value/1":
        return replay_ramanujan_value(packet)
    if packet.get("schema") == "dynacomp.spectral/1":
        return replay_spectral(packet)
    if packet.get("schema") == "dynacomp.spectral-composition/1":
        return replay_spectral_composition(packet)
    readers = {"dynacomp.validated-box/1":replay_validated,"dynacomp.switching-enrichment/1": replay_switching, "dynacomp.uniform-enrichment/1": replay_uniform,
               "dynacomp.sparse-family/1": replay_sparse_family, "dynacomp.linear/1": replay_linear, "dynacomp.finite/1": replay_finite,
               "dynacomp.polynomial/1": replay_polynomial, "dynacomp.sparse/1": replay_sparse,
               "dynacomp.controlled_polynomial/1": replay_controlled_polynomial,
               "dynacomp.realization/1": replay_realization, "dynacomp.switched/1": replay_switched,
               "dynacomp.automaton/1": replay_automaton, "dynacomp.equivalence/1": replay_equivalence,
               "dynacomp.parametric/1": replay_parametric, "dynacomp.enrichment/1": replay_enrichment,
               "dynacomp.family/1": replay_family, "dynacomp.memory/1": replay_memory,
               "dynacomp.adaptive/1": replay_adaptive,
               "dynacomp.quadratic-metric/1": replay_quadratic, "dynacomp.continuous-metric/1": replay_continuous,
               "dynacomp.common-quadratic/1": replay_common_quadratic, "dynacomp.all-time-bound/1": replay_all_time,
               "dynacomp.zonotope-bound/1": replay_zonotope}
    if packet.get("schema") not in readers:
        raise ValueError("Unknown or unsuccessful packet")
    return readers[packet["schema"]](packet)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("operation", choices=["compile", "replay"])
    parser.add_argument("input", type=Path)
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()
    try:
        data = json.loads(args.input.read_text())
        result = compile_spec(data) if args.operation == "compile" else {"accepted": replay(data)}
    except (ValueError, KeyError, TypeError, OverflowError, OSError) as exc:
        parser.exit(2, f"dynacomp: {exc}\n")
    text = json.dumps(result, indent=2) + "\n"
    if args.output:
        args.output.write_text(text)
    else:
        print(text, end="")


if __name__ == "__main__":
    main()
","dynacomp/enclosures.py":""""Small outward rational enclosures; no floating special-function oracle.

These routines bound real constants, not runtime floating-point evaluation.
Taylor remainders and integer square roots supply the endpoint inequalities.
"""
from fractions import Fraction
from math import isqrt
from .rational import q


def precision(bits):
    if type(bits) is not int or not 16 <= bits <= 512:
        raise ValueError("Precision must be an integer in [16,512]")
    return 1 << bits


def outward(lo, hi, bits):
    scale = precision(bits)
    lo, hi = q(lo), q(hi)
    if lo > hi:
        raise ValueError("Reversed interval")
    return (Fraction((lo*scale).__floor__(), scale),
            Fraction((hi*scale).__ceil__(), scale))


def sqrt_integer(n, bits=80):
    scale = precision(bits)
    if type(n) is not int or n < 0:
        raise ValueError("Nonnegative integer radicand required")
    root = isqrt(n*scale*scale)
    return Fraction(root, scale), Fraction(root+int(root*root != n*scale*scale), scale)


def log_rational(x, bits=80):
    """Positive rational logarithm, reduced to atanh arguments <= 1/3."""
    precision(bits)
    x = q(x)
    if x <= 0:
        raise ValueError("Positive logarithm argument required")
    if x < 1:
        lo, hi = log_rational(1/x, bits)
        return -hi, -lo
    exponent = x.numerator.bit_length()-x.denominator.bit_length()
    if x < 2**exponent:
        exponent -= 1
    reduced = x / (2**exponent)

    def series(value):
        z = (value-1)/(value+1)
        power = z
        total = Fraction(0)
        for j in range(bits+8):
            total += 2*power/(2*j+1)
            power *= z*z
            remainder = 2*power/((2*j+3)*(1-z*z))
            if remainder <= Fraction(1, 1 << (bits+8)):
                break
        return total, total+remainder

    a, b = series(Fraction(2))
    c, d = series(reduced)
    return outward(exponent*a+c, exponent*b+d, bits)


def pi_interval(bits=80):
    """Machin's identity and the alternating arctangent remainder."""
    precision(bits)

    def atan_inverse(n):
        x = Fraction(1, n)
        total = Fraction(0)
        power = x
        for j in range(bits+8):
            total += (-1)**j*power/(2*j+1)
            power *= x*x
            next_term = (-1)**(j+1)*power/(2*j+3)
            if abs(next_term) <= Fraction(1, 1 << (bits+8)):
                break
        return min(total, total+next_term), max(total, total+next_term)

    a, b = atan_inverse(5)
    c, d = atan_inverse(239)
    return outward(16*a-4*d, 16*b-4*c, bits)


def exp_negative(x, bits=80):
    """Enclose exp(-x), x >= 0, by alternating Taylor and squaring."""
    precision(bits)
    x = q(x)
    if x < 0:
        raise ValueError("Nonnegative exponential argument required")
    if not x:
        return Fraction(1), Fraction(1)
    squarings = 0
    while x > Fraction(1, 2):
        x /= 2
        squarings += 1
    # Extra guard bits control outward errors through repeated squaring.
    work = bits+squarings.bit_length()+8
    # Public precision limit is independent of this internal guard budget.
    scale = 1 << work
    total = Fraction(1)
    term = Fraction(1)
    for j in range(1, bits+16):
        term *= -x/j
        total += term
        next_term = term*(-x)/(j+1)
        if abs(next_term) <= Fraction(1, scale):
            break
    lo, hi = min(total, total+next_term), max(total, total+next_term)
    for _ in range(squarings):
        lo = Fraction((lo*lo*scale).__floor__(), scale)
        hi = Fraction((hi*hi*scale).__ceil__(), scale)
    return outward(max(Fraction(0), lo), min(Fraction(1), hi), bits)
","dynacomp/engineering.py":""""Exact descriptor elimination and replayable ZOH/coefficient/output bounds.

Engineering feedthrough F is distinct from the reduction's output matrix D.
Outputs use u[t] at t<T and the last held input at the terminal sample.
"""
from fractions import Fraction as Q
from .rational import matrix, mul, inverse, identity, encoded, norm_inf, q
from .machine import _up, U, ETA, LIMIT
from .native import sequential_budget


def standardize(a,b,e):
    n=len(a)
    if e == identity(n): return a,b
    if all(not e[i][j] for i in range(n) for j in range(n) if i!=j):
        if any(not e[i][i] for i in range(n)): raise ValueError('Singular descriptor mass E')
        return tuple(tuple(v/e[i][i] for v in row) for i,row in enumerate(a)),tuple(tuple(v/e[i][i] for v in row) for i,row in enumerate(b))
    if n>32: raise ValueError('General descriptor exact elimination supports at most 32 states; diagonal E has no such limit')
    inv=inverse(e)
    return mul(inv,a),mul(inv,b)


def descriptor_transform(a,b,e,candidate=None):
    """Exact solve, or strict row dominance plus an exact residual bound.

    ||E^-1||inf <= 1/min_i(|Eii|-sum_j!=i |Eij|) by the
    maximum-component argument. This proves nonsingularity independently
    of the numerical solve used only to propose stored coefficients.
    """
    n=len(a)
    diagonal=all(not e[i][j] for i in range(n) for j in range(n) if i!=j)
    if n<=32 or diagonal:
        sa,sb=standardize(a,b,e)
        if candidate is not None and candidate!=(sa,sb): raise ValueError('Exact descriptor coefficients do not replay')
        return sa,sb,{'status':'exact','A_error_inf':'0','B_error_inf':'0'}
    margin=min(abs(e[i][i])-sum(abs(v) for j,v in enumerate(row) if i!=j) for i,row in enumerate(e))
    if margin<=0: raise ValueError('Unsupported descriptor: above 32 states require diagonal E or strict row diagonal dominance; singular systems are not approximated')
    if n>256: raise ValueError('Residual-certified descriptor solve limited to 256 states')
    if candidate is None:
        import numpy as np
        from scipy.linalg import solve
        stored=solve(np.asarray(e,dtype=float),np.asarray([ar+br for ar,br in zip(a,b)],dtype=float))
        if not np.isfinite(stored).all(): raise ValueError('Descriptor solve produced nonfinite values')
        candidate=(matrix([[str(Q(float(v))) for v in row[:n]] for row in stored]),
                   matrix([[str(Q(float(v))) for v in row[n:]] for row in stored]))
    sa,sb=candidate
    if len(sa)!=n or len(sa[0])!=n or len(sb)!=n or len(sb[0])!=len(b[0]): raise ValueError('Descriptor candidate dimensions differ')
    def residual(stored,target):
        # Sparse source rows avoid cubic work for banded engineering masses.
        columns=tuple(zip(*stored))
        return max(sum(abs(sum(v*col[j] for j,v in enumerate(row) if v)-wanted) for col,wanted in zip(columns,tr)) for row,tr in zip(e,target))
    da,db=residual(sa,a)/margin,residual(sb,b)/margin
    return sa,sb,{'status':'bounded','A_error_inf':str(_up(da)),'B_error_inf':str(_up(db)),
                  'method':'strict row diagonal dominance and exact rational solve residuals','mass_dominance_margin':str(margin)}


def enclosure(a,b,dt,stored_a,stored_b):
    """Taylor polynomial in Q; infinity-norm tail from a geometric majorant.

    For rho=||M||inf, k+2>rho bounds the tail after k by
    rho^(k+1)/(k+1)! /(1-rho/(k+2)). No floating proof arithmetic.
    """
    n,m=len(a),len(b[0]); size=n+m
    if size>12: return {'status':'uncertified','reason':'verified Taylor enclosure limited to augmented dimension 12'}
    z=matrix([[dt*v for v in a[i]+b[i]] if i<n else [0]*size for i in range(size)])
    rho=norm_inf(z)
    if rho>8: return {'status':'uncertified','reason':'verified Taylor enclosure requires augmented infinity norm <= 8'}
    term=identity(size); total=term; scalar=Q(1)
    for k in range(1,161):
        term=tuple(tuple(v/k for v in row) for row in mul(term,z))
        total=tuple(tuple(x+y for x,y in zip(row,other)) for row,other in zip(total,term))
        scalar=scalar*rho/k
        if k+2>rho:
            tail=scalar*rho/(k+1)/(1-rho/Q(k+2))
            if tail<=Q(1,1<<100): break
    else: return {'status':'uncertified','reason':'Taylor enclosure work limit'}
    error_a=norm_inf(tuple(tuple(abs(total[i][j]-stored_a[i][j]) for j in range(n)) for i in range(n)))+tail
    error_b=norm_inf(tuple(tuple(abs(total[i][n+j]-stored_b[i][j]) for j in range(m)) for i in range(n)))+tail
    return {'status':'bounded','terms':k,'tail_inf':str(_up(tail)),
            'A_error_inf':str(_up(error_a)),'B_error_inf':str(_up(error_b)),
            'method':'exact rational Taylor polynomial and geometric tail; includes stored coefficient discrepancy'}


def replay_import(spec):
    binding=spec.get('import_certificate')
    if binding is None: return None
    if binding.get('schema')!='dynacomp.engineering-import/1': raise ValueError('Unknown import certificate')
    a,b,c,e,f=map(matrix,(binding[k] for k in ('A','B','C','E','F')))
    n,m,p=len(a),len(b[0]),len(c)
    if len(a[0])!=n or len(b)!=n or len(c[0])!=n or len(e)!=n or len(e[0])!=n or len(f)!=p or len(f[0])!=m: raise ValueError('Import certificate dimensions differ')
    stored_a,stored_b=map(matrix,(spec['model'][k] for k in ('A','B')))
    candidate=tuple(map(matrix,(binding[k] for k in ('standard_A','standard_B')))) if 'standard_A' in binding else None
    sa,sb,descriptor=descriptor_transform(a,b,e,candidate)
    if descriptor!=binding.get('descriptor',descriptor): raise ValueError('Descriptor elimination bound does not replay')
    divisor=q(binding['output_divisor'])
    if divisor<=0: raise ValueError('Positive output divisor required')
    expected_c=tuple(tuple(v/divisor for v in row) for row in c)
    expected_f=tuple(tuple(v/divisor for v in row) for row in f)
    if matrix(spec['model']['C'])!=expected_c or matrix(spec['feedthrough'])!=expected_f: raise ValueError('Original outputs or units changed')
    dt=binding['sampling_interval']
    if dt is None:
        if (stored_a,stored_b)!=(sa,sb): raise ValueError('Descriptor source identities do not replay')
        certificate=descriptor
    else:
        dt=q(dt)
        if dt<=0: raise ValueError('Positive sampling interval required')
        certificate=enclosure(sa,sb,dt,stored_a,stored_b)
        if descriptor['status']!='exact':
            certificate={'status':'uncertified','reason':'continuous sampling after residual-bounded descriptor elimination is not yet enclosed'}
    if certificate!=binding['transformation']: raise ValueError('Import transformation enclosure does not replay')
    return certificate


def output_contract(spec,model,domain,packet=None):
    """Uniform imported-source + feedthrough execution budgets, time matched."""
    from .binary64 import round_bits, exact, classify
    cert=replay_import(spec)
    n,m,p=model.operator.n,len(model.B[0]),len(model.C)
    f=matrix(spec.get('feedthrough',[[0]*m for _ in range(p)]))
    if len(f)!=p or len(f[0])!=m: raise ValueError('Feedthrough must have shape [outputs,inputs]')
    if spec.get('output_input_semantics','right-continuous-terminal-hold')!='right-continuous-terminal-hold': raise ValueError('Unsupported output input semantics')
    center,radius,radii,means=domain
    if any(v for row in f for v in row) and not radii: raise ValueError('Feedthrough requires at least one held input')
    words=[[round_bits(v) for v in row] for row in f]
    if any(classify(v)=='infinity' for row in words for v in row): raise ValueError('Feedthrough loading overflows')
    loaded=tuple(tuple(exact(v) for v in row) for row in words)
    x=max(abs(c)+r for c,r in zip(center,radius)); error=Q(0)
    a=[[Q(0)]*n for _ in range(n)]
    for i,j,v in model.operator.entries:a[i][j]=v
    anorm=norm_inf(a); bnorm=norm_inf(model.B)
    da=q(cert.get('A_error_inf','0')) if cert else Q(0)
    db=q(cert.get('B_error_inf','0')) if cert else Q(0)
    bounded=cert is None or cert['status']!='uncertified'
    rows=[]; imports=[]
    for t in range(len(radii)+1):
        ub=tuple(abs(c)+r for c,r in zip(means[min(t,len(radii)-1)],radii[min(t,len(radii)-1)])) if radii else (Q(0),)*m
        out=[]; imp=[]
        for j,(row,hat,crow) in enumerate(zip(f,loaded,model.C)):
            imported=_up(sum(abs(v) for v in crow)*error); imp.append(str(imported))
            # Exact zero feedthrough preserves the original engine and budget.
            extra=Q(0)
            if any(row) and packet is not None:
                magnitude=sum(abs(v)*u for v,u in zip(hat,ub))
                ferr=sum(abs(v-w)*u for v,w,u in zip(row,hat,ub))+sequential_budget(magnitude,m)
                base=sum(abs(v)*x for v in crow)+q(packet['combined_output_upper'][t][j])
                total=base+magnitude+ferr
                add=U*total+ETA
                if total+add>LIMIT: raise ValueError('Cannot exclude feedthrough addition overflow')
                extra=_up(ferr+add)
            out.append(str(_up(imported+extra)))
        rows.append(out); imports.append(imp)
        if t<len(radii):
            u=max(abs(c)+r for c,r in zip(means[t],radii[t]))
            error=_up((anorm+da)*error+da*x+db*u)
            x=_up(anorm*x+bnorm*u)
    return {'schema':'dynacomp.engineering-output/1','feedthrough_words':words,'additional_output_upper':rows,
            'import_output_upper':imports,'engineering_import_bounded':bounded,
            'continuous_sampling_bounded':bounded if cert and spec['import_certificate']['sampling_interval'] is not None else None,
            'reference':('continuous ZOH samples' if spec['import_certificate']['sampling_interval'] is not None else 'original discrete descriptor') if cert and bounded else 'exact stored discrete coefficients',
            'semantics':'right-continuous-terminal-hold'}


class EngineeringRunner:
    """Checked base runtime plus separate sequential feedthrough dot and add."""
    def __init__(self,runner,contract,certified=True):
        import numpy as np
        from .binary64 import from_bits
        self.runner=runner; self.f=np.ascontiguousarray([[from_bits(v) for v in row] for row in contract['feedthrough_words']],dtype=np.float64); self.certified=certified
        self.f.flags.writeable=False
    def simulate(self,initial,inputs):
        import numpy as np
        output=self.runner.simulate(initial,inputs)
        if not np.any(self.f): return output
        u=np.asarray(inputs,dtype=np.float64)
        if self.certified:
            import ctypes
            from .native import _library
            u=np.ascontiguousarray(u)
            pointer=ctypes.POINTER(ctypes.c_double)
            status=_library().feedthrough(self.f.shape[1],self.f.shape[0],len(u),u.shape[2],
                *(v.ctypes.data_as(pointer) for v in (self.f,u,output)))
            if status: raise RuntimeError('Native feedthrough refused floating environment')
        else:
            for t in range(len(output)):
                output[t]=output[t]+self.f@u[min(t,len(u)-1)]
        if not np.isfinite(output).all(): raise OverflowError('Nonfinite engineering output')
        return output
","dynacomp/enrich.py":""""Certified greedy enrichment of approximate linear reductions.

Start from the target directions, project the dynamics, and certify every
scenario with the exact rational envelope of ``bounds.finite_horizon_bound``.
While a certified bound exceeds the tolerance, add the full-state error
snapshot whose future is most visible to the target. Each accepted step is a
proof for the supplied scenarios, not a training-set fit. Because the lift
can grow to the full space, where all residuals vanish, the loop always ends.
"""
from .bounds import finite_horizon_bound
from .krylov import Echelon
from .rational import matrix, sub, mul, transpose, inverse, mv, addv, q, vector_norm, encoded, row_basis


def _project(model, columns):
    """Orthogonal projector over Q: W = (V^T V)^(-1) V^T, G = WAV, H = WB."""
    v = transpose(columns)
    w = mul(inverse(mul(columns, v)), columns)
    return v, w, mul(mul(w, model.A), v), mul(w, model.B)


def _trajectory(model, x0, inputs):
    xs = [tuple(q(x) for x in x0)]
    for u in inputs:
        xs.append(addv(mv(model.A, xs[-1]), mv(model.B, u)))
    return xs


def _visibility(model, e, horizon):
    """Target-weighted size of an error direction: sum_k |C A^k e| for k <= horizon."""
    total, x = q(0), e
    for _ in range(horizon+1):
        total += vector_norm(mv(model.C, x))
        x = mv(model.A, x)
    return total


def simplify_direction(e, denominator):
    """Scale to unit max-norm and round to small denominators.

    Soundness does not depend on which rational lift is used: the envelope is
    recomputed exactly for whatever V results. Rounding only controls growth.
    """
    if not denominator:
        return e
    scale = vector_norm(e)
    return tuple((x/scale).limit_denominator(denominator) for x in e)


def greedy_enrichment(model, scenarios, tolerance, max_dimension=None, lookahead=None, denominator=64):
    """Grow a lift until every scenario's certified output envelope meets tolerance.

    scenarios: [(x0, inputs)]. ``denominator`` bounds the entries of each added
    direction (None keeps exact snapshots). Returns the final reduced model, the per-round
    worst certified bounds, and status "certified" or "budget_exhausted".
    """
    tol = q(tolerance)
    n = len(model.A)
    budget = n if max_dimension is None else min(n, max_dimension)
    horizon = lookahead if lookahead is not None else min(n, max(len(u) for _, u in scenarios))
    columns = list(row_basis(model.C))
    if len(columns) > budget:
        raise ValueError("Budget is smaller than the number of independent targets")
    trajectories = [_trajectory(model, x0, inputs) for x0, inputs in scenarios]
    history = []
    while True:
        v, w, g, h = _project(model, tuple(columns))
        worst, certificates, candidates = q(0), [], []
        for (x0, inputs), xs in zip(scenarios, trajectories):
            z0 = mv(w, xs[0])
            cert = finite_horizon_bound(model, v, g, h, {"full": xs[0], "reduced": z0}, inputs)
            certificates.append(cert)
            worst = max([worst] + [q(b) for b in cert["bound"]])
            z = z0
            for t, x in enumerate(xs):
                error = tuple(a-b for a, b in zip(x, mv(v, z)))
                if any(error):
                    candidates.append(error)
                if t < len(inputs):
                    z = addv(mv(g, z), mv(h, inputs[t]))
        history.append({"dimension": len(columns), "worst_certified_bound": str(worst),
                        "approximately": f"{float(worst):.6g}"})
        if worst <= tol:
            status = "certified"
            break
        if len(columns) >= budget:
            status = "budget_exhausted"
            break
        span = Echelon()
        for c in columns:
            span.add(c)
        # Residual directions cover bounds driven by A V - V G when snapshots agree.
        candidates += list(transpose(sub(mul(model.A, v), mul(v, g))))
        ranked = sorted(candidates, key=lambda e: (_visibility(model, e, horizon), vector_norm(e)), reverse=True)
        chosen = next((s for s in (simplify_direction(e, denominator) for e in ranked)
                       if any(span.reduce(s))), None)
        if chosen is None:
            chosen = next(tuple(int(i == j) for i in range(n)) for j in range(n)
                          if any(span.reduce(tuple(int(i == j) for i in range(n)))))
        columns.append(chosen)
    return {"schema": "dynacomp.enrichment/1", "status": status, "tolerance": str(tol),
            "full_dimension": n, "reduced_dimension": len(columns),
            "V": encoded(v), "W": encoded(w), "G": encoded(g), "H": encoded(h),
            "A": encoded(model.A), "B": encoded(model.B), "C": encoded(model.C),
            "scenarios": [{"x0": [str(x) for x in x0], "inputs": encoded(inputs) if inputs else []}
                          for x0, inputs in scenarios],
            "history": history, "certificates": [c["bound"] for c in certificates],
            "claim": "rational output-error envelopes for the supplied scenarios only"}


def replay_enrichment(packet):
    """Recompute every envelope from the stored lift; no greedy search is rerun."""
    from .linear import LinearModel
    from .rational import identity
    if packet.get("schema") != "dynacomp.enrichment/1":
        raise ValueError("Unknown schema")
    model = LinearModel.from_rows(packet["A"], packet["B"], packet["C"])
    v, w, g, h = (matrix(packet[k]) for k in ("V", "W", "G", "H"))
    if mul(w, v) != identity(len(g)):
        raise ValueError("W is not a left inverse of V")
    if mul(mul(w, model.A), v) != g or mul(w, model.B) != h:
        raise ValueError("Reduced matrices are not the stated projection")
    tol, worst = q(packet["tolerance"]), q(0)
    if len(packet["certificates"]) != len(packet["scenarios"]):
        raise ValueError("One certificate per scenario required")
    for scenario, stored in zip(packet["scenarios"], packet["certificates"]):
        x0 = tuple(q(x) for x in scenario["x0"])
        cert = finite_horizon_bound(model, v, g, h, {"full": x0, "reduced": mv(w, x0)}, scenario["inputs"])
        if cert["bound"] != stored:
            raise ValueError("Stored envelope does not match recomputation")
        worst = max([worst] + [q(b) for b in stored])
    if packet["status"] == "certified" and worst > tol:
        raise ValueError("Certified status but an envelope exceeds tolerance")
    return True
","dynacomp/explorer.py":""""Plain-language scenario adapter for the web/mobile explorer.

Real DynaComp rational compilation and replay drive the comparison. Illustrative
room/supply models are explicitly labelled; they are not fitted customer models.
"""
from fractions import Fraction
from .linear import LinearModel, compile_linear, replay_linear
from .adaptive import adaptive_coordinates, replay_adaptive
from .rational import q, mv, addv, matrix, encoded


def _number(value, lo, hi):
    if isinstance(value, bool):
        raise ValueError('A number is required')
    value = Fraction(str(value))
    if not lo <= value <= hi:
        raise ValueError('The setting is outside its supported range')
    return value


def scenario(request):
    kind = request.get('example', 'warmth')
    if kind not in ('warmth', 'supplies', 'custom'):
        raise ValueError('Choose warmth, supplies, or your own model')
    step_value = _number(request.get('steps', 16), 1, 40)
    if step_value.denominator != 1:
        raise ValueError('Choose a whole number of steps')
    steps = int(step_value)
    start = _number(request.get('start', 20), -100, 1000)
    strength = _number(request.get('strength', 2), -20, 20)
    tolerance = _number(request.get('tolerance', 0), 0, 100)
    output = request.get('output', 'whole')
    if output not in ('whole', 'one'):
        raise ValueError('Choose the whole system or one place')
    feedthrough = None
    descriptor = None
    if kind == 'custom':
        workload = request['model']
        supplied = workload.get('model', workload)
        if any(key in supplied for key in ('time', 'sample_period')):
            raise ValueError('Open a prepared sampled model here. Continuous-time preparation uses the full downloadable DynaComp package.')
        n = len(supplied['A'])
        if not 1 <= n <= 12:
            raise ValueError('The interactive workspace supports 1–12 model values')
        a, b = supplied['A'], supplied['B']
        if 'E' in supplied:
            from .engineering import descriptor_transform
            a, b, descriptor = descriptor_transform(matrix(a), matrix(b), matrix(supplied['E']))
            if descriptor['status'] != 'exact':
                raise ValueError('This interactive workspace requires exact descriptor elimination')
        model = LinearModel.from_rows(a, b, supplied['C'])
        f = workload.get('feedthrough', supplied.get('D'))
        if f is not None:
            feedthrough = matrix(f)
            if len(feedthrough) != len(model.C) or len(feedthrough[0]) != len(model.B[0]):
                raise ValueError('The direct-output inputs do not match the model')
        if len(model.B[0]) > 4 or len(model.C) > 4:
            raise ValueError('Use at most four inputs and outputs in this workspace')
        initial = tuple(q(x) for x in supplied.get('initial', workload.get('initial_center', [str(start)] * n)))
        inputs = [tuple(q(x) for x in u) for u in supplied.get('inputs', [[str(strength)] * len(model.B[0])] * steps)]
        if any(len(u) != len(model.B[0]) for u in inputs):
            raise ValueError('The input values do not match the model')
        if len(inputs) > 40:
            raise ValueError('Use at most forty updates in this workspace')
        title, unit = 'Your model', supplied.get('unit', 'output units')
    else:
        n = 6
        a = [[Fraction(0) for _ in range(n)] for _ in range(n)]
        for i in range(n):
            a[i][i] = Fraction(3, 4) if kind == 'warmth' else Fraction(7, 8)
            a[i][(i - 1) % n] = Fraction(1, 16)
            a[i][(i + 1) % n] = Fraction(1, 16)
        c = [[Fraction(1, n)] * n] if output == 'whole' else [[int(i == 0) for i in range(n)]]
        model = LinearModel.from_rows(a, [[Fraction(1, 4)] for _ in range(n)], c)
        initial = tuple(start + Fraction(i - 2, 4) for i in range(n))
        inputs = [(strength if t < steps // 2 else strength / 2,) for t in range(steps)]
        title, unit = ('Warmth across six connected rooms', 'illustrative temperature units') if kind == 'warmth' else ('Supplies across six connected places', 'illustrative stock units')
    if len(initial) != n:
        raise ValueError('The starting values do not match the model')
    exact = compile_linear(model)
    packet = exact.packet()
    replay_linear(packet)
    reduced = exact.simulate(initial, inputs)
    bound = [Fraction(0)] * (len(inputs) + 1)
    rank, method, accepted = len(exact.E), 'exact output-preserving reduction', True
    if tolerance > 0:
        # Bound a box around the supplied initial values and all inputs up to
        # each displayed magnitude. The nominal run is one member of that box.
        adaptive = adaptive_coordinates(model, initial, [0] * n,
                    [[str(abs(v)) for v in u] for u in inputs], str(tolerance),
                    initial_coordinates=[max(range(n), key=lambda i: sum(abs(row[i]) for row in model.C))])
        replay_adaptive(adaptive)
        if adaptive['status'] == 'tolerance_met' and len(adaptive['candidate']['selected']) < rank:
            packet = adaptive
            candidate = adaptive['candidate']
            z = mv(matrix(candidate['E']), initial)
            reduced = [mv(matrix(candidate['D']), z)]
            for u in inputs:
                z = addv(mv(matrix(candidate['G']), z), mv(matrix(candidate['H']), u))
                reduced.append(mv(matrix(candidate['D']), z))
            rank = len(candidate['selected'])
            bound = [q(x) for x in adaptive['box_bound']['bound']]
            method = 'bounded approximate reduction'
    x = initial
    full = [mv(model.C, x)]
    for u in inputs:
        x = addv(mv(model.A, x), mv(model.B, u))
        full.append(mv(model.C, x))
    if feedthrough is not None:
        zero = (q(0),) * len(model.B[0])
        # Same right-continuous terminal-hold convention as the engineering
        # importer: y_t=C x_t + F u_t, holding the final input at the last sample.
        direct = [mv(feedthrough, inputs[t] if t < len(inputs) else inputs[-1] if inputs else zero) for t in range(len(full))]
        full = [addv(y, d) for y, d in zip(full, direct)]
        reduced = [addv(y, d) for y, d in zip(reduced, direct)]
    differences = [max(abs(a - b) for a, b in zip(f, r)) for f, r in zip(full, reduced)]
    if any(d > b for d, b in zip(differences, bound)):
        raise AssertionError('The actual trajectory escaped its error bound')
    return {'schema': 'dynacomp.explorer-run/1', 'title': title, 'unit': unit,
            'original_values': n, 'retained_values': rank, 'method': method,
            'tolerance': str(tolerance), 'max_error_bound': str(max(bound)),
            'max_actual_difference': str(max(differences)), 'accepted': accepted,
            'scope': 'Exact rational computation for the supplied sampled model and displayed finite horizon. Illustrative scenarios are not customer measurements.',
            'request': request, 'full': [[str(v) for v in row] for row in full],
            'reduced': [[str(v) for v in row] for row in reduced],
            'error_bound': [str(v) for v in bound], 'certificate': packet,
            'descriptor': descriptor, 'feedthrough': encoded(feedthrough) if feedthrough is not None else None,
            'output_input_semantics': 'right-continuous-terminal-hold',
            'measurement_and_continuous_sampling_errors': 'not covered by the displayed model-reduction bound'}
","dynacomp/families.py":""""Common exact quotients for coefficient families and switching systems."""
from .linear import LinearModel, compile_linear
from .rational import matrix, row_basis, mul, coordinates, encoded, q, transpose, inverse, sub


def compile_family(models):
    models = tuple(models)
    if not models:
        raise ValueError("Nonempty coefficient family required")
    first = models[0]
    n, m = len(first.A), len(first.B[0])
    if any(len(model.A) != n or len(model.B[0]) != m or model.C != first.C for model in models):
        raise ValueError("Models must share dimensions and target")
    e = row_basis(first.C)
    if not e:
        raise ValueError("Need nonzero target")
    ranks = [len(e)]
    while True:
        rows = e + tuple(row for model in models for row in mul(e, model.A))
        enlarged = row_basis(rows)
        if len(enlarged) == len(e):
            break
        e = enlarged
        ranks.append(len(e))
    return {"schema": "dynacomp.family/1", "E": encoded(e),
            "D": encoded([coordinates(row, e) for row in first.C]), "C": encoded(first.C),
            "A": [encoded(model.A) for model in models], "B": [encoded(model.B) for model in models],
            "G": [encoded([coordinates(row, e) for row in mul(e, model.A)]) for model in models],
            "H": [encoded(mul(e, model.B)) for model in models], "ranks": ranks,
            "coverage": "arbitrary linear coefficient combinations, including time-varying coefficients"}


def replay_family(packet):
    if packet.get("schema") != "dynacomp.family/1":
        raise ValueError("Unknown schema")
    from .linear import replay_linear
    count = len(packet["A"])
    if not count or any(len(packet[k]) != count for k in ("B", "G", "H")):
        raise ValueError("Family counts disagree")
    for i in range(count):
        replay_linear({"schema": "dynacomp.linear/1", "A": packet["A"][i], "B": packet["B"][i],
                       "C": packet["C"], "E": packet["E"], "D": packet["D"],
                       "G": packet["G"][i], "H": packet["H"][i]})
    return True


def closure_conditions(A_coefficients, E):
    """Exact affine equations for where a fixed row encoding closes.

    A(theta)=A0+theta1*A1+... . Each returned equation is a coefficient
    list [constant,theta1,...] required to vanish. No sampling is involved.
    """
    coeffs = [matrix(a) for a in A_coefficients]
    e = matrix(E)
    if not coeffs or any(len(a) != len(e[0]) or len(a[0]) != len(e[0]) for a in coeffs):
        raise ValueError("Square coefficient operators with matching encoder required")
    et = transpose(e)
    v = mul(et, inverse(mul(e, et)))
    defects = []
    for a in coeffs:
        ea = mul(e, a)
        defects.append(sub(ea, mul(mul(ea, v), e)))
    equations = []
    for i in range(len(e)):
        for j in range(len(e[0])):
            equation = tuple(d[i][j] for d in defects)
            if any(equation) and equation not in equations:
                equations.append(equation)
    return {"equations": [[str(v) for v in row] for row in equations],
            "parameters": len(coeffs)-1, "meaning": "every affine equation must vanish for closure"}


def specialize(coefficients, parameters):
    matrices = [matrix(a) for a in coefficients]
    values = [q(1)]+[q(v) for v in parameters]
    if not matrices or len(values) != len(matrices):
        raise ValueError("Coefficient count must be one plus parameter count")
    shape = len(matrices[0]), len(matrices[0][0])
    if any((len(a), len(a[0])) != shape for a in matrices):
        raise ValueError("Coefficient shapes differ")
    return tuple(tuple(sum(value*a[i][j] for value, a in zip(values, matrices))
                       for j in range(shape[1])) for i in range(shape[0]))
","dynacomp/fastforward.py":""""Exact logarithmic composition of reduced affine update blocks."""
from .rational import matrix, identity, mul, mv, q, addv


def compose(after, before):
    """(A,b) after (C,d) is (AC,Ad+b)."""
    a, b = after
    c, d = before
    return mul(a, c), addv(mv(a, d), b)


def repeat_affine(A, b, repeats):
    a = matrix(A)
    if type(repeats) is not int or repeats < 0 or len(a) != len(a[0]) or len(b) != len(a):
        raise ValueError("Need square A, matching b and a nonnegative integer repeat count")
    result = identity(len(a)), tuple(q(0) for _ in a)
    power = a, tuple(q(v) for v in b)
    while repeats:
        if repeats & 1:
            result = compose(power, result)
        repeats >>= 1
        if repeats:
            power = compose(power, power)
    return result


def repeat_input_block(reduction, x0, inputs, repeats):
    """Repeat a fixed control word without replaying every individual step."""
    r = len(reduction.G)
    block = identity(r), tuple(q(0) for _ in range(r))
    for u in inputs:
        step = reduction.G, mv(reduction.H, u)
        block = compose(step, block)
    power, offset = repeat_affine(*block, repeats)
    final = addv(mv(power, mv(reduction.E, x0)), offset)
    return mv(reduction.D, final)
","dynacomp/finite.py":""""Minimal all-future observational quotient for finite partial machines."""
from dataclasses import dataclass
from collections import deque


@dataclass(frozen=True)
class FiniteModel:
    observations: tuple
    transitions: tuple

    def __post_init__(self):
        n = len(self.observations)
        if not n or len(self.transitions) != n:
            raise ValueError("Need observations and transition row per state")
        m = len(self.transitions[0])
        if not m or any(len(row) != m for row in self.transitions):
            raise ValueError("Need a nonempty fixed action alphabet")
        if any(t is not None and (type(t) is not int or not 0 <= t < n)
               for row in self.transitions for t in row):
            raise ValueError("Successors must be states or None")


def partition(labels):
    distinct, result = [], []
    for label in labels:
        if label not in distinct:
            distinct.append(label)
        result.append(distinct.index(label))
    return tuple(result)


def distinguish(model, s, t):
    """Shortest experiment; definedness itself is observable."""
    queue, seen = deque([(s, t, ())]), set()
    while queue:
        s, t, word = queue.popleft()
        if (s, t) in seen:
            continue
        seen.add((s, t))
        if model.observations[s] != model.observations[t]:
            return list(word)
        for action, (a, b) in enumerate(zip(model.transitions[s], model.transitions[t])):
            if (a is None) != (b is None):
                return list(word + (action,))
            if a is not None:
                queue.append((a, b, word + (action,)))
    return None


def compile_finite(model):
    classes = partition(model.observations)
    rounds = []
    while True:
        signatures = [(classes[s], tuple(None if t is None else classes[t] for t in row))
                      for s, row in enumerate(model.transitions)]
        refined = partition(signatures)
        if refined == classes:
            break
        witnesses = []
        for s in range(len(classes)):
            for t in range(s):
                if classes[s] == classes[t] and refined[s] != refined[t]:
                    witnesses.append({"states": [t, s], "word": distinguish(model, t, s)})
        rounds.append({"before": max(classes)+1, "after": max(refined)+1, "witnesses": witnesses})
        classes = refined
    representatives = [classes.index(c) for c in range(max(classes)+1)]
    observations = [model.observations[s] for s in representatives]
    transitions = [[None if t is None else classes[t] for t in model.transitions[s]]
                   for s in representatives]
    witnesses = [{"classes": [a, b], "word": distinguish(model, representatives[a], representatives[b])}
                 for a in range(len(representatives)) for b in range(a)]
    return {"schema": "dynacomp.finite/1", "observations": list(model.observations),
            "transitions": [list(row) for row in model.transitions], "classes": list(classes),
            "quotient_observations": observations, "quotient_transitions": transitions,
            "distinguishing_witnesses": witnesses, "rounds": rounds}


def outcome(model, state, word):
    """Observe initial and every subsequent state, including undefined action."""
    trace = [model.observations[state]]
    for action in word:
        if type(action) is not int or not 0 <= action < len(model.transitions[0]):
            raise ValueError("Invalid action")
        state = model.transitions[state][action]
        if state is None:
            return (trace, False)
        trace.append(model.observations[state])
    return (trace, True)


def replay_finite(packet):
    """Check homomorphism and pair-specific witnesses, without partition refinement."""
    if packet.get("schema") != "dynacomp.finite/1":
        raise ValueError("Unknown schema")
    source = FiniteModel(tuple(packet["observations"]), tuple(tuple(r) for r in packet["transitions"]))
    target = FiniteModel(tuple(packet["quotient_observations"]), tuple(tuple(r) for r in packet["quotient_transitions"]))
    classes = packet["classes"]
    n = len(target.observations)
    if len(source.transitions[0]) != len(target.transitions[0]):
        raise ValueError("Action alphabets differ")
    if len(classes) != len(source.observations) or any(type(c) is not int or not 0 <= c < n for c in classes):
        raise ValueError("Invalid class map")
    if set(classes) != set(range(n)):
        raise ValueError("Class map is not onto")
    for s, c in enumerate(classes):
        if source.observations[s] != target.observations[c]:
            raise ValueError("Observation not preserved")
        for action, t in enumerate(source.transitions[s]):
            expected = None if t is None else classes[t]
            if expected != target.transitions[c][action]:
                raise ValueError("Transition/definedness not preserved")
    pairs = set()
    for witness in packet["distinguishing_witnesses"]:
        a, b = witness["classes"]
        if type(a) is not int or type(b) is not int or not 0 <= b < a < n:
            raise ValueError("Invalid witness pair")
        if outcome(target, a, witness["word"]) == outcome(target, b, witness["word"]):
            raise ValueError("Witness does not distinguish")
        pairs.add((a, b))
    if pairs != {(a, b) for a in range(n) for b in range(a)}:
        raise ValueError("Missing class-pair witnesses")
    return True
","dynacomp/forever.py":""""All-time uniform output-error brackets for persistent input boxes.

Question: does a fixed reduced model keep |y_t - y_hat_t| <= tol for EVERY
t >= 0, every initial state in a box and every input sequence that stays in a
constant box forever? Finite-horizon certificates cannot answer this: a model
accepted for twenty steps can drift away at steady state.

Work on the exact observable quotient (Eo, Go, Ho, Do), whose outputs equal
the full model's, and stack w = (Eo x, z):
    Aw = diag(Go, G), Bw = [Ho; H], Cw = [Do, -D],  e_t = Cw w_t.
With rows R_t = Cw Aw^t, steady state w* = (I-Aw)^(-1) Bw a, e* = Cw w*,
d0 = lift(c) - w*, the exact supremum of |e_t,i| over the domain at time t is
    S_t,i = |e*_i + R_t,i d0| + sum_k |R_t,i lift_k| r_k + sum_(s<t) sum_k |R_s,i Bw_k| b_k,
attained by a sign-pattern witness. DynaComp encloses S_t from both sides for
t = 0..T with dyadic arithmetic whose rounding error is tracked in the dual
norm ||.||_(P^-1) of a certified quadratic metric P (rows contract there, so
rounding errors stay bounded). For t > T every term is bounded with
||R_t v|| <= kappa rho^t ||v||_P, giving
    S_t,i <= |e*_i| + sum_(s<T) |...| + kappa_i rho^T (||d0||_P + nu_x + beta/(1-rho)).
The result is a rigorous bracket [lower, upper] for sup_t sup_domain |e_t|.
If lower > tol the tolerance is REFUTED: some admissible scenario violates it.
"""
from fractions import Fraction
from .rational import matrix, mul, identity, sub, mv, q, encoded, inverse, transpose
from .sparse import compile_sparse
from .stability import quadratic_certificate, contraction_holds, positive_definite, sqrt_up
from .uniform import as_sparse, sharp_box_bound, SparseLinearModel


def _blockdiag(a, b):
    n, m = len(a), len(b)
    return tuple(tuple(a[i][j] if j < n else Fraction(0) for j in range(n+m)) for i in range(n)) + \
        tuple(tuple(Fraction(0) if j < n else b[i][j-n] for j in range(n+m)) for i in range(m))


def _quad_abs(p, m):
    """Upper bound of sqrt(v^T P v) over |v_i| <= m_i."""
    k = len(m)
    return sqrt_up(sum(abs(p[i][j])*m[i]*m[j] for i in range(k) if m[i] for j in range(k) if m[j]))


def _pnorm(p, v):
    return sqrt_up(sum(v[i]*p[i][j]*v[j] for i in range(len(v)) if v[i] for j in range(len(v)) if v[j]))


def _round(x, bits):
    """Nearest integer to x * 2^bits."""
    y = q(x)*(1 << bits)
    return (y.numerator*2 + y.denominator)//(2*y.denominator)


_QUOTIENTS = {}


def _quotient(model):
    """Exact observable quotient and its certified metric, cached per model."""
    key = (model.operator.n, model.operator.entries, model.B, model.C)
    if key not in _QUOTIENTS:
        op = model.operator
        packet = compile_sparse(op, model.B, model.C, max_rank=op.n)
        parts = tuple(matrix(packet[k]) for k in ("E", "G", "H", "D"))
        _QUOTIENTS[key] = (parts, quadratic_certificate(parts[1]))
    return _QUOTIENTS[key]


def stacked_error_system(model, E, G, H, D):
    (eo, go, ho, do), _ = _quotient(model)
    return {"Go": go, "Eo": eo, "Ho": ho, "Do": do, "Aw": _blockdiag(go, G),
            "Bw": tuple(ho) + tuple(H), "Cw": tuple(tuple(r) + tuple(-x for x in s) for r, s in zip(do, D)),
            "lift": tuple(eo) + tuple(E)}


def all_time_bound(model, V, E, G, H, initial_center, initial_radius, input_center, input_radius,
                   tolerance=None, slack="1/1000000", max_steps=20000, bits=64):
    model = as_sparse(model)
    v, e, g, h = map(matrix, (V, E, G, H))
    if mul(e, v) != identity(len(g)):
        raise ValueError("Need EV = I")
    d = mul(model.C, v)
    c0, r0 = tuple(q(x) for x in initial_center), tuple(q(x) for x in initial_radius)
    a, b = tuple(q(x) for x in input_center), tuple(q(x) for x in input_radius)
    n, m = model.operator.n, len(model.B[0])
    if len(c0) != n or len(r0) != n or len(a) != m or len(b) != m or any(x < 0 for x in r0+b):
        raise ValueError("Boxes need matching dimensions and nonnegative radii")
    tol = None if tolerance is None else q(tolerance)
    slack = q(slack)
    s = stacked_error_system(model, e, g, h, d)
    aw, bw, cw, lift = s["Aw"], s["Bw"], s["Cw"], s["lift"]
    k, p_out = len(aw), len(cw)
    base = {"schema": "dynacomp.all-time-bound/1", "model": model.spec(),
            "V": encoded(v), "E": encoded(e), "G": encoded(g), "H": encoded(h),
            "initial_center": [str(x) for x in c0], "initial_radius": [str(x) for x in r0],
            "input_center": [str(x) for x in a], "input_radius": [str(x) for x in b],
            "tolerance": None if tol is None else str(tol), "slack": str(slack), "bits": bits,
            "quotient_order": len(s["Go"]), "reduced_order": len(g)}
    metrics = [_quotient(model)[1], quadratic_certificate(g)]
    if any(x["status"] != "certified" for x in metrics):
        return {**base, "status": "no_metric", "metrics": [x["status"] for x in metrics],
                "claim": "no all-time statement; finite-horizon certificates still apply"}
    P = _blockdiag(matrix(metrics[0]["P"]), matrix(metrics[1]["P"]))
    gamma = max(q(x["gamma"]) for x in metrics)
    rho = sqrt_up(gamma)
    if rho >= 1:
        return {**base, "status": "no_metric", "claim": "rounded contraction factor reached 1"}
    Pinv = inverse(P)
    w_star = mv(inverse(sub(identity(k), aw)), mv(bw, a))
    steady = mv(cw, w_star)
    d0 = tuple(x - y for x, y in zip(mv(lift, c0), w_star))
    kappa = [sqrt_up(sum(c[i]*Pinv[i][j]*c[j] for i in range(k) for j in range(k))) for c in cw]
    mu = _pnorm(P, d0)
    nu_x = _quad_abs(P, [sum(abs(x)*r for x, r in zip(row, r0)) for row in lift])
    beta = _quad_abs(P, [sum(abs(x)*r for x, r in zip(row, b)) for row in bw])
    lam = sqrt_up(sum(abs(x) for row in Pinv for x in row))  # ||eps||_(P^-1) <= lam * max|eps_k|
    tail_factor = mu + nu_x + beta/(1-rho)

    ulp = Fraction(1, 1 << bits)
    lift_cols = transpose(lift)
    bw_cols = transpose(bw)
    awi = [[_round(x, bits) for x in row] for row in aw]
    d0i = [_round(x, bits) for x in d0]
    lifti = [[_round(x, bits) for x in col] for col in lift_cols]
    bwi = [[_round(x, bits) for x in col] for col in bw_cols]
    lift_norm = [_pnorm(P, col) for col in lift_cols]
    bw_norm = [_pnorm(P, col) for col in bw_cols]
    d0_norm = mu
    active_x = [j for j, r in enumerate(r0) if r]
    active_u = [j for j, r in enumerate(b) if r]

    rows = [[_round(x, bits) for x in row] for row in cw]
    eta = [lam*ulp/2 for _ in cw]  # ||R_t - rows/2^bits||_(P^-1)
    rho_t = Fraction(1)
    s_hi, s_lo = [Fraction(0)]*p_out, [Fraction(0)]*p_out
    upper_so_far, lower_best = Fraction(0), (Fraction(0), 0, 0)
    two = 1 << (2*bits)
    history = []
    status, steps = None, 0
    use_state_metric = [False]*p_out
    for t in range(max_steps+1):
        steps = t
        tails = []
        for i, row in enumerate(rows):
            one_norm = Fraction(sum(abs(x) for x in row), 1 << bits)
            def dot(col):
                return Fraction(sum(x*y for x, y in zip(row, col) if x and y), two)
            def err(norm):
                # stored-row error (eta * ||v||_P) plus rounding of v itself
                return eta[i]*norm + one_norm*ulp/2
            mean = steady[i] + dot(d0i)
            me = err(d0_norm)
            mean_hi, mean_lo = abs(mean) + me, max(abs(mean) - me, 0)
            if use_state_metric[i]:
                state_hi, state_lo = kappa[i]*rho_t*nu_x, Fraction(0)
            else:
                state_hi = state_lo = Fraction(0)
                for j in active_x:
                    val, ev = abs(dot(lifti[j])), err(lift_norm[j])
                    state_hi += (val + ev)*r0[j]
                    state_lo += max(val - ev, 0)*r0[j]
                if kappa[i]*rho_t*nu_x <= slack/4:
                    use_state_metric[i] = True
            hi = mean_hi + state_hi + s_hi[i]
            lo = mean_lo + state_lo + s_lo[i]
            upper_so_far = max(upper_so_far, hi)
            if lo > lower_best[0]:
                lower_best = (lo, t, i)
            for j in active_u:
                val, ev = abs(dot(bwi[j])), err(bw_norm[j])
                s_hi[i] += (val + ev)*b[j]
                s_lo[i] += max(val - ev, 0)*b[j]
            tails.append(abs(steady[i]) + s_hi[i] + kappa[i]*rho_t*rho*tail_factor)
        upper = max(upper_so_far, max(tails))
        if t % 64 == 0:
            history.append({"t": t, "lower": f"{float(lower_best[0]):.9g}", "upper": f"{float(upper):.9g}"})
        if tol is not None and lower_best[0] > tol:
            status = "refuted"
            break
        if tol is not None and upper <= tol:
            status = "certified"
            break
        if max(kappa)*rho_t*rho*tail_factor <= slack and all(use_state_metric):
            status = "converged" if tol is None else "undecided_within_slack"
            break
        # Advance rows: R_(t+1) = R_t Aw, tracking rounding in the dual metric.
        new_rows = []
        for i, row in enumerate(rows):
            nxt = [sum(x*y[c] for x, y in zip(row, awi) if x) for c in range(k)]
            new_rows.append([(z + (1 << (bits-1))) >> bits for z in nxt])
            one_norm = Fraction(sum(abs(x) for x in row), 1 << bits)
            eta[i] = rho*eta[i] + lam*(ulp/2 + one_norm*ulp/2)
            eta[i] = Fraction(_round(eta[i], bits) + 1, 1 << bits)  # keep sizes bounded, round up
        rows = new_rows
        rho_t = Fraction(_round(rho_t*rho, bits) + 1, 1 << bits)
    else:
        status = "step_limit"
    lower, t_low, i_low = lower_best
    result = {**base, "status": status, "steps_examined": steps,
              "lower": str(lower), "upper": str(upper),
              "lower_approximately": f"{float(lower):.9g}", "upper_approximately": f"{float(upper):.9g}",
              "worst_time_lower_bound": t_low, "worst_output": i_low,
              "steady_state_error": [str(x) for x in steady],
              "steady_state_error_approximately": [f"{float(x):.9g}" for x in steady],
              "P": encoded(P), "gamma": str(gamma), "rho": str(rho),
              "history": history,
              "claim": ("rigorous bracket for sup over all t >= 0, all initial states in the box and all input "
                        "sequences remaining in the constant input box; the lower value is attained by a "
                        "sign-pattern scenario at the recorded time")}
    if status == "refuted":
        result["refutation"] = {"time": t_low, "output": i_low, "error_at_least": str(lower)}
    return result


def replay_all_time(packet):
    """Check the metric exactly, then recompute the deterministic bracket."""
    if packet.get("schema") != "dynacomp.all-time-bound/1" or packet.get("status") == "no_metric":
        raise ValueError("Need an all-time bracket packet")
    model = SparseLinearModel.from_spec(packet["model"])
    v, e, g, h = (matrix(packet[k]) for k in ("V", "E", "G", "H"))
    p, gamma = matrix(packet["P"]), q(packet["gamma"])
    if not positive_definite(p) or not 0 <= gamma < 1:
        raise ValueError("Invalid metric")
    aw = stacked_error_system(model, e, g, h, mul(model.C, v))["Aw"]
    if not contraction_holds(aw, p, gamma):
        raise ValueError("Stacked error dynamics do not contract in the stored metric")
    fresh = all_time_bound(model, v, e, g, h, packet["initial_center"], packet["initial_radius"],
                           packet["input_center"], packet["input_radius"], packet["tolerance"],
                           packet["slack"], bits=packet["bits"])
    for key in ("status", "lower", "upper", "P", "gamma", "steps_examined"):
        if fresh[key] != packet[key]:
            raise ValueError(f"Stored {key} does not match recomputation")
    return True


def moment_rows(model, count):
    """Rows C (I - A)^(-j), j = 1..count: left Krylov directions at z = 1.

    Including them in the encoder matches steady-state (DC) gains, which a
    finite-horizon enrichment does not see. Computed on the exact quotient.
    """
    model = as_sparse(model)
    (eo, go, _, do), _ = _quotient(model)
    resolvent = inverse(sub(identity(len(go)), go))
    rows, block = [], do
    for _ in range(count):
        block = mul(block, resolvent)
        rows.extend(mul(block, eo))
    return rows


def all_time_enrichment(model, initial_center, initial_radius, input_center, input_radius, tolerance,
                        max_rank=None, slack="1/1000000"):
    """Grow directions until the all-time bracket certifies the tolerance.

    Two candidate families compete at each round: the next steady-state moment
    row C (I - A)^(-j) and the next target pullback C A^k. The candidate with
    the smaller rigorous lower bound is kept (refutations are found early, so
    rejected candidates are cheap). This is a heuristic; the final packet is
    an ordinary all-time bracket, replayed independently of the search.
    """
    from .uniform import _project
    from .krylov import Echelon
    model = as_sparse(model)
    n = model.operator.n
    budget = n if max_rank is None else max_rank
    moments = moment_rows(model, budget)
    pulls, row = [], model.C
    for _ in range(budget):
        row = model.operator.pullback(row)
        pulls.extend(row)
    span, chosen = Echelon(), []
    for r in model.C:
        if span.add(r):
            chosen.append(r)
    queues = {"moment": list(moments), "pullback": pulls}
    history = []

    def evaluate(rows):
        v, e, g, h, d = _project(model, rows)
        return all_time_bound(model, v, e, g, h, initial_center, initial_radius, input_center,
                              input_radius, tolerance, slack)

    current = evaluate(chosen)
    history.append({"rank": len(chosen), "status": current["status"], "lower": current["lower_approximately"],
                    "upper": current["upper_approximately"]})
    while current["status"] != "certified" and len(chosen) < budget:
        trials = []
        for kind, queue in queues.items():
            while queue and not any(span.reduce(queue[0])):
                queue.pop(0)
            if queue:
                packet = evaluate(chosen + [queue[0]])
                trials.append((packet["status"] != "certified", Fraction(packet["lower"]), kind, packet))
        if not trials:
            break
        _, _, kind, current = min(trials, key=lambda x: (x[0], x[1]))
        added = queues[kind].pop(0)
        span.add(added)
        chosen.append(added)
        history.append({"rank": len(chosen), "added": kind, "status": current["status"],
                        "lower": current["lower_approximately"], "upper": current["upper_approximately"]})
    return {**current, "enrichment_history": history,
            "enrichment_claim": "heuristic choice between steady-state moments and target pullbacks; acceptance is the all-time bracket"}
","dynacomp/generating.py":""""Exact rational OGFs and a supported algebraic-series remainder calculus.

Coefficients are low degree first. A realization means a_n=C A^n x0,
including n=0; it is not an input/output transfer-function indexing convention.
The same stdlib-only file is distributed in PerfectPower.
"""
from dataclasses import dataclass
from fractions import Fraction as Q


def _q(x):
    if isinstance(x, float):
        raise TypeError('Exact rational input required')
    value=Q(x)
    if max(abs(value.numerator).bit_length(),value.denominator.bit_length()) > 16384:
        raise ValueError('Exact generating-function arithmetic exceeds 16384 bits')
    return value


def _poly(xs):
    xs = list(map(_q, xs))
    while xs and not xs[-1]:
        xs.pop()
    return tuple(xs) or (Q(0),)


def _add(a, b):
    return _poly([(a[i] if i < len(a) else 0)+(b[i] if i < len(b) else 0)
                  for i in range(max(len(a), len(b)))])


def _mul(a, b):
    c = [Q(0)]*(len(a)+len(b)-1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            c[i+j] += x*y
    return _poly(c)


def _div(a, b):
    a, b = list(_poly(a)), _poly(b)
    if b == (0,):
        raise ValueError('Zero denominator')
    c = [Q(0)]*max(1, len(a)-len(b)+1)
    while a and len(a) >= len(b):
        k, v = len(a)-len(b), a[-1]/b[-1]
        c[k] = v
        for j, x in enumerate(b):
            a[j+k] -= v*x
        while a and not a[-1]:
            a.pop()
    return _poly(c), _poly(a)


def _gcd(a, b):
    while b != (0,):
        a, b = b, _div(a, b)[1]
    return tuple(x/a[-1] for x in a)


def _matrix(rows):
    rows = tuple(tuple(_q(x) for x in row) for row in rows)
    if not rows or not rows[0] or any(len(row) != len(rows[0]) for row in rows):
        raise ValueError('Nonempty rectangular matrix required')
    return rows


def _mm(a, b):
    return tuple(tuple(_q(sum(x*y for x, y in zip(row, col))) for col in zip(*b)) for row in a)


def _mv(a, x):
    return tuple(_q(sum(v*w for v, w in zip(row, x))) for row in a)


def _rpow(x, n):
    result=Q(1)
    while n:
        if n & 1:
            result=_q(result*x)
        n//=2
        if n:
            x=_q(x*x)
    return result


def _identity(n):
    return tuple(tuple(Q(i == j) for j in range(n)) for i in range(n))


def _power(a, n):
    result = _identity(len(a))
    while n:
        if n & 1:
            result = _mm(result, a)
        a, n = _mm(a, a), n//2
    return result


def _det(a):
    a = [list(row) for row in a]
    result = Q(1)
    for j in range(len(a)):
        pivot = next((k for k in range(j, len(a)) if a[k][j]), None)
        if pivot is None:
            return Q(0)
        if pivot != j:
            a[j], a[pivot] = a[pivot], a[j]
            result = -result
        v = a[j][j]
        result *= v
        for k in range(j+1, len(a)):
            t = a[k][j]/v
            for i in range(j+1, len(a)):
                a[k][i] -= t*a[j][i]
    return result


def _count(n, limit=10000):
    if type(n) is not int or not 0 <= n <= limit:
        raise ValueError(f'Integer count in 0..{limit} required')
    return n


@dataclass(frozen=True)
class RationalGF:
    numerator: tuple
    denominator: tuple = (Q(1),)

    def __post_init__(self):
        p, q = _poly(self.numerator), _poly(self.denominator)
        if not q[0]:
            raise ValueError('An ordinary generating function needs Q(0) != 0')
        g = _gcd(p, q)
        p, q = _div(p, g)[0], _div(q, g)[0]
        factor = q[0]
        object.__setattr__(self, 'numerator', tuple(x/factor for x in p))
        object.__setattr__(self, 'denominator', tuple(x/factor for x in q))

    @property
    def dimension(self):
        return 0 if self.numerator == (0,) else max(len(self.denominator)-1, len(self.numerator))

    def coefficients(self, count):
        out = []
        for n in range(_count(count)):
            v = self.numerator[n] if n < len(self.numerator) else Q(0)
            out.append(_q(v-sum(self.denominator[j]*out[n-j]
                             for j in range(1, min(n+1, len(self.denominator))))))
        return tuple(out)

    def __add__(self, other):
        return RationalGF(_add(_mul(self.numerator, other.denominator),
                               _mul(other.numerator, self.denominator)),
                          _mul(self.denominator, other.denominator))

    def __mul__(self, other):
        return RationalGF(_mul(self.numerator, other.numerator),
                          _mul(self.denominator, other.denominator))

    def weighted_indices(self):
        """OGF of n*a_n: z*d/dz, retaining index zero."""
        p, q = self.numerator, self.denominator
        dp, dq = _poly([i*p[i] for i in range(1, len(p))]), _poly([i*q[i] for i in range(1, len(q))])
        return RationalGF((0,)+_add(_mul(dp, q), tuple(-x for x in _mul(p, dq))), _mul(q, q))

    def realize(self):
        r = self.dimension
        if r > 128:
            raise ValueError('Realization dimension exceeds 128')
        if not r:
            return (), (), ()
        a = [[Q(0)]*r for _ in range(r)]
        for i in range(r-1):
            a[i][i+1] = Q(1)
        a[-1] = [-self.denominator[r-i] if r-i < len(self.denominator) else Q(0) for i in range(r)]
        return tuple(map(tuple, a)), self.coefficients(r), (Q(1),)+(Q(0),)*(r-1)

    def nth(self, n):
        if type(n) is not int or n < 0:
            raise ValueError('Nonnegative integer index required')
        a, x, c = self.realize()
        return sum(v*w for v, w in zip(c, _mv(_power(a, n), x))) if a else Q(0)

    def subsequence(self, stride, offset=0):
        if type(stride) is not int or stride < 1 or type(offset) is not int or offset < 0:
            raise ValueError('Positive integer stride and nonnegative offset required')
        a, x, c = self.realize()
        if not a:
            return self
        return from_state(_power(a, stride), _mv(_power(a, offset), x), c)

    def packet(self):
        a, x, c = self.realize()
        r = len(a)
        values = self.coefficients(2*r-1) if r else ()
        hankel = [[values[i+j] for j in range(r)] for i in range(r)]
        determinant = _det(hankel)
        if r and not determinant:
            raise ArithmeticError('Minimal realization Hankel witness is singular')
        return {'schema': 'exact.rational-gf/1', 'numerator': list(map(str, self.numerator)),
                'denominator': list(map(str, self.denominator)), 'dimension': r,
                'A': [list(map(str, row)) for row in a], 'initial': list(map(str, x)),
                'C': list(map(str, c)), 'hankel_determinant': str(determinant),
                'indexing': 'a_n = C A^n initial, n >= 0; no input feedthrough'}

    def tail(self, argument, radius, count):
        """Cauchy majorant on |z|=radius; certified absolute series tail."""
        z, radius, count = abs(_q(argument)), _q(radius), _count(count)
        if not 0 <= z < radius:
            raise ValueError('Need |argument| < radius')
        gap = 1-sum(abs(x)*radius**i for i, x in enumerate(self.denominator) if i)
        if gap <= 0:
            raise ValueError('Triangle bound cannot certify a pole-free disk at this radius')
        majorant = sum(abs(x)*radius**i for i, x in enumerate(self.numerator))/gap
        bound = _q(majorant*_rpow(z/radius,count)/(1-z/radius))
        return {'schema': 'exact.rational-gf-tail/1', 'source': self.packet(),
                'argument': str(_q(argument)), 'radius': str(radius), 'count': count,
                'majorant': str(majorant), 'absolute_tail_upper': str(bound)}


def from_recurrence(coefficients, initial):
    c, initial = tuple(map(_q, coefficients)), tuple(map(_q, initial))
    if not c or len(c) != len(initial):
        raise ValueError('Matching positive order and initial prefix required')
    q = (Q(1),)+tuple(-x for x in reversed(c))
    p = [sum(q[j]*initial[i-j] for j in range(i+1)) for i in range(len(c))]
    return RationalGF(tuple(p), q)


def from_state(A, initial, C):
    """Faddeev-LeVerrier exact denominator, followed by full cancellation."""
    a, x, c = _matrix(A), tuple(map(_q, initial)), tuple(map(_q, C))
    n = len(a)
    if n > 128 or len(a[0]) != n or len(x) != n or len(c) != n:
        raise ValueError('Square state matrix, matching vectors, dimension <= 128 required')
    b, denominator = _identity(n), [Q(1)]
    for k in range(1, n+1):
        b = _mm(a, b)
        v = -sum(b[i][i] for i in range(n))/k
        denominator.append(v)
        b = tuple(tuple(b[i][j]+(v if i == j else 0) for j in range(n)) for i in range(n))
    values = []
    for _ in range(n):
        values.append(sum(v*w for v, w in zip(c, x)))
        x = _mv(a, x)
    numerator = [sum(denominator[j]*values[i-j] for j in range(i+1)) for i in range(n)]
    return RationalGF(tuple(numerator), tuple(denominator))


def periodic_gf(prefix, cycle):
    prefix, cycle = tuple(map(_q, prefix)), tuple(map(_q, cycle))
    if not cycle:
        raise ValueError('Nonempty periodic cycle required')
    return RationalGF(prefix or (0,)) + RationalGF((Q(0),)*len(prefix)+cycle,
                                                  (Q(1),)+(Q(0),)*(len(cycle)-1)+(Q(-1),))


def binomial_tail(alpha, argument, count):
    """Enclose (1-z)^(-alpha) for rational alpha>0 and 0<=z<1.

    Bound each future coefficient ratio, not just its asymptotic growth.
    Count is the number of retained coefficients, including the constant.
    """
    a, z, count = _q(alpha), _q(argument), _count(count)
    if a <= 0 or not 0 <= z < 1:
        raise ValueError('Positive alpha and argument in [0,1) required')
    coefficient, partial, power = Q(1), Q(0), Q(1)
    for n in range(count):
        partial = _q(partial+coefficient*power)
        power = _q(power*z)
        coefficient = _q(coefficient*(a+n)/(n+1))
    ratio = z*max(Q(1), (count+a)/(count+1))
    if ratio >= 1:
        raise ValueError('Retain more coefficients to make the geometric majorant contract')
    tail = _q(coefficient*power/(1-ratio))
    return {'schema': 'exact.binomial-tail/1', 'alpha': str(a), 'argument': str(z),
            'count': count, 'lower': str(partial), 'upper': str(partial+tail),
            'tail_upper': str(tail), 'future_ratio_upper': str(ratio),
            'scope': 'positive real binomial branch (1-z)^(-alpha)'}


def replay_generating(packet):
    schema = packet.get('schema')
    if schema == 'exact.rational-gf/1':
        expected = RationalGF(packet['numerator'], packet['denominator']).packet()
    elif schema == 'exact.rational-gf-tail/1':
        source = packet['source']
        replay_generating(source)
        expected = RationalGF(source['numerator'], source['denominator']).tail(
            packet['argument'], packet['radius'], packet['count'])
    elif schema == 'exact.binomial-tail/1':
        expected = binomial_tail(packet['alpha'], packet['argument'], packet['count'])
    else:
        raise ValueError('Unknown generating function schema')
    if packet != expected:
        raise ValueError('Generating function certificate does not reconstruct')
    return True
","dynacomp/krylov.py":""""Labeled breadth-first Krylov spans over Q.

Every retained vector remembers the word that produced it, so a basis is also
an experiment design: row c_i A_w is "observe output i after word w".
"""
from collections import deque
from .rational import q


class Echelon:
    """Incremental exact independence test; rows kept in insertion order."""

    def __init__(self):
        self.rows = []

    def reduce(self, vector):
        v = [q(x) for x in vector]
        for pivot, row in self.rows:
            c = v[pivot]
            if c:
                v = [a-c*b for a, b in zip(v, row)]
        return v

    def add(self, vector):
        v = self.reduce(vector)
        pivot = next((j for j, x in enumerate(v) if x), None)
        if pivot is None:
            return False
        c = v[pivot]
        self.rows.append((pivot, [x/c for x in v]))
        return True

    def __len__(self):
        return len(self.rows)


def vecmat(v, a):
    """Row vector times matrix."""
    if len(v) != len(a):
        raise ValueError("Vector dimension does not match")
    return tuple(sum(v[i]*a[i][j] for i in range(len(v)) if v[i]) for j in range(len(a[0])))


def matvec(a, v):
    if len(a[0]) != len(v):
        raise ValueError("Vector dimension does not match")
    return tuple(sum(x*y for x, y in zip(row, v) if y) for row in a)


def krylov(starts, maps, limit=None, visit=None):
    """Span of {s . w} over start labels s and words w, in shortlex order.

    starts: [(label, vector)], maps: {letter: vector -> vector} (dict order is
    the alphabet order). Returns (vectors, labels) with labels (start, word).
    ``visit(label, vector)`` is called on every enqueued word before the
    independence test and may return a non-None value to stop early.
    """
    echelon, vectors, labels = Echelon(), [], []
    queue = deque((label, (), tuple(q(x) for x in v)) for label, v in starts)
    while queue:
        start, word, v = queue.popleft()
        if visit is not None:
            stop = visit((start, word), v)
            if stop is not None:
                return stop
        if not echelon.add(v):
            continue
        vectors.append(v)
        labels.append((start, word))
        if limit is not None and len(vectors) > limit:
            raise OverflowError("Krylov dimension exceeded limit")
        for letter, apply in maps.items():
            queue.append((start, word+(letter,), apply(v)))
    return tuple(vectors), tuple(labels)
","dynacomp/linear.py":""""Compile minimal target-preserving rational linear dynamics."""
from dataclasses import dataclass
from .rational import matrix, row_basis, coordinates, mul, mv, nullspace, encoded, q, addv


@dataclass(frozen=True)
class LinearModel:
    A: tuple
    B: tuple
    C: tuple

    @classmethod
    def from_rows(cls, A, B, C):
        a, b, c = matrix(A), matrix(B), matrix(C)
        n = len(a)
        if len(a[0]) != n or len(b) != n or len(c[0]) != n:
            raise ValueError("Expected A[n,n], B[n,m], C[p,n]")
        return cls(a, b, c)


@dataclass(frozen=True)
class LinearReduction:
    model: LinearModel
    E: tuple
    G: tuple
    H: tuple
    D: tuple
    rounds: tuple

    def packet(self):
        return {"schema": "dynacomp.linear/1", "arithmetic": "rational",
                **{k: encoded(getattr(self.model, k)) for k in ("A", "B", "C")},
                **{k: encoded(getattr(self, k)) for k in ("E", "G", "H", "D")},
                "rounds": list(self.rounds)}

    def simulate(self, x0, inputs):
        z = mv(self.E, tuple(q(v) for v in x0))
        outputs = [mv(self.D, z)]
        for u in inputs:
            z = addv(mv(self.G, z), mv(self.H, u))
            outputs.append(mv(self.D, z))
        return tuple(outputs)


def compile_linear(model):
    """Smallest A-invariant row space containing C, over all initial states."""
    basis = row_basis(model.C)
    if not basis:
        raise ValueError("Zero-only targets need no state; request a nonzero target")
    rounds = []
    while True:
        next_rows = mul(basis, model.A)
        enlarged = row_basis(basis + next_rows)
        if len(enlarged) == len(basis):
            break
        witness = closure_witness(model.A, basis)
        rounds.append({"before": len(basis), "after": len(enlarged), "witness": witness})
        basis = enlarged
    g = tuple(coordinates(row, basis) for row in mul(basis, model.A))
    d = tuple(coordinates(row, basis) for row in model.C)
    return LinearReduction(model, basis, g, mul(basis, model.B), d, tuple(rounds))


def closure_witness(A, E):
    """Same encoded state, different next encoded state: 0 and v."""
    a, e = matrix(A), matrix(E)
    for v in nullspace(e):
        difference = mv(mul(e, a), v)
        if any(difference):
            return {"v": [str(x) for x in v], "Ev": [str(x) for x in mv(e, v)],
                    "EAv": [str(x) for x in difference]}
    return None


def distinguishing_horizon(model, v):
    """Earliest output difference; None proves all-future equality by Cayley–Hamilton."""
    x = tuple(q(w) for w in v)
    for t in range(len(model.A)):
        y = mv(model.C, x)
        if any(y):
            return {"horizon": t, "difference": [str(w) for w in y]}
        x = mv(model.A, x)
    return None


def replay_linear(packet):
    """Independent acceptance by three exact identities, no compiler call."""
    if packet.get("schema") != "dynacomp.linear/1":
        raise ValueError("Unknown certificate schema")
    model = LinearModel.from_rows(packet["A"], packet["B"], packet["C"])
    e, g, h, d = (matrix(packet[k]) for k in ("E", "G", "H", "D"))
    if len(e[0]) != len(model.A) or len(row_basis(e)) != len(e):
        raise ValueError("E must have full row rank and correct width")
    if mul(e, model.A) != mul(g, e):
        raise ValueError("Transition identity EA=GE fails")
    if mul(e, model.B) != h:
        raise ValueError("Input identity EB=H fails")
    if mul(d, e) != model.C:
        raise ValueError("Target identity DE=C fails")
    return True
","dynacomp/machine.py":""""Uniform error bounds for a specified integer-accumulated binary64 runtime.

Every row sums exact products of stored operands, then rounds once to nearest
even. Encoder, transition+forcing, and output each follow that contract. This
does not certify NumPy/BLAS or arbitrary sequential floating point execution.
"""
from fractions import Fraction as Q
from .rational import matrix, q, encoded
from .binary64 import bits, from_bits, exact, round_bits, dot_bits, classify, MAX_FINITE
from .validated import replay_validated

U = Q(1, 1 << 53)
ETA = Q(1, 1 << 1075)
LIMIT = exact(MAX_FINITE)


def _up(x):
    scale = 1 << 96
    return Q((x*scale).__ceil__(), scale)


def _vec(values, n):
    result = tuple(map(q, values))
    if len(result) != n:
        raise ValueError('Domain dimensions differ')
    return result


def _abs_mv(a, x):
    return tuple(sum(abs(v)*w for v, w in zip(row, x)) for row in a)


def _round_budget(magnitude):
    if magnitude > LIMIT:
        raise ValueError('Cannot exclude binary64 overflow on this domain')
    return _up(U*magnitude+ETA) if magnitude else Q(0)


def _certify_execution(E, G, H, D, initial_center, initial_radius, input_radii,
                       tolerance, input_centers, budget, contract, schema):
    e, g, h, d = map(matrix, (E, G, H, D))
    r, n, m = len(g), len(e[0]), len(h[0])
    if len(e) != r or len(g[0]) != r or len(h) != r or len(d[0]) != r:
        raise ValueError('Expected E[r,n], G[r,r], H[r,m], D[p,r]')
    center, radius = _vec(initial_center, n), _vec(initial_radius, n)
    radii = tuple(_vec(row, m) for row in input_radii)
    means = tuple(_vec(row, m) for row in input_centers) if input_centers is not None else ((Q(0),)*m,)*len(radii)
    if len(means) != len(radii) or len(radii) > 4096:
        raise ValueError('Matching input domain and horizon <= 4096 required')
    if any(x < 0 for x in radius+sum(radii, ())):
        raise ValueError('Nonnegative radii required')
    tol = q(tolerance)
    if tol < 0:
        raise ValueError('Nonnegative tolerance required')
    words, loaded, differences = {}, {}, {}
    for name, a in zip(('E', 'G', 'H', 'D'), (e, g, h, d)):
        w = tuple(tuple(round_bits(v) for v in row) for row in a)
        if any(classify(v) == 'infinity' for row in w for v in row):
            raise ValueError('Matrix loading overflows binary64')
        loaded[name] = tuple(tuple(exact(v) for v in row) for row in w)
        differences[name] = tuple(tuple(abs(x-y) for x, y in zip(row, other))
                                  for row, other in zip(a, loaded[name]))
        words[name] = [list(row) for row in w]
    eh, gh, hh, dh = (loaded[k] for k in ('E', 'G', 'H', 'D'))
    de, dg, dh_input, dd = (differences[k] for k in ('E', 'G', 'H', 'D'))
    xbound = tuple(abs(c)+b for c, b in zip(center, radius))
    if any(v > LIMIT for v in xbound):
        raise ValueError('Initial domain exceeds finite binary64 range')
    z = tuple(_up(v) for v in _abs_mv(e, xbound))
    error = tuple(_up(a+budget(b, n)) for a, b in zip(_abs_mv(de, xbound), _abs_mv(eh, xbound)))
    outputs, states = [], []
    for t in range(len(radii)+1):
        actual_bound = tuple(a+b for a, b in zip(z, error))
        output_error = tuple(_up(a+b+budget(c, r)) for a, b, c in zip(
            _abs_mv(dh, error), _abs_mv(dd, z), _abs_mv(dh, actual_bound)))
        states.append(list(map(str, error)))
        outputs.append(list(map(str, output_error)))
        if t == len(radii):
            break
        ubound = tuple(abs(c)+b for c, b in zip(means[t], radii[t]))
        if any(v > LIMIT for v in ubound):
            raise ValueError('Input domain exceeds finite binary64 range')
        next_error = tuple(_up(a+b+c+budget(v+w, r+m)) for a, b, c, v, w in zip(
            _abs_mv(gh, error), _abs_mv(dg, z), _abs_mv(dh_input, ubound),
            _abs_mv(gh, actual_bound), _abs_mv(hh, ubound)))
        z = tuple(_up(v+w) for v, w in zip(_abs_mv(g, z), _abs_mv(h, ubound)))
        error = next_error
    worst = max(q(v) for row in outputs for v in row)
    return {'schema': schema,
            **{k: encoded(a) for k, a in zip(('E', 'G', 'H', 'D'), (e, g, h, d))},
            'initial_center': list(map(str, center)), 'initial_radius': list(map(str, radius)),
            'input_centers': [list(map(str, row)) for row in means],
            'input_radii': [list(map(str, row)) for row in radii], 'loaded_words': words,
            'state_error_upper': states, 'output_error_upper': outputs,
            'worst_execution_upper': str(worst), 'tolerance': str(tol),
            'status': 'tolerance_met' if worst <= tol else 'not_certified',
            'contract': contract,
            'scope': 'uniform deviation from the supplied rational reduced dynamics; finite horizon; includes coefficient loading'}


def certify_execution(E, G, H, D, initial_center, initial_radius, input_radii,
                      tolerance, input_centers=None):
    return _certify_execution(E, G, H, D, initial_center, initial_radius,
                             input_radii, tolerance, input_centers,
                             lambda magnitude, count: _round_budget(magnitude),
                             'finite stored binary64 inputs; integer exact dot; one RN-even rounding per row; +0 for exact zero',
                             'dynacomp.binary64-execution/1')


def replay_execution(packet):
    if packet.get('schema') != 'dynacomp.binary64-execution/1':
        raise ValueError('Unknown execution schema')
    fresh = certify_execution(*(packet[k] for k in ('E', 'G', 'H', 'D')),
                              packet['initial_center'], packet['initial_radius'],
                              packet['input_radii'], packet['tolerance'], packet['input_centers'])
    if packet != fresh:
        raise ValueError('Execution certificate does not reconstruct')
    return True


def compose_execution(source, tolerance):
    """Combine replayed finite model/source guarantees with machine execution."""
    if source.get('schema') == 'dynacomp.validated-box/1':
        replay_validated(source)
        finite, source_error = source, Q(0)
    elif source.get('schema') == 'dynacomp.spectral-composition/1':
        from .spectral import replay_spectral_composition
        replay_spectral_composition(source)
        finite = source['finite']
        source_error = q(source['combined_upper'])-q(finite['certificate']['worst_upper'])
    else:
        raise ValueError('Need a validated-box or spectral-composition source')
    tol = q(tolerance)
    runtime = certify_execution(*(finite[k] for k in ('E', 'G', 'H', 'D')),
                                finite['initial_center'], finite['initial_radius'],
                                finite['input_radii'], tol, finite['input_centers'])
    combined = [[str(source_error+q(a)+q(b)) for a, b in zip(model, execution)]
                for model, execution in zip(finite['certificate']['output_upper'], runtime['output_error_upper'])]
    worst = max(q(x) for row in combined for x in row)
    stable = finite['reduced_contraction_certified'] is not False
    return {'schema': 'dynacomp.machine-composition/1', 'source': source, 'execution': runtime,
            'tolerance': str(tol), 'combined_output_upper': combined, 'combined_upper': str(worst),
            'status': 'tolerance_met' if worst <= tol and stable else 'not_certified',
            'scope': 'source/model error plus actual specified binary64 execution; finite horizon'}


def replay_machine_composition(packet):
    if packet.get('schema') != 'dynacomp.machine-composition/1' or packet != compose_execution(packet['source'], packet['tolerance']):
        raise ValueError('Machine composition does not reconstruct')
    return True


class Binary64Runtime:
    """Execute precisely the machine protocol certified above; no BLAS calls."""
    def __init__(self, packet, require_accepted=True):
        import copy
        self._packet = copy.deepcopy(packet)
        if packet.get('schema') == 'dynacomp.machine-composition/1':
            replay_machine_composition(self._packet)
            self._execution = self._packet['execution']
        else:
            replay_execution(self._packet)
            self._execution = self._packet
        if require_accepted and self._packet['status'] != 'tolerance_met':
            raise ValueError('Tolerance not certified')
        self._words = {name: tuple(tuple(row) for row in rows) for name, rows in self._execution['loaded_words'].items()}

    @property
    def packet(self):
        import copy
        return copy.deepcopy(self._packet)

    def _domain(self, words, center, radius):
        if len(words) != len(center):
            raise ValueError('Input dimensions differ')
        for word, c, r in zip(words, center, radius):
            if abs(exact(word)-q(c)) > q(r):
                raise ValueError('Stored value is outside the certified domain')

    def simulate_bits(self, initial, inputs):
        p = self._execution
        initial, inputs = tuple(initial), tuple(tuple(row) for row in inputs)
        if len(inputs) > len(p['input_radii']):
            raise ValueError('Execution exceeds the certified horizon')
        self._domain(initial, p['initial_center'], p['initial_radius'])
        for t, row in enumerate(inputs):
            self._domain(row, p['input_centers'][t], p['input_radii'][t])
        z = tuple(dot_bits(row, initial) for row in self._words['E'])
        output = []
        for t in range(len(inputs)+1):
            output.append(tuple(dot_bits(row, z) for row in self._words['D']))
            if t < len(inputs):
                z = tuple(dot_bits(tuple(g)+tuple(h), z+inputs[t])
                          for g, h in zip(self._words['G'], self._words['H']))
        return tuple(output)

    def simulate(self, initial, inputs):
        result = self.simulate_bits(tuple(map(bits, initial)), [tuple(map(bits, row)) for row in inputs])
        return tuple(tuple(from_bits(word) for word in row) for row in result)
","dynacomp/memory.py":""""Derive exact scalar output recurrences with finite input memory."""
from .rational import matrix, mul, coordinates, mv, q, encoded, row_basis


def compile_output_memory(model):
    """Minimal scalar output recurrence for all initial states and input words."""
    if len(model.C) != 1 or not any(model.C[0]):
        raise ValueError("Need a nonzero scalar target")
    rows = [model.C[0]]
    while True:
        next_row = mul((rows[-1],), model.A)[0]
        coefficients = coordinates(next_row, matrix(rows))
        if coefficients is not None:
            break
        rows.append(next_row)
    order = len(rows)
    markov = [mul((row,), model.B)[0] for row in rows]
    kernels = []
    for j in range(order):
        kernel = list(markov[order-1-j])
        for i in range(j+1, order):
            for action in range(len(kernel)):
                kernel[action] -= coefficients[i]*markov[i-1-j][action]
        kernels.append(tuple(kernel))
    return {"schema": "dynacomp.memory/1", "order": order, "A": encoded(model.A),
            "B": encoded(model.B), "C": encoded(model.C),
            "output_coefficients": [str(v) for v in coefficients],
            "input_kernels": encoded(kernels),
            "meaning": "y[t+q]=sum_i a[i]y[t+i]+sum_j K[j]u[t+j]"}


def replay_memory(packet):
    """Check output and forcing polynomial identities, not training traces."""
    from .linear import LinearModel
    if packet.get("schema") != "dynacomp.memory/1":
        raise ValueError("Unknown schema")
    model = LinearModel.from_rows(packet["A"], packet["B"], packet["C"])
    order = packet["order"]
    if type(order) is not int or not 1 <= order <= len(model.A) or len(model.C) != 1:
        raise ValueError("Invalid scalar recurrence order")
    a = tuple(q(v) for v in packet["output_coefficients"])
    kernels = matrix(packet["input_kernels"])
    if len(a) != order or len(kernels) != order or len(kernels[0]) != len(model.B[0]):
        raise ValueError("Invalid recurrence dimensions")
    rows = [model.C[0]]
    for _ in range(order):
        rows.append(mul((rows[-1],), model.A)[0])
    if len(row_basis(rows[:-1])) != order:
        raise ValueError("Recurrence is not of minimal observable order")
    expected = tuple(sum(a[i]*rows[i][j] for i in range(order)) for j in range(len(model.A)))
    if expected != rows[-1]:
        raise ValueError("Output recurrence identity fails")
    markov = [mul((row,), model.B)[0] for row in rows[:-1]]
    for j in range(order):
        expected = tuple(markov[order-1-j][k]-sum(a[i]*markov[i-1-j][k] for i in range(j+1, order))
                         for k in range(len(model.B[0])))
        if expected != kernels[j]:
            raise ValueError("Input-memory identity fails")
    return True


def simulate_memory(packet, initial_outputs, inputs):
    """Initial q outputs must be consistent with the chosen initial input prefix."""
    replay_memory(packet)
    order = packet["order"]
    ys = [q(v) for v in initial_outputs]
    us = [tuple(q(v) for v in u) for u in inputs]
    a = tuple(q(v) for v in packet["output_coefficients"])
    kernels = matrix(packet["input_kernels"])
    if len(ys) != order or len(us) < order-1 or any(len(u) != len(kernels[0]) for u in us):
        raise ValueError("Need q initial outputs and at least q-1 matching inputs")
    for t in range(len(us)-order+1):
        output = sum(a[i]*ys[t+i] for i in range(order))
        output += sum(sum(kernels[j][k]*us[t+j][k] for k in range(len(kernels[0]))) for j in range(order))
        ys.append(output)
    return tuple(ys)
","dynacomp/metrics.py":""""Exact weighted infinity-norm margins; heuristic discovery, exact acceptance."""
from .rational import matrix, q


def metric_margin(A, weights):
    a = matrix(A)
    weights = tuple(q(v) for v in weights)
    if len(a) != len(a[0]) or len(weights) != len(a) or any(w <= 0 for w in weights):
        raise ValueError("Need square A and strictly positive weights")
    # ||x||_w = max_i |x_i| / w_i.
    rho = max(sum(abs(value)*weights[j] for j, value in enumerate(row))/weights[i]
              for i, row in enumerate(a))
    return {"arithmetic": "rational", "weights": [str(w) for w in weights],
            "factor": str(rho), "margin": str(1-rho), "contractive": rho < 1}


def discover_metric(A, rounds=32):
    """Search positive diagonal metrics. Failure is not proof of instability."""
    a = matrix(A)
    if len(a) != len(a[0]) or rounds < 0:
        raise ValueError("Invalid square operator or search budget")
    weights = [q(1)]*len(a)
    best = metric_margin(a, weights)
    for _ in range(rounds):
        # Positive resolvent-like iteration on |A|, with an additive floor.
        weights = [1+sum(abs(v)*weights[j] for j, v in enumerate(row)) for row in a]
        candidate = metric_margin(a, weights)
        if q(candidate["factor"]) < q(best["factor"]):
            best = candidate
    return best
