def sequential_budget(magnitude, count):
    """2k rounded operations: gamma_(2k) M + 2k eta/(1-2ku)."""
    if type(count) is not int or count < 0 or 2*count*U >= 1:
        raise ValueError('Invalid dot length')
    if not magnitude:
        return Q(0)
    denominator = 1-2*count*U
    error = (2*count*U*magnitude+2*count*ETA)/denominator
    if magnitude+error > LIMIT:
        raise ValueError('Cannot exclude intermediate sequential overflow')
    return _up(error)


def certify_sequential(E, G, H, D, initial_center, initial_radius, input_radii,
                       tolerance, input_centers=None):
    return _certify_execution(E, G, H, D, initial_center, initial_radius,
                             input_radii, tolerance, input_centers,
                             sequential_budget, CONTRACT,
                             'dynacomp.sequential-binary64/1')


def replay_sequential(packet):
    if packet.get('schema') != 'dynacomp.sequential-binary64/1':
        raise ValueError('Unknown sequential execution schema')
    fresh = certify_sequential(*(packet[k] for k in ('E','G','H','D')),
                               packet['initial_center'], packet['initial_radius'],
                               packet['input_radii'], packet['tolerance'], packet['input_centers'])
    if fresh != packet:
        raise ValueError('Sequential execution certificate does not reconstruct')
    return True


def compose_sequential(source, tolerance):
    if source.get('schema') != 'dynacomp.validated-box/1':
        raise ValueError('A finite validated-box source is required')
    replay_validated(source)
    runtime = certify_sequential(*(source[k] for k in ('E','G','H','D')),
                                 source['initial_center'], source['initial_radius'],
                                 source['input_radii'], tolerance, source['input_centers'])
    combined = [[str(q(a)+q(b)) for a,b in zip(model,execution)] for model,execution in
                zip(source['certificate']['output_upper'], runtime['output_error_upper'])]
    worst = max(q(v) for row in combined for v in row)
    return {'schema':'dynacomp.sequential-composition/1','source':source,'execution':runtime,
            'tolerance':str(q(tolerance)), 'combined_output_upper':combined,
            'combined_upper':str(worst),
            'status':'tolerance_met' if worst <= q(tolerance) and source['reduced_contraction_certified'] is not False else 'not_certified',
            'scope':'finite sampled rational source/model plus specified sequential C binary64 execution'}


def replay_sequential_composition(packet):
    if packet.get('schema') != 'dynacomp.sequential-composition/1' or packet != compose_sequential(packet['source'],packet['tolerance']):
        raise ValueError('Sequential composition does not reconstruct')
    return True


def _library():
    global _LIBRARY, _TEMP
    if _LIBRARY is not None:
        return _LIBRARY
    compiler = shutil.which('cc') or shutil.which('gcc') or shutil.which('clang')
    if not compiler:
        raise RuntimeError('Install a GCC-compatible C compiler to prepare native execution')
    source = Path(__file__).with_name('sequential.c')
    _TEMP = tempfile.TemporaryDirectory(prefix='dynacomp-sequential-')
    target = Path(_TEMP.name)/'runtime.so'
    command = [compiler,'-std=c11','-O2','-shared','-fPIC','-fno-fast-math',
               '-ffp-contract=off','-frounding-math',str(source),'-lm','-o',str(target)]
    started = time.perf_counter()
    subprocess.run(command,check=True,capture_output=True,text=True)
    build_seconds = time.perf_counter()-started
    lib = ctypes.CDLL(str(target))
    pointer = ctypes.POINTER(ctypes.c_double)
    lib.run.argtypes = [ctypes.c_size_t]*6+[pointer]*7
    lib.run.restype = ctypes.c_int
    lib.feedthrough.argtypes = [ctypes.c_size_t]*4+[pointer]*3
    lib.feedthrough.restype = ctypes.c_int
    lib.compiler_command = command[:-1]+['<temporary runtime>']
    lib.source_sha256 = hashlib.sha256(source.read_bytes()).hexdigest()
    lib.build_seconds = build_seconds
    lib.compiler_version = subprocess.run([compiler,'--version'],check=True,capture_output=True,text=True).stdout.splitlines()[0]
    _LIBRARY = lib
    return lib


class PreparedSequential:
    """Checked batched execution; array axes match PreparedValidated."""
    def __init__(self,packet):
        import numpy as np
        from .prepared import PreparedSwitching
        self._packet = copy.deepcopy(packet)
        if packet.get('schema') == 'dynacomp.sequential-composition/1':
            replay_sequential_composition(self._packet)
            execution = self._packet['execution']
        else:
            replay_sequential(self._packet)
            execution = self._packet
        if self._packet['status'] != 'tolerance_met':
            raise ValueError('Sequential plan has not met tolerance')
        self._lib = _library()
        self._e,self._g,self._h,self._d = [np.ascontiguousarray([[from_bits(v) for v in row]
                                                           for row in execution['loaded_words'][k]],dtype=np.float64)
                                       for k in ('E','G','H','D')]
        self._r,self._n,self._m,self._p = len(self._g),self._e.shape[1],self._h.shape[1],len(self._d)
        for value in (self._e,self._g,self._h,self._d):
            value.flags.writeable = False
        self._horizon = len(execution['input_radii'])
        def endpoints(center,radius):
            return [PreparedSwitching._float_endpoints(q(c)-q(r),q(c)+q(r)) for c,r in zip(center,radius)]
        initial = endpoints(execution['initial_center'],execution['initial_radius'])
        self._lower = np.asarray([lo for lo,hi in initial])[:,None]
        self._upper = np.asarray([hi for lo,hi in initial])[:,None]
        domain = [endpoints(c,r) for c,r in zip(execution['input_centers'],execution['input_radii'])]
        self._input_lower = np.asarray([[lo for lo,hi in row] for row in domain]).reshape(self._horizon,self._m,1)
        self._input_upper = np.asarray([[hi for lo,hi in row] for row in domain]).reshape(self._horizon,self._m,1)

    @property
    def packet(self):
        return copy.deepcopy(self._packet)

    @property
    def build_info(self):
        return {'source_sha256':self._lib.source_sha256,'compiler_command':self._lib.compiler_command,
                'compiler_version':self._lib.compiler_version,'contract':CONTRACT}

    def simulate(self,initial,inputs):
        import numpy as np
        x = np.ascontiguousarray(initial,dtype=np.float64)
        u = np.ascontiguousarray(inputs,dtype=np.float64)
        if x.ndim == 1:
            x = x[:,None]
        if u.ndim != 3 or u.shape[:2] != (self._horizon,self._m) or u.shape[2] < 1:
            raise ValueError('Wrong input shape or certified horizon')
        count = u.shape[2]
        if x.ndim != 2 or x.shape[0] != self._n or x.shape[1] not in (1,count):
            raise ValueError('Wrong initial shape')
        if not np.isfinite(x).all() or not np.isfinite(u).all():
            raise ValueError('Finite stored inputs required')
        if (x < self._lower).any() or (x > self._upper).any() or (u < self._input_lower).any() or (u > self._input_upper).any():
            raise ValueError('Batch outside certified boxes')
        if x.shape[1] == 1 and count > 1:
            x = np.ascontiguousarray(np.repeat(x,count,axis=1))
        output = np.empty((self._horizon+1,self._p,count),dtype=np.float64)
        pointer = ctypes.POINTER(ctypes.c_double)
        arrays = [v.ctypes.data_as(pointer) for v in (self._e,self._g,self._h,self._d,x,u,output)]
        status = self._lib.run(self._n,self._r,self._m,self._p,self._horizon,count,*arrays)
        if status:
            raise RuntimeError(f'Native execution refused unsupported floating-point environment (code {status})')
        if not np.isfinite(output).all():
            raise OverflowError('Nonfinite native output')
        return output
","dynacomp/network.py":""""Inventory-network scenario compilation with exact closed regional outputs.

State is pre-dispatch stock; inputs arrive after dispatch each step. All column
mass absent from the transition is counted as dispatch from its source region.
Rates are fixed linear fractions, without demand caps or congestion feedback.
"""
import hashlib
import json
import math
from dataclasses import dataclass
from .rational import q, matrix, encoded, mv, addv
from .sparse import SparseOperator
from .structure import aggregate_partition


def fingerprint(spec):
    return hashlib.sha256(json.dumps(spec, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()).hexdigest()


def _names(values, label):
    if not isinstance(values, list) or not values or any(not isinstance(v, str) or not v.strip() for v in values) or len(set(values)) != len(values):
        raise ValueError(f"Unique nonempty {label} names required")
    return tuple(values)


def _nonnegative(values, size, label):
    if not isinstance(values, (list, tuple)) or len(values) != size:
        raise ValueError(f"Wrong {label} dimension")
    result = tuple(q(v) for v in values)
    if any(v < 0 for v in result):
        raise ValueError(f"Nonnegative {label} required")
    return result


@dataclass(frozen=True)
class Network:
    op: SparseOperator
    regions: tuple
    names: tuple
    channels: tuple
    B: tuple
    exits: tuple

    @classmethod
    def load(cls, spec):
        if spec.get("schema") != "dynacomp.network-model/1":
            raise ValueError("Unknown network model schema")
        op = SparseOperator.from_entries(spec["n"], spec["transitions"])
        # Reject individual negative entries, even if duplicate summation cancels.
        if any(q(v) < 0 for _, _, v in spec["transitions"]):
            raise ValueError("Network transitions must be nonnegative")
        names = _names(spec["region_names"], "region")
        regions = tuple(spec["node_regions"])
        if len(regions) != op.n or any(type(v) is not int or not 0 <= v < len(names) for v in regions) or set(regions) != set(range(len(names))):
            raise ValueError("Every node needs a region and every region needs a node")
        totals = [q(0)]*op.n
        for _, j, v in op.entries:
            totals[j] += v
        if any(v > 1 for v in totals):
            raise ValueError("Transition columns must sum to at most one")
        inputs = spec["inputs"]
        channels = _names([item["name"] for item in inputs], "input")
        b = [[q(0)]*len(channels) for _ in range(op.n)]
        for k, item in enumerate(inputs):
            for node, weight in item["distribution"]:
                if type(node) is not int or not 0 <= node < op.n or q(weight) < 0:
                    raise ValueError("Invalid input distribution")
                b[node][k] += q(weight)
            if sum(row[k] for row in b) != 1:
                raise ValueError("Each input distribution must sum exactly to one")
        return cls(op, regions, names, channels, matrix(b), tuple(1-v for v in totals))

    def output(self, x):
        stock, dispatch = [q(0)]*len(self.names), [q(0)]*len(self.names)
        for i, value in enumerate(x):
            stock[self.regions[i]] += value
            dispatch[self.regions[i]] += self.exits[i]*value
        return tuple(stock+dispatch)


def _closed_coefficients(net, classes):
    """Check closure by column sums, independently of refinement discovery."""
    if len(classes) != net.op.n or any(type(c) is not int or c < 0 for c in classes):
        raise ValueError("Invalid aggregate classes")
    rank = max(classes)+1
    if set(classes) != set(range(rank)):
        raise ValueError("Aggregate classes must be consecutive and nonempty")
    representatives = [classes.index(c) for c in range(rank)]
    column = [[q(0)]*rank for _ in classes]
    for i, j, v in net.op.entries:
        column[j][classes[i]] += v
    for j in range(net.op.n):
        representative = representatives[classes[j]]
        if net.regions[j] != net.regions[representative] or net.exits[j] != net.exits[representative] or column[j] != column[representative]:
            raise ValueError("Aggregate does not preserve transition, stock or dispatch outputs")
    g = tuple(tuple(column[representatives[c]][d] for c in range(rank)) for d in range(rank))
    h = [[q(0)]*len(net.channels) for _ in range(rank)]
    for j, row in enumerate(net.B):
        for k, value in enumerate(row):
            h[classes[j]][k] += value
    d = [[q(0)]*rank for _ in range(2*len(net.names))]
    for c, j in enumerate(representatives):
        d[net.regions[j]][c] = q(1)
        d[len(net.names)+net.regions[j]][c] = net.exits[j]
    return g, matrix(h), matrix(d)


def compile_network(spec, max_groups=128):
    net = Network.load(spec)
    discovered = aggregate_partition(net.op, [(net.regions[j], net.exits[j]) for j in range(net.op.n)], max_groups)
    classes = discovered["classes"]
    g, h, d = _closed_coefficients(net, classes)
    return {"schema": "dynacomp.network-plan/1", "source_sha256": fingerprint(spec),
            "model": spec, "classes": classes, "G": encoded(g), "H": encoded(h), "D": encoded(d),
            "rank": len(g), "refinement_rounds": discovered["rounds"],
            "claim": "exact regional stock and dispatch for all initial states and input words; coarsest aggregate refinement of region/exit labels"}


def replay_network(packet):
    if packet.get("schema") != "dynacomp.network-plan/1" or fingerprint(packet["model"]) != packet["source_sha256"]:
        raise ValueError("Unknown plan schema or changed source model")
    net = Network.load(packet["model"])
    if type(packet["rank"]) is not int or packet["rank"] < 1 or packet["rank"] > net.op.n or len(packet["classes"]) != net.op.n or any(type(c) is not int or not 0 <= c < packet["rank"] for c in packet["classes"]):
        raise ValueError("Invalid plan rank or classes")
    g, h, d = _closed_coefficients(net, packet["classes"])
    if len(g) != packet["rank"] or any(matrix(packet[key]) != value for key, value in (("G", g), ("H", h), ("D", d))):
        raise ValueError("Network plan identities fail")
    return True


def load_scenarios(spec, net):
    if spec.get("schema") != "dynacomp.network-scenarios/1" or not isinstance(spec.get("scenarios"), list) or not spec["scenarios"]:
        raise ValueError("Nonempty scenario batch required")
    _names([s["name"] for s in spec["scenarios"]], "scenario")
    result = []
    for s in spec["scenarios"]:
        initial = _nonnegative(s["initial_stock"], net.op.n, "initial stock")
        if not isinstance(s["replenishment"], list):
            raise ValueError("Replenishment must be a time-ordered list")
        inputs = tuple(_nonnegative(row, len(net.channels), "input") for row in s["replenishment"])
        floor = _nonnegative(s.get("stock_floor", [0]*len(net.names)), len(net.names), "stock floor")
        result.append((s["name"], initial, inputs, floor))
    return result


def _trace(net, packet, initial, inputs, reduced, exact):
    convert = q if exact else float
    if reduced:
        x = [convert(0)]*packet["rank"]
        for j, value in enumerate(initial):
            x[packet["classes"][j]] += convert(value)
        g, h, d = (tuple(tuple(convert(q(v)) for v in row) for row in packet[k]) for k in ("G", "H", "D"))
        def dot(rows, values):
            return [sum(a*b for a, b in zip(row, values)) for row in rows]
        def output(state):
            return dot(d, state)
        def step(state, u):
            return [a+b for a, b in zip(dot(g, state), dot(h, u))]
    else:
        x = [convert(v) for v in initial]
        entries = [(i, j, convert(v)) for i, j, v in net.op.entries]
        b = [[convert(v) for v in row] for row in net.B]
        exits = [convert(v) for v in net.exits]
        def output(state):
            values = [convert(0)]*(2*len(net.names))
            for j, v in enumerate(state):
                values[net.regions[j]] += v
                values[len(net.names)+net.regions[j]] += exits[j]*v
            return values
        def step(state, u):
            result = [sum(a*v for a, v in zip(row, u)) for row in b]
            for i, j, v in entries:
                result[i] += v*state[j]
            return result
    trace = [output(x)]
    for u in inputs:
        x = step(x, [convert(v) for v in u])
        trace.append(output(x))
    if not exact and any(not math.isfinite(v) for row in trace for v in row):
        raise OverflowError("Nonfinite numerical output; rescale quantities or use exact arithmetic")
    return trace


def run_scenarios(packet, spec, engine="reduced", exact=False, backend="standard"):
    if backend not in ("standard", "numpy") or (exact and backend != "standard"):
        raise ValueError("Backend must be standard or numpy; exact arithmetic needs standard")
    if engine not in ("reduced", "full"):
        raise ValueError("Engine must be reduced or full")
    replay_network(packet)
    net = Network.load(packet["model"])
    results = []
    convert = str if exact else float
    scenarios = load_scenarios(spec, net)
    numerical_traces = {}
    if backend == "numpy":
        from .network_numeric import NumpyEvolution
        import numpy as np
        evolution = NumpyEvolution(net, packet, engine)
        buckets = {}
        for index, (_, initial, inputs, _) in enumerate(scenarios):
            buckets.setdefault(len(inputs), []).append(index)
        for horizon, indices in buckets.items():
            initial = np.asarray([[float(v) for v in scenarios[i][1]] for i in indices]).T
            inputs = np.asarray([[[float(v) for v in row] for row in scenarios[i][2]] for i in indices]).reshape(len(indices), horizon, len(net.channels)).transpose(1, 2, 0)
            output = evolution.simulate(initial, inputs)
            for column, index in enumerate(indices):
                numerical_traces[index] = output[:, :, column].tolist()
    for index, (name, initial, inputs, floor) in enumerate(scenarios):
        trace = numerical_traces[index] if backend == "numpy" else _trace(net, packet, initial, inputs, engine == "reduced", exact)
        r = len(net.names)
        cumulative = [sum(row[r+k] for row in trace[:-1]) for k in range(r)]
        supplied = sum(initial)+sum(sum(u) for u in inputs)
        residual = supplied-sum(trace[-1][:r])-sum(cumulative)
        margins = [[row[k]-(floor[k] if exact else float(floor[k])) for k in range(r)] for row in trace]
        results.append({"name": name, "horizon": len(inputs),
                        "stock_trace": [[convert(v) for v in row[:r]] for row in trace],
                        "dispatch_trace": [[convert(v) for v in row[r:]] for row in trace[:-1]],
                        "cumulative_dispatch": [convert(v) for v in cumulative],
                        "final_stock": [convert(v) for v in trace[-1][:r]],
                        "minimum_stock_margin": [convert(min(row[k] for row in margins)) for k in range(r)],
                        "stock_floor_violations": [sum(row[k] < 0 for row in margins) for k in range(r)],
                        "mass_balance_residual": convert(residual)})
    return {"schema": "dynacomp.network-report/1", "source_sha256": packet["source_sha256"],
            "scenario_sha256": fingerprint(spec), "engine": engine, "backend": backend, "arithmetic": "rational" if exact else "binary64",
            "full_states": net.op.n, "compiled_states": packet["rank"], "region_names": list(net.names),
            "input_names": list(net.channels), "scenarios": results,
            "scope": "fixed linear routing; floor checks are diagnostics, not capacity or demand feedback; binary64 output is not interval certified"}
","dynacomp/network_cli.py":""""Compile inventory networks and report batches of replenishment scenarios."""
import argparse
import csv
import json
from pathlib import Path
from .network import compile_network, replay_network, run_scenarios


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="operation", required=True)
    compile_cmd = sub.add_parser("compile")
    compile_cmd.add_argument("model", type=Path)
    compile_cmd.add_argument("--max-groups", type=int, default=128)
    compile_cmd.add_argument("--output", type=Path, required=True)
    replay_cmd = sub.add_parser("replay")
    replay_cmd.add_argument("plan", type=Path)
    run_cmd = sub.add_parser("run")
    run_cmd.add_argument("plan", type=Path)
    run_cmd.add_argument("scenarios", type=Path)
    run_cmd.add_argument("--engine", choices=("reduced", "full"), default="reduced")
    run_cmd.add_argument("--exact", action="store_true")
    run_cmd.add_argument("--backend", choices=("standard", "numpy"), default="standard")
    run_cmd.add_argument("--output", type=Path, required=True)
    run_cmd.add_argument("--csv", type=Path)
    args = parser.parse_args()
    try:
        if args.operation == "compile":
            result = compile_network(json.loads(args.model.read_text()), args.max_groups)
        else:
            plan = json.loads(args.plan.read_text())
            if args.operation == "replay":
                result = {"accepted": replay_network(plan)}
            else:
                result = run_scenarios(plan, json.loads(args.scenarios.read_text()), args.engine, args.exact, args.backend)
        if args.operation == "run" and args.csv:
            with args.csv.open("w", newline="", encoding="utf-8") as stream:
                writer = csv.writer(stream)
                writer.writerow(["scenario", "region", "final_stock", "cumulative_dispatch", "minimum_stock_margin", "stock_floor_violations"])
                for s in result["scenarios"]:
                    for k, name in enumerate(result["region_names"]):
                        writer.writerow([s["name"], name]+[s[key][k] for key in ("final_stock", "cumulative_dispatch", "minimum_stock_margin", "stock_floor_violations")])
        text = json.dumps(result, indent=2, allow_nan=False)+"\n"
        if hasattr(args, "output"):
            args.output.write_text(text)
        else:
            print(text, end="")
    except (ValueError, KeyError, TypeError, OverflowError, ZeroDivisionError, OSError, ImportError) as exc:
        parser.exit(2, f"dynacomp-network: {exc}\n")


if __name__ == "__main__":
    main()
","dynacomp/network_numeric.py":""""Optional vectorized batch execution shared by the application and benchmark."""
import numpy as np
from scipy.sparse import csr_matrix
from .rational import q


class NumpyEvolution:
    """Prepare an already validated Network/plan pair; columns are scenarios.

    Public JSON entry points validate the exact plan before constructing this
    executor. Numeric traces use ordinary binary64 arithmetic, not intervals.
    """
    def __init__(self, net, packet, engine):
        self.n, self.inputs, self.outputs = net.op.n, len(net.channels), 2*len(net.names)
        self.engine = engine
        if engine == "full":
            rows,cols,values=zip(*net.op.entries) if net.op.entries else ([],[],[])
            self.a=csr_matrix((np.asarray(values,dtype=float),(rows,cols)),shape=(net.op.n,net.op.n))
            self.b=csr_matrix(np.asarray(net.B,dtype=float))
            self.c=csr_matrix(([1.]*net.op.n+list(map(float,net.exits)),
                (list(net.regions)+[len(net.names)+r for r in net.regions],list(range(net.op.n))*2)),shape=(self.outputs,net.op.n))
            self.e=None
        elif engine == "reduced":
            self.e=csr_matrix((np.ones(net.op.n),(packet["classes"],np.arange(net.op.n))),shape=(packet["rank"],net.op.n))
            self.a,self.b,self.c=(np.asarray([[float(q(v)) for v in row] for row in packet[k]]) for k in ("G","H","D"))
            if packet["rank"]>=32:
                self.a,self.b,self.c=map(csr_matrix,(self.a,self.b,self.c))
        else:
            raise ValueError("Engine must be reduced or full")

    def simulate(self, initial, inputs):
        initial=np.asarray(initial,dtype=float)
        inputs=np.asarray(inputs,dtype=float)
        if initial.ndim != 2 or initial.shape[0] != self.n or initial.shape[1] < 1 or inputs.ndim != 3 or inputs.shape[1:] != (self.inputs,initial.shape[1]):
            raise ValueError("Expected initial (nodes, scenarios), input (steps, channels, scenarios)")
        if not np.isfinite(initial).all() or not np.isfinite(inputs).all() or (initial<0).any() or (inputs<0).any():
            raise ValueError("Finite nonnegative numerical stocks and inputs required")
        state=initial.copy() if self.e is None else self.e@initial
        output=np.empty((len(inputs)+1,self.outputs,initial.shape[1]))
        output[0]=self.c@state
        for t,u in enumerate(inputs):
            state=self.a@state+self.b@u
            output[t+1]=self.c@state
        if not np.isfinite(output).all():
            raise OverflowError("Nonfinite numerical output; rescale quantities or use exact arithmetic")
        return output
","dynacomp/parametric.py":""""Structural versus accidental closure for one real parameter.

Entries of A(t), B(t), C(t) are polynomials in t. A reduction compiled at one
parameter value may be smaller than at nearby values: closure there is an
accident of that coefficient choice. For a real polynomial matrix M(t), let
e_k(t) be the k-th elementary symmetric function of the eigenvalues of
M(t)^T M(t). By Cauchy-Binet, e_k is the sum of squares of all k x k minors of
M, so for real t, rank M(t) >= k exactly when e_k(t) != 0. The generic rank r
is the largest k with e_k not identically zero, and the exceptional real
parameters are precisely the real roots of e_r. Sturm sequences count and
isolate them exactly; rational exceptional values are found exactly.
"""
from fractions import Fraction
from . import upoly as P
from .rational import matrix, rref


def poly_matrix(rows):
    out = tuple(tuple(P.parse(x) for x in row) for row in rows)
    if not out or not out[0] or any(len(r) != len(out[0]) for r in out):
        raise ValueError("Expected a nonempty rectangular parametric matrix")
    return out


def pm_mul(a, b):
    if len(a[0]) != len(b):
        raise ValueError("Matrix dimensions do not match")
    cols = tuple(zip(*b))
    out = []
    for row in a:
        new = []
        for col in cols:
            s = ()
            for x, y in zip(row, col):
                if x and y:
                    s = P.add(s, P.mul(x, y))
            new.append(s)
        out.append(tuple(new))
    return tuple(out)


def pm_transpose(a):
    return tuple(zip(*a))


def pm_eval(a, t):
    return matrix([[P.evaluate(x, t) for x in row] for row in a])


def elementary_symmetric(m):
    """[e_0, ..., e_n] of the eigenvalues of square polynomial matrix m (Faddeev-LeVerrier)."""
    n = len(m)
    coefficient = [P.const(1)]
    mk = tuple(tuple(() for _ in range(n)) for _ in range(n))
    for k in range(1, n+1):
        # M_k = M (M_(k-1) + c_(k-1) I), c_k = -tr(M_k)/k.
        shifted = tuple(tuple(P.add(mk[i][j], coefficient[-1]) if i == j else mk[i][j]
                              for j in range(n)) for i in range(n))
        mk = pm_mul(m, shifted)
        trace = ()
        for i in range(n):
            trace = P.add(trace, mk[i][i])
        coefficient.append(P.scale(trace, Fraction(-1, k)))
    # coefficient[k] multiplies lambda^(n-k); e_k = (-1)^k coefficient[k].
    return [P.scale(c, (-1)**k) for k, c in enumerate(coefficient)]


def rank_profile(m):
    """Generic rank, drop polynomial and exceptional real parameters of m(t)."""
    gram = pm_mul(pm_transpose(m), m)
    e = elementary_symmetric(gram)
    r = max(k for k, p in enumerate(e) if p)
    if r == 0:
        return {"generic_rank": 0, "drop_polynomial": ["1"], "rational_exceptions": [],
                "irrational_exceptions": [], "real_exception_count": 0, "witness": "0"}
    drop = P.squarefree(e[r])
    rational, irrational = P.real_roots(drop)
    witness = next(Fraction(k) for k in _small_integers() if P.evaluate(drop, k))
    return {"generic_rank": r, "drop_polynomial": P.encode(drop),
            "real_exception_count": len(rational)+len(irrational),
            "rational_exceptions": [{"value": str(x), "rank": rank_at(m, x)} for x in rational],
            "irrational_exceptions": [{"interval": [str(lo), str(hi)]} for lo, hi in irrational],
            "witness": str(witness)}


def _small_integers():
    k = 0
    while True:
        yield k
        if k:
            yield -k
        k += 1


def rank_at(m, t):
    return len(rref(pm_eval(m, t))[1])


def _krylov_stack(a, start, n):
    """[S; S A; ...; S A^(n-1)] for row block S."""
    rows, block = [], start
    for _ in range(n):
        rows.extend(block)
        block = pm_mul(block, a)
    return tuple(rows)


def parametric_analysis(A, B, C):
    """Observable, reachable and minimal (Hankel) orders as functions of t."""
    a, b, c = poly_matrix(A), poly_matrix(B), poly_matrix(C)
    n = len(a)
    if len(a[0]) != n or len(b) != n or len(c[0]) != n:
        raise ValueError("Expected A[n,n], B[n,m], C[p,n]")
    observability = _krylov_stack(a, c, n)
    reachability = pm_transpose(_krylov_stack(pm_transpose(a), pm_transpose(b), n))
    hankel = pm_mul(observability, reachability)
    encode = lambda m: [[P.encode(x) for x in row] for row in m]
    return {"schema": "dynacomp.parametric/1", "arithmetic": "rational polynomial in t",
            "A": encode(a), "B": encode(b), "C": encode(c),
            "observable": rank_profile(observability),
            "reachable": rank_profile(reachability),
            "minimal": rank_profile(hankel),
            "claim": "ranks for real t; exceptional values are exactly the real roots of each drop polynomial"}


def classify(packet, t, quantity="observable"):
    """Is the closure at parameter t structural (generic order) or accidental?"""
    profile = packet[quantity]
    drop = tuple(Fraction(x) for x in profile["drop_polynomial"])
    accidental = P.evaluate(drop, t) == 0
    return {"value": str(Fraction(t)), "quantity": quantity, "accidental": accidental,
            "generic_order": profile["generic_rank"]}


def replay_parametric(packet):
    """Re-derive each profile from the stored model and compare.

    Also evaluates the rank at the generic witness and every rational exception
    directly by rational elimination, independent of the symmetric functions.
    """
    if packet.get("schema") != "dynacomp.parametric/1":
        raise ValueError("Unknown schema")
    fresh = parametric_analysis(packet["A"], packet["B"], packet["C"])
    for key in ("observable", "reachable", "minimal"):
        if fresh[key] != packet[key]:
            raise ValueError(f"{key} profile does not match the model")
    a, b, c = (poly_matrix(packet[k]) for k in ("A", "B", "C"))
    n = len(a)
    stacks = {"observable": _krylov_stack(a, c, n),
              "reachable": pm_transpose(_krylov_stack(pm_transpose(a), pm_transpose(b), n))}
    for key, m in stacks.items():
        profile = packet[key]
        if rank_at(m, Fraction(profile["witness"])) != profile["generic_rank"]:
            raise ValueError(f"{key} witness rank differs from generic rank")
        for x in profile["rational_exceptions"]:
            if rank_at(m, Fraction(x["value"])) >= profile["generic_rank"]:
                raise ValueError(f"{key} exception {x['value']} does not drop rank")
    return True
