def import_mat(path,dt=None,normalize_output=False,require_bounded=False):
    """Import real nonsingular descriptors; preserve coordinates and ZOH outputs.

    Exact rational elimination; bounded sampling when enclosure limits permit.
    Outside those limits the stored-source scope is explicitly uncertified.
    """
    import numpy as np
    from scipy.io import loadmat
    from scipy.linalg import expm
    from scipy.sparse import issparse
    from .rational import matrix,encoded
    from .engineering import descriptor_transform,enclosure,replay_import
    path=Path(path); data=loadmat(path)
    def dense(value):
        value=value.toarray() if issparse(value) else np.asarray(value)
        if value.ndim!=2 or not np.isrealobj(value) or not np.isfinite(value).all():
            raise ValueError('Finite real two-dimensional MAT matrices required')
        return value
    if 'A' not in data or 'B' not in data or 'C' not in data:
        raise ValueError('Explicit A, B, C required to preserve output meaning')
    a,b,c=map(dense,(data[k] for k in ('A','B','C')));n=len(a)
    if not n or a.shape!=(n,n) or b.shape[0]!=n or not b.shape[1] or c.shape[1]!=n or not len(c):
        raise ValueError('MAT matrices have inconsistent dimensions')
    e=dense(data.get('E',np.eye(n)));f=dense(data.get('D',np.zeros((len(c),b.shape[1]))))
    if e.shape!=(n,n) or f.shape!=(len(c),b.shape[1]): raise ValueError('Descriptor or feedthrough dimensions differ')
    def exact(value):
        return matrix([[str(Fraction(v.item())) for v in row] for row in value])
    a,b,c,e,f=map(exact,(a,b,c,e,f))
    sa,sb,descriptor=descriptor_transform(a,b,e)
    divisor=max(sum(abs(v) for v in row) for row in c) if normalize_output else q(1)
    if divisor<=0: raise ValueError('Cannot normalize zero output')
    interval=None
    if dt is not None:
        interval=q(dt)
        if interval<=0 or not np.isfinite(float(interval)): raise ValueError('Positive finite sampling interval required')
        augmented=np.zeros((n+len(b[0]),n+len(b[0])))
        augmented[:n,:n]=np.asarray(sa,dtype=float)*float(interval)
        augmented[:n,n:]=np.asarray(sb,dtype=float)*float(interval)
        if not np.isfinite(augmented).all(): raise ValueError('Sampling input overflows')
        sampled=expm(augmented)
        if not np.isfinite(sampled).all(): raise ValueError('Sampling produced nonfinite coefficients')
        stored_a,stored_b=exact(sampled[:n,:n]),exact(sampled[:n,n:])
        transformation=enclosure(sa,sb,interval,stored_a,stored_b)
        if descriptor['status']!='exact':
            transformation={'status':'uncertified','reason':'continuous sampling after residual-bounded descriptor elimination is not yet enclosed'}
    else:
        stored_a,stored_b=sa,sb
        transformation=descriptor
    if require_bounded and transformation['status']=='uncertified': raise ValueError(transformation['reason'])
    binding={'schema':'dynacomp.engineering-import/1',**{k:encoded(v) for k,v in zip(('A','B','C','E','F'),(a,b,c,e,f))},
             'descriptor':descriptor,'standard_A':encoded(sa),'standard_B':encoded(sb),
             'output_divisor':str(divisor),'sampling_interval':str(interval) if interval is not None else None,'transformation':transformation}
    spec={'schema':'dynacomp.workload/1','name':path.stem,
          'model':{'A':encoded(stored_a),'B':encoded(stored_b),'C':encoded(tuple(tuple(v/divisor for v in row) for row in c))},
          'feedthrough':encoded(tuple(tuple(v/divisor for v in row) for row in f)),
          'output_input_semantics':'right-continuous-terminal-hold','import_certificate':binding,
          'initial_center':[0]*n,'initial_radius':[1]*n,'input_radii':[[1]*len(b[0]) for _ in range(20)],
          'tolerance':'1/100','min_rank':1,'max_rank':min(16,n),
          'provenance':{'mat_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'sampling_interval':binding['sampling_interval'],
                        'output_divisor':str(divisor),'scope':'exact stored coefficients; bounded ZOH sampling when replay reports bounded; sampling/physical errors otherwise unbounded; physical calibration always unbounded'}}
    replay_import(spec)
    return spec


def simulate_plan(folder,method,initial,inputs):
    """Execute a saved, independently checked plan on customer-supplied arrays."""
    folder=Path(folder)
    plan=read_json(folder/'plan.json')
    if plan.get('schema')!='dynacomp.pilot-plan/1' or digest(plan['workload'])!=plan['workload_sha256']:
        raise ValueError('Invalid saved workload plan')
    result=plan['methods'][method]
    if not result['accepted']:
        raise ValueError('Requested method did not meet the workload target')
    packet=_load_packet(folder,result)
    model,domain,tol,_,_=workload(plan['workload'])
    source=packet['source'];center,radius,radii,means=domain
    if (digest(source['model'])!=digest(model.spec()) or q(packet['tolerance'])!=tol or
        tuple(map(q,source['initial_center']))!=center or tuple(map(q,source['initial_radius']))!=radius or
        tuple(tuple(map(q,row)) for row in source['input_radii'])!=radii or
        tuple(tuple(map(q,row)) for row in source['input_centers'])!=means):
        raise ValueError('Saved packet differs from workload contract')
    from .engineering import output_contract, EngineeringRunner
    contract=output_contract(plan['workload'],model,domain,packet)
    upper=max(q(a)+q(b) for row,extra in zip(packet['combined_output_upper'],contract['additional_output_upper']) for a,b in zip(row,extra))
    if result.get('engineering',contract)!=contract or q(result.get('engineering_upper',upper))!=upper or upper>tol:
        raise ValueError('Engineering contract or tolerance does not replay')
    return EngineeringRunner(PreparedSequential(packet),contract).simulate(initial,inputs)


def main(argv=None):
    parser = argparse.ArgumentParser(description='Compile and evaluate a matched-accuracy workload')
    sub = parser.add_subparsers(dest='command',required=True)
    for name in ('compile','evaluate'):
        p = sub.add_parser(name); p.add_argument('spec'); p.add_argument('--output',required=True)
        if name=='evaluate':
            p.add_argument('--queries',type=int,default=256);p.add_argument('--trials',type=int,default=7)
            p.add_argument('--batches',type=int,default=1000)
    p = sub.add_parser('run');p.add_argument('folder');p.add_argument('--queries',type=int,default=256)
    p.add_argument('--trials',type=int,default=7);p.add_argument('--batches',type=int,default=1000)
    p = sub.add_parser('simulate');p.add_argument('folder');p.add_argument('--method',choices=['observable','balanced'],default='observable')
    p.add_argument('--initial',required=True);p.add_argument('--inputs',required=True);p.add_argument('--output',required=True)
    p = sub.add_parser('import-mat');p.add_argument('mat');p.add_argument('--dt');p.add_argument('--normalize-output',action='store_true');p.add_argument('--require-bounded',action='store_true');p.add_argument('--output',required=True)
    args = parser.parse_args(argv)
    if args.command=='simulate':
        import numpy as np
        result=simulate_plan(args.folder,args.method,np.load(args.initial,allow_pickle=False),np.load(args.inputs,allow_pickle=False))
        np.save(args.output,result);print(args.output);return
    if args.command=='import-mat':
        spec = import_mat(args.mat,args.dt,args.normalize_output,args.require_bounded)
        Path(args.output).write_text(json.dumps(spec,indent=2)+'\n');print(args.output);return
    if args.command in ('compile','evaluate'):
        plan = compile_workload(read_json(args.spec),args.output)
        if args.command=='compile':
            print(json.dumps({name:{'accepted':r['accepted'],'rank':r.get('rank')} for name,r in plan['methods'].items()}));return
        folder = args.output
    else:
        folder = args.folder
    result = evaluate_plan(folder,args.queries,args.trials,args.batches)
    print(json.dumps({name:{k:r[k] for k in ('rank','combined_upper','warm_speedup','break_even_batches','total_speedup')} for name,r in result['methods'].items()},indent=2))


if __name__=='__main__':
    main()
","dynacomp/polynomial.py":""""Exact autonomous polynomial observable closure, with explicit resource limits."""
from .rational import q, row_basis, coordinates, encoded, matrix


def clean(p):
    return {tuple(k): q(v) for k, v in p.items() if q(v)}


def validate(p, n):
    p = clean(p)
    if any(len(k) != n or any(type(e) is not int or e < 0 for e in k) for k in p):
        raise ValueError("Invalid monomial exponents")
    return p


def add(p, r):
    out = dict(p)
    for k, v in r.items():
        out[k] = out.get(k, q(0)) + v
    return clean(out)


def scale(p, c):
    return clean({k: v*c for k, v in p.items()})


def multiply(p, r):
    out = {}
    for k, v in p.items():
        for l, w in r.items():
            m = tuple(a+b for a, b in zip(k, l))
            out[m] = out.get(m, q(0)) + v*w
    return clean(out)


def compose(p, update, max_degree=32, max_terms=10000, variables=None):
    n = len(update) if variables is None else variables
    one = {(0,)*n: q(1)}
    result = {}
    for exponent, coefficient in p.items():
        term = scale(one, coefficient)
        for i, power in enumerate(exponent):
            for _ in range(power):
                term = multiply(term, update[i])
                if len(term) > max_terms or any(sum(k) > max_degree for k in term):
                    raise OverflowError("Polynomial expansion exceeded resource limit")
        result = add(result, term)
        if len(result) > max_terms:
            raise OverflowError("Polynomial expansion exceeded term limit")
    return result


def evaluate(p, x):
    total = q(0)
    for k, coefficient in p.items():
        term = coefficient
        for v, e in zip(x, k):
            term *= q(v)**e
        total += term
    return total


def as_basis(polynomials):
    keys = sorted(set().union(*(p.keys() for p in polynomials)))
    if not keys:
        return []
    rows = row_basis([[p.get(k, q(0)) for k in keys] for p in polynomials])
    return [clean(dict(zip(keys, row))) for row in rows]


def coeffs(p, basis):
    keys = sorted(set(p).union(*(b.keys() for b in basis)))
    return coordinates([p.get(k, q(0)) for k in keys],
                       matrix([[b.get(k, q(0)) for k in keys] for b in basis]))


def pack(p):
    return [{"exponent": list(k), "coefficient": str(v)} for k, v in sorted(p.items())]


def unpack(terms, n):
    out = {}
    for term in terms:
        k = tuple(term["exponent"])
        out[k] = out.get(k, q(0)) + q(term["coefficient"])
    return validate(out, n)


def compile_polynomial(update, targets, max_degree=12, max_features=64, max_rounds=32):
    n = len(update)
    if not n or max_features < 1 or max_rounds < 0 or max_degree < 0:
        raise ValueError("Invalid dimensions or limits")
    update = [validate(p, n) for p in update]
    targets = [validate(p, n) for p in targets]
    basis = as_basis(targets)
    if not basis:
        raise ValueError("Need a nonzero target")
    dimensions = [len(basis)]
    for _ in range(max_rounds+1):
        if len(basis) > max_features or any(sum(k) > max_degree for p in basis for k in p):
            return {"status": "resource_limit", "dimensions": dimensions, "reason": "feature/degree limit"}
        try:
            pulled = [compose(p, update, max_degree=max_degree) for p in basis]
        except OverflowError as exc:
            return {"status": "resource_limit", "dimensions": dimensions, "reason": str(exc)}
        enlarged = as_basis(basis+pulled)
        if len(enlarged) == len(basis):
            return {"schema": "dynacomp.polynomial/1", "status": "exact", "variables": n,
                    "update": [pack(p) for p in update], "targets": [pack(p) for p in targets],
                    "features": [pack(p) for p in basis],
                    "G": encoded([coeffs(p, basis) for p in pulled]),
                    "D": encoded([coeffs(p, basis) for p in targets]), "dimensions": dimensions}
        basis = enlarged
        dimensions.append(len(basis))
    return {"status": "resource_limit", "dimensions": dimensions, "reason": "round limit"}


def replay_polynomial(packet):
    if packet.get("schema") != "dynacomp.polynomial/1" or packet.get("status") != "exact":
        raise ValueError("Need an exact polynomial packet")
    n = packet["variables"]
    update = [unpack(p, n) for p in packet["update"]]
    targets = [unpack(p, n) for p in packet["targets"]]
    basis = [unpack(p, n) for p in packet["features"]]
    if len(update) != n or not basis or len(as_basis(basis)) != len(basis):
        raise ValueError("Invalid update or dependent features")
    g, d = matrix(packet["G"]), matrix(packet["D"])
    if len(g) != len(basis) or len(g[0]) != len(basis) or len(d) != len(targets) or len(d[0]) != len(basis):
        raise ValueError("Coefficient matrix dimensions do not match")
    # Replay arbitrary accepted degrees with a limit informed by actual packet data.
    degree = max([sum(k) for p in update+basis+targets for k in p] or [0])
    for feature, row in zip(basis, g):
        rhs = {}
        for b, c in zip(basis, row):
            rhs = add(rhs, scale(b, c))
        if compose(feature, update, max_degree=max(32, degree*degree)) != rhs:
            raise ValueError("Polynomial transition identity fails")
    for target, row in zip(targets, d):
        rhs = {}
        for b, c in zip(basis, row):
            rhs = add(rhs, scale(b, c))
        if target != rhs:
            raise ValueError("Polynomial target identity fails")
    return True


def split_inputs(p, n):
    """Group a polynomial in (x, u) by input monomial: {u-exponent: poly in x}."""
    parts = {}
    for k, v in p.items():
        state, control = k[:n], k[n:]
        part = parts.setdefault(control, {})
        key = state + (0,)*len(control)
        part[key] = part.get(key, q(0)) + v
    return {m: clean(part) for m, part in parts.items() if clean(part)}


def compile_controlled_polynomial(update, targets, inputs, max_degree=12, max_features=64, max_rounds=32):
    """Exact lifted dynamics z_next = sum_m u^m G_m z for polynomial x_next = F(x, u).

    Update polynomials use n+k variables (state, then inputs); targets use the
    state variables only. Each pulled-back feature is split by input monomial
    and every coefficient polynomial must lie in the feature span. Inputs are
    arbitrary at every step, so no relation among them is assumed.
    """
    k = inputs
    n = len(update)
    if not n or type(k) is not int or k < 0:
        raise ValueError("Invalid dimensions")
    update = [validate(p, n+k) for p in update]
    pad = lambda p: {e + (0,)*(n+k-len(e)): v for e, v in p.items()}
    targets = [validate(pad(p), n+k) for p in targets]
    if any(any(e[n:]) for p in targets for e in p):
        raise ValueError("Targets must not depend on inputs")
    basis = as_basis(targets)
    if not basis:
        raise ValueError("Need a nonzero target")
    dimensions = [len(basis)]
    for _ in range(max_rounds+1):
        if len(basis) > max_features or any(sum(e) > max_degree for p in basis for e in p):
            return {"status": "resource_limit", "dimensions": dimensions, "reason": "feature/degree limit"}
        try:
            pulled = [split_inputs(compose(p, update, max_degree=max_degree, variables=n+k), n) for p in basis]
        except OverflowError as exc:
            return {"status": "resource_limit", "dimensions": dimensions, "reason": str(exc)}
        enlarged = as_basis(basis + [part for parts in pulled for part in parts.values()])
        if len(enlarged) == len(basis):
            monomials = sorted(set().union(*(parts.keys() for parts in pulled)))
            zero = [q(0)]*len(basis)
            blocks = [{"input_exponent": list(m),
                       "G": encoded([coeffs(parts[m], basis) if m in parts else zero for parts in pulled])}
                      for m in monomials]
            return {"schema": "dynacomp.controlled_polynomial/1", "status": "exact",
                    "variables": n, "inputs": k, "update": [pack(p) for p in update],
                    "targets": [pack(p) for p in targets], "features": [pack(p) for p in basis],
                    "blocks": blocks, "D": encoded([coeffs(p, basis) for p in targets]),
                    "dimensions": dimensions}
        basis = enlarged
        dimensions.append(len(basis))
    return {"status": "resource_limit", "dimensions": dimensions, "reason": "round limit"}


def controlled_step(packet, z, u):
    """One reduced step: z_next = sum_m u^m G_m z."""
    out = [q(0)]*len(z)
    for block in packet["blocks"]:
        weight = q(1)
        for value, e in zip(u, block["input_exponent"]):
            weight *= q(value)**e
        if weight:
            for i, row in enumerate(block["G"]):
                out[i] += weight*sum(q(g)*x for g, x in zip(row, z))
    return tuple(out)


def replay_controlled_polynomial(packet):
    if packet.get("schema") != "dynacomp.controlled_polynomial/1" or packet.get("status") != "exact":
        raise ValueError("Need an exact controlled polynomial packet")
    n, k = packet["variables"], packet["inputs"]
    update = [unpack(p, n+k) for p in packet["update"]]
    targets = [unpack(p, n+k) for p in packet["targets"]]
    basis = [unpack(p, n+k) for p in packet["features"]]
    if len(update) != n or not basis or len(as_basis(basis)) != len(basis):
        raise ValueError("Invalid update or dependent features")
    if any(any(e[n:]) for p in targets+basis for e in p):
        raise ValueError("Features and targets must not depend on inputs")
    expected = [{} for _ in basis]
    seen = set()
    for block in packet["blocks"]:
        m = tuple(block["input_exponent"])
        if len(m) != k or m in seen or any(type(e) is not int or e < 0 for e in m):
            raise ValueError("Invalid or repeated input exponent")
        seen.add(m)
        g = matrix(block["G"])
        if len(g) != len(basis) or len(g[0]) != len(basis):
            raise ValueError("Block dimensions do not match")
        monomial = {(0,)*n + m: q(1)}
        for i, row in enumerate(g):
            for b, c in zip(basis, row):
                expected[i] = add(expected[i], scale(multiply(monomial, b), c))
    degree = max([sum(e) for p in update+basis for e in p] or [0])
    for feature, rhs in zip(basis, expected):
        if compose(feature, update, max_degree=max(32, degree*degree), variables=n+k) != rhs:
            raise ValueError("Controlled transition identity fails")
    d = matrix(packet["D"])
    if len(d) != len(targets) or len(d[0]) != len(basis):
        raise ValueError("Decoder dimensions do not match")
    for target, row in zip(targets, d):
        rhs = {}
        for b, c in zip(basis, row):
            rhs = add(rhs, scale(b, c))
        if target != rhs:
            raise ValueError("Polynomial target identity fails")
    return True
