        self.c=c if self.basis is None else c@self.basis
        self.initial_intervals=[(q(c)-q(r),q(c)+q(r)) for c,r in zip(self.packet['initial_center'],self.packet['initial_radius'])]
        self.input_intervals=[[(q(c)-q(r),q(c)+q(r)) for c,r in zip(centers,radii)] for centers,radii in zip(self.packet['input_centers'],self.packet['input_radii'])]
        lower,upper=zip(*(self._float_endpoints(lo,hi) for lo,hi in self.initial_intervals))
        self.initial_lower=np.asarray(lower)[:,None];self.initial_upper=np.asarray(upper)[:,None]
        input_pairs=[[self._float_endpoints(lo,hi) for lo,hi in intervals] for intervals in self.input_intervals]
        self.input_lower=np.asarray([[lo for lo,hi in row] for row in input_pairs]).reshape(self.horizon,self.m,1)
        self.input_upper=np.asarray([[hi for lo,hi in row] for row in input_pairs]).reshape(self.horizon,self.m,1)
        self.cache_stats={'packet_replays':int(engine=='reduced'),'batches':0,'initial_fields_encoded':0}

    @staticmethod
    def _float_endpoints(low,high):
        # The smallest/largest binary64 inside each rational endpoint gives
        # exact box membership for finite binary64 values, without per-value
        # Fraction conversion. Endpoints themselves are compared exactly once.
        def rounded(value,up):
            try:result=float(value)
            except OverflowError:return np.inf if value>0 else -np.inf
            actual=Fraction(result)
            if (up and actual<value) or (not up and actual>value):
                result=float(np.nextafter(result,np.inf if up else -np.inf))
            return result
        return rounded(low,True),rounded(high,False)

    def simulate(self,initial,inputs,mixing,check_domain=True):
        """Return all-time outputs, shape [steps+1, outputs, scenarios].

        initial: [nodes], [nodes,1] or [nodes,scenarios]. inputs: [steps,channels,
        scenarios]. mixing: [steps] or [steps,scenarios], in [0,1], weighting
        the second named mode. Shared fields are projected only once. Disabling
        domain checks is for already-validated workloads, without an input claim.
        """
        initial,inputs,mixing=(np.asarray(v,dtype=float) for v in (initial,inputs,mixing))
        if initial.ndim==1:initial=initial[:,None]
        if inputs.ndim!=3 or inputs.shape[0]!=self.horizon or inputs.shape[1]!=self.m or inputs.shape[2]<1:
            raise ValueError('Wrong input batch dimensions or certified horizon')
        queries=inputs.shape[2]
        if initial.ndim!=2 or initial.shape[0]!=self.n or initial.shape[1] not in (1,queries):raise ValueError('Wrong initial field dimensions')
        if mixing.ndim==1:mixing=mixing[:,None]
        if mixing.shape not in ((self.horizon,1),(self.horizon,queries)) or any(not np.isfinite(v).all() for v in (initial,inputs,mixing)) or (mixing<0).any() or (mixing>1).any():raise ValueError('Finite matching mode interpolation in [0,1] required')
        if check_domain:
            if (initial<self.initial_lower).any() or (initial>self.initial_upper).any():
                raise ValueError('Initial field outside certified box')
            if (inputs<self.input_lower).any() or (inputs>self.input_upper).any():
                raise ValueError('Input outside certified box')
        state=initial.copy() if self.basis is None else self.basis.T@initial
        if state.shape[1]==1 and queries!=1:state=np.repeat(state,queries,axis=1)
        output=np.empty((self.horizon+1,self.p,queries));output[0]=self.c@state
        for t,u in enumerate(inputs):
            alpha=mixing[t]
            state=(1-alpha)*(self.a[0]@state+self.b[0]@u)+alpha*(self.a[1]@state+self.b[1]@u)
            output[t+1]=self.c@state
        if not np.isfinite(output).all():raise OverflowError('Nonfinite numerical output')
        self.cache_stats['batches']+=1
        if self.basis is not None:self.cache_stats['initial_fields_encoded']+=initial.shape[1]
        return output
","dynacomp/proposals.py":""""Snapshot-based numerical proposals, rationalized before algebraic use."""
from fractions import Fraction
from .rational import matrix, transpose, mul, inverse, identity, encoded


def reduced_candidate(model, V):
    """Any independent rational lift gets an exact left inverse and residuals.

    This constructs a candidate, not a claim of invariant closure.
    """
    v = matrix(V)
    if len(v) != len(model.A):
        raise ValueError("Lift must have one row per full-state coordinate")
    vt = transpose(v)
    e = mul(inverse(mul(vt, v)), vt)
    assert mul(e, v) == identity(len(v[0]))
    return {"V": encoded(v), "E": encoded(e), "G": encoded(mul(mul(e, model.A), v)),
            "H": encoded(mul(e, model.B)), "D": encoded(mul(model.C, v)),
            "status": "candidate_requires_error_bound"}


def propose_from_snapshots(model, snapshots, rank, max_denominator=10000):
    """Optional POD proposal. Rationalization can alter rank and is checked."""
    import numpy as np
    x = np.asarray(snapshots, dtype=float)
    if x.ndim != 2 or x.shape[0] != len(model.A) or not np.isfinite(x).all():
        raise ValueError("Expected finite snapshots[n,samples]")
    if type(rank) is not int or not 1 <= rank <= min(x.shape) or max_denominator < 1:
        raise ValueError("Invalid rank or denominator budget")
    u, singular, _ = np.linalg.svd(x, full_matrices=False)
    v = [[Fraction(float(value)).limit_denominator(max_denominator) for value in row]
         for row in u[:, :rank]]
    result = reduced_candidate(model, v)
    result["proposal_method"] = "POD with rationalized basis"
    result["snapshot_singular_values"] = [float(value) for value in singular]
    return result
","dynacomp/ramanujan.py":""""Two-cusp real evaluation of R(exp(-t)) with outward rational endpoints.

Uses the classical product and reciprocity cited in spectral.PAPER. This is
an evaluation algorithm, not a proof of irrationality of odd zeta values.
"""
from fractions import Fraction
from .rational import q
from .enclosures import exp_negative, pi_interval, sqrt_integer, precision, outward
from .spectral import character5, PAPER


def _product(tlo, thi, bits):
    qlo = exp_negative(thi, bits)[0]
    qhi = exp_negative(tlo, bits)[1]
    if qhi >= 1:
        raise ValueError("Cannot separate q from one at this precision")
    count = 1
    while True:
        tail = qhi**(count+1)/((1-qhi)*(1-qhi**(count+1)))
        if tail <= Fraction(1, 1 << bits):
            break
        count *= 2
        if count > 4096:
            raise ValueError("Product budget exhausted")
    # Retain a small dyadic upper bound, rather than serializing a huge power.
    tail = outward(tail, tail, bits)[1]
    lo, hi = exp_negative(thi/5, bits)[0], exp_negative(tlo/5, bits)[1]
    for j in range(1, count+1):
        char = character5(j)
        if char == 1:
            lo *= 1-qhi**j
            hi *= 1-qlo**j
        elif char == -1:
            lo /= 1-qlo**j
            hi /= 1-qhi**j
        lo, hi = outward(lo, hi, bits)
    factor = exp_negative(tail, bits)[0]
    lo, hi = outward(lo*factor, hi/factor, bits)
    return lo, hi, count, tail


def ramanujan_value(t, bits=80):
    """Evaluate a positive rational t using the faster cusp expansion.

    t<6 uses reciprocity; t>=6 uses the direct product. The threshold only
    selects a representation, never extrapolates an unbounded remainder.
    """
    t = q(t)
    precision(bits)
    if t <= 0:
        raise ValueError("Positive t required")
    if t >= 6:
        lo, hi, count, tail = _product(t, t, bits)
        branch = "direct"
    else:
        pilo, pihi = pi_interval(bits)
        rlo, rhi, count, tail = _product(4*pilo*pilo/t, 4*pihi*pihi/t, bits)
        root = sqrt_integer(5, bits)
        philo, phihi = (1+root[0])/2, (1+root[1])/2
        # Reciprocity rearranged to avoid subtracting two nearby constants.
        lo = max(Fraction(0), (1-phihi*rhi)/(phihi+rhi))
        hi = (1-philo*rlo)/(philo+rlo)
        branch = "reciprocal"
    lo, hi = outward(lo, hi, bits)
    return {"schema": "dynacomp.ramanujan-value/1", "t": str(t), "bits": bits,
            "interval": [str(lo), str(hi)], "branch": branch, "product_terms": count,
            "log_product_tail": str(tail), "source_reference": PAPER,
            "claim": "R(exp(-t)) in rational interval, conditional on classical product and reciprocal identities; no floating evaluation error included."}


def replay_ramanujan_value(packet):
    if packet.get("schema") != "dynacomp.ramanujan-value/1":
        raise ValueError("Unknown Ramanujan value schema")
    if ramanujan_value(packet["t"], packet["bits"]) != packet:
        raise ValueError("Two-cusp evaluation or tail differs")
    return True
","dynacomp/rational.py":""""Small exact linear algebra over Q. No numerical rank decisions."""
from fractions import Fraction


def q(value):
    if isinstance(value, float):
        raise TypeError("Use rational strings; binary floats are not exact inputs")
    return Fraction(value)


def matrix(rows):
    result = tuple(tuple(q(x) for x in row) for row in rows)
    if not result or not result[0] or any(len(r) != len(result[0]) for r in result):
        raise ValueError("Expected a nonempty rectangular matrix")
    return result


def identity(n):
    return matrix([[int(i == j) for j in range(n)] for i in range(n)])


def zeros(m, n):
    return matrix([[0] * n for _ in range(m)])


def transpose(a):
    return tuple(zip(*a))


def mul(a, b):
    if len(a[0]) != len(b):
        raise ValueError("Matrix dimensions do not match")
    return tuple(tuple(sum(x*y for x, y in zip(row, col)) for col in transpose(b)) for row in a)


def sub(a, b):
    if len(a) != len(b) or len(a[0]) != len(b[0]):
        raise ValueError("Matrix dimensions do not match")
    return tuple(tuple(x-y for x, y in zip(r, s)) for r, s in zip(a, b))


def mv(a, x):
    if len(a[0]) != len(x):
        raise ValueError("Vector dimension does not match")
    return tuple(sum(v*q(w) for v, w in zip(row, x)) for row in a)


def addv(x, y):
    if len(x) != len(y):
        raise ValueError("Vector dimensions do not match")
    return tuple(a+b for a, b in zip(x, y))


def rref(rows):
    a = [list(row) for row in matrix(rows)]
    m, n = len(a), len(a[0])
    pivots = []
    for j in range(n):
        k = next((i for i in range(len(pivots), m) if a[i][j]), None)
        if k is None:
            continue
        i = len(pivots)
        a[i], a[k] = a[k], a[i]
        divisor = a[i][j]
        a[i] = [v/divisor for v in a[i]]
        for k in range(m):
            if k != i:
                coefficient = a[k][j]
                a[k] = [v-coefficient*w for v, w in zip(a[k], a[i])]
        pivots.append(j)
        if len(pivots) == m:
            break
    return tuple(tuple(row) for row in a), tuple(pivots)


def row_basis(rows):
    reduced, pivots = rref(rows)
    return reduced[:len(pivots)]


def nullspace(a):
    reduced, pivots = rref(a)
    vectors = []
    for j in range(len(a[0])):
        if j not in pivots:
            v = [q(0)] * len(a[0])
            v[j] = q(1)
            for i, k in enumerate(pivots):
                v[k] = -reduced[i][j]
            vectors.append(tuple(v))
    return tuple(vectors)


def coordinates(row, basis):
    """Express a row in a full-row-rank basis, or return None."""
    reduced, pivots = rref(basis)
    if len(pivots) != len(basis):
        raise ValueError("Basis must have independent rows")
    # Solve B^T c = row^T using an augmented system.
    augmented = tuple(tuple(col) + (q(target),) for col, target in zip(transpose(basis), row))
    result, _ = rref(augmented)
    d = len(basis)
    if any(not any(r[:d]) and r[d] for r in result):
        return None
    answer = [q(0)] * d
    for r in result:
        pivot = next((j for j in range(d) if r[j]), None)
        if pivot is not None:
            answer[pivot] = r[d]
    return tuple(answer)


def norm_inf(a):
    return max(sum(abs(v) for v in row) for row in a)


def vector_norm(x):
    return max((abs(q(v)) for v in x), default=q(0))


def encoded(a):
    return [[str(v) for v in row] for row in a]


def inverse(a):
    n = len(a)
    if len(a[0]) != n:
        raise ValueError("Expected square matrix")
    augmented = tuple(tuple(row)+tuple(int(i == j) for j in range(n)) for i, row in enumerate(a))
    reduced, pivots = rref(augmented)
    if pivots[:n] != tuple(range(n)):
        raise ValueError("Singular matrix")
    return tuple(row[n:] for row in reduced)


def pivot_coordinates(row, basis, pivots):
    """Coordinates in a reduced row echelon basis are its pivot entries; None if outside the span."""
    c = tuple(q(row[p]) for p in pivots)
    rebuilt = [sum(ci*b[j] for ci, b in zip(c, basis) if ci) for j in range(len(row))]
    return c if all(q(x) == y for x, y in zip(row, rebuilt)) else None
","dynacomp/realization.py":""""Minimal input-output realization with an independent Hankel-rank certificate.

The observable quotient keeps every distinction any initial state could make.
When the system starts at rest (x0 = 0) only the reachable part matters, and
the order can drop further: to the rank of the block Hankel matrix of Markov
parameters C A^k B, which no realization of the same input-output map can beat.
"""
from .krylov import krylov, vecmat, matvec
from .linear import LinearModel
from .rational import matrix, mul, coordinates, encoded, rref, transpose, q, mv, addv


def _block_rank(rows):
    return len(rref(rows)[1]) if rows else 0


def minimal_realization(model):
    """Kalman-minimal (G, H, D) with identical Markov parameters.

    Stage 1 keeps the reachable column space P: A P = P F, B = P K.
    Stage 2 takes the observable row space of (F, K, CP): E F = G E, E K = H,
    D E = C P. Then C A^k B = D G^k H for every k.
    """
    a, b, c = model.A, model.B, model.C
    m, p = len(b[0]), len(c)
    columns = [(j, tuple(row[j] for row in b)) for j in range(m)]
    reach, reach_labels = krylov(columns, {"A": lambda v: matvec(a, v)})
    if not reach:
        raise ValueError("No input reaches the state; the input-output map is zero")
    P = transpose(reach)
    F = transpose(tuple(coordinates(matvec(a, v), reach) for v in reach))
    K = transpose(tuple(coordinates(col, reach) for _, col in columns))
    cp = mul(c, P)
    rows = [(i, cp[i]) for i in range(p)]
    obs, obs_labels = krylov(rows, {"A": lambda v: vecmat(v, F)})
    if not obs:
        raise ValueError("No output observes a reachable state; the input-output map is zero")
    E = obs
    G = tuple(coordinates(vecmat(row, F), E) for row in E)
    H = mul(E, K)
    D = tuple(coordinates(row, E) for row in cp)
    s = len(E)
    # Hankel certificate: experiments from the minimal system's own Krylov spans.
    hrow_vectors, hrow_labels = krylov([(i, D[i]) for i in range(p)], {"A": lambda v: vecmat(v, G)})
    hcol_vectors, hcol_labels = krylov([(j, tuple(row[j] for row in H)) for j in range(m)],
                                       {"A": lambda v: matvec(G, v)})
    assert len(hrow_vectors) == len(hcol_vectors) == s
    hankel_rows = [[i, len(w)] for i, w in hrow_labels]
    hankel_cols = [[j, len(w)] for j, w in hcol_labels]
    return {"schema": "dynacomp.realization/1", "arithmetic": "rational",
            "A": encoded(a), "B": encoded(b), "C": encoded(c),
            "P": encoded(P), "F": encoded(F), "K": encoded(K),
            "E": encoded(E), "G": encoded(G), "H": encoded(H), "D": encoded(D),
            "reachable_dimension": len(reach), "minimal_order": s,
            "hankel_rows": hankel_rows, "hankel_columns": hankel_cols,
            "claim": "zero-initial-state input-output map preserved; order equals Hankel rank"}


def markov_parameter(a, b, c, k):
    """C A^k B, computed by k vector-matrix products per output row."""
    rows = c
    for _ in range(k):
        rows = tuple(vecmat(r, a) for r in rows)
    return mul(rows, b)


def hankel_submatrix(a, b, c, row_labels, col_labels):
    """Entries C_i A^(k+l) B_j, building C A^t once for t up to the largest k+l."""
    top = max(k for _, k in row_labels) + max(l for _, l in col_labels)
    rows, markov = c, []
    for _ in range(top+1):
        markov.append(mul(rows, b))
        rows = tuple(vecmat(r, a) for r in rows)
    return tuple(tuple(markov[k+l][i][j] for j, l in col_labels) for i, k in row_labels)


def replay_realization(packet):
    """Accept identities, then prove minimality from the ORIGINAL Markov parameters."""
    if packet.get("schema") != "dynacomp.realization/1":
        raise ValueError("Unknown schema")
    model = LinearModel.from_rows(packet["A"], packet["B"], packet["C"])
    P, F, K = (matrix(packet[k]) for k in ("P", "F", "K"))
    E, G, H, D = (matrix(packet[k]) for k in ("E", "G", "H", "D"))
    n, m, p = len(model.A), len(model.B[0]), len(model.C)
    r, s = len(F), len(G)
    if len(P) != n or len(P[0]) != r or len(F[0]) != r or len(K) != r or len(K[0]) != m:
        raise ValueError("Reachability block dimensions do not match")
    if len(E) != s or len(E[0]) != r or len(G[0]) != s or len(H) != s or len(D) != p or len(D[0]) != s:
        raise ValueError("Observability block dimensions do not match")
    if mul(model.A, P) != mul(P, F) or mul(P, K) != model.B:
        raise ValueError("Reachability identities AP=PF, B=PK fail")
    if mul(E, F) != mul(G, E) or mul(E, K) != H or mul(D, E) != mul(model.C, P):
        raise ValueError("Observability identities EF=GE, EK=H, DE=CP fail")
    rows = [tuple(x) for x in packet["hankel_rows"]]
    cols = [tuple(x) for x in packet["hankel_columns"]]
    if len(rows) != s or len(cols) != s:
        raise ValueError("Hankel certificate must be square of minimal order")
    for i, k in rows:
        if type(i) is not int or type(k) is not int or not 0 <= i < p or k < 0:
            raise ValueError("Invalid Hankel row label")
    for j, l in cols:
        if type(j) is not int or type(l) is not int or not 0 <= j < m or l < 0:
            raise ValueError("Invalid Hankel column label")
    if _block_rank(hankel_submatrix(model.A, model.B, model.C, rows, cols)) != s:
        raise ValueError("Hankel submatrix is singular: minimality not established")
    return True


def simulate_zero_state(G, H, D, inputs):
    z = tuple(q(0) for _ in G)
    outputs = [mv(D, z)]
    for u in inputs:
        z = addv(mv(G, z), mv(H, u))
        outputs.append(mv(D, z))
    return tuple(outputs)
","dynacomp/robust.py":""""Sharp box errors under arbitrary time-varying convex mode combinations.

Commuting full/projected operators compress endpoint words into a count lattice.
A signed-support dynamic program retains order-dependent forcing while avoiding
word enumeration. Noncommuting families use budgeted endpoint enumeration.
Both routes exploit multi-affinity: a worst case occurs at mode vertices.
"""
from itertools import product
from .uniform import SparseLinearModel,_domain,_project,_sign
from .rational import q,matrix,mul,mv,sub,encoded,addv
from .krylov import Echelon


def _models(modes,C):
    if not isinstance(modes,dict) or not modes or any(not isinstance(k,str) or not k for k in modes):
        raise ValueError('Nonempty named modes required')
    if any('C' in spec and matrix(spec['C'])!=matrix(C) for spec in modes.values()):
        raise ValueError('Mode targets must match shared target')
    models={name:SparseLinearModel.from_spec({**spec,'C':C}) for name,spec in modes.items()}
    first=next(iter(models.values()))
    if any(m.operator.n!=first.operator.n or len(m.B[0])!=len(first.B[0]) for m in models.values()):
        raise ValueError('Modes must share state/input dimensions')
    return models


def _sparse_product(a,b):
    rows={}
    for i,j,v in b.entries:rows.setdefault(i,[]).append((j,v))
    out={}
    for i,k,v in a.entries:
        for j,w in rows.get(k,[]):out[i,j]=out.get((i,j),q(0))+v*w
    return {key:value for key,value in out.items() if value}


def _commute(models,gs):
    names=list(models)
    for i,s in enumerate(names):
        for t in names[i+1:]:
            if _sparse_product(models[s].operator,models[t].operator)!=_sparse_product(models[t].operator,models[s].operator) or mul(gs[s],gs[t])!=mul(gs[t],gs[s]):
                return False
    return True


def _candidate(models,rows):
    first=next(iter(models.values()))
    v,e,_,_,d=_project(first,rows)
    gs={s:mul(m.operator.pullback(e),v) for s,m in models.items()}
    hs={s:mul(e,m.B) for s,m in models.items()}
    return v,e,gs,hs,d


def _dot(a,b):return sum(x*y for x,y in zip(a,b))

def _sharp_for_word(models,candidate,domain,word,output):
    v,e,gs,hs,d=candidate
    center,radius,us,means=domain
    first=next(iter(models.values()))
    a,b=(first.C[output],),(d[output],)
    kernels=[None]*len(word)
    for j in range(len(word)-1,-1,-1):
        s=word[j]
        kernels[j]=sub(mul(a,models[s].B),mul(b,hs[s]))[0]
        a=models[s].operator.pullback(a);b=mul(b,gs[s])
    k=sub(a,mul(b,e))[0]
    mean=_dot(k,center)+sum(_dot(row,means[j]) for j,row in enumerate(kernels))
    width=sum(abs(x)*r for x,r in zip(k,radius))+sum(sum(abs(x)*r for x,r in zip(row,us[j])) for j,row in enumerate(kernels))
    return abs(mean)+width,k,kernels,(-1 if mean<0 else 1)


def _witness(models,candidate,domain,time,output,word,orientation,bound):
    _,k,kernels,_=_sharp_for_word(models,candidate,domain,word,output)
    center,radius,us,means=domain
    x0=[str(c+orientation*_sign(a)*r) for c,a,r in zip(center,k,radius)]
    inputs=[]
    for j,(mean,radii) in enumerate(zip(means,us)):
        row=kernels[j] if j<time else (q(0),)*len(mean)
        inputs.append([str(c+orientation*_sign(a)*r) for c,a,r in zip(mean,row,radii)])
    names=list(models)
    return {'time':time,'output':output,'modes':list(word)+[names[0]]*(len(us)-time),
            'x0':x0,'inputs':inputs,'signed_error':str(orientation*bound)}


def switching_box_bound(models,candidate,domain,max_symbolic_states=10000):
    """Exact worst output errors for all endpoint words and box choices.

    The same suprema cover independently chosen convex weights at every time.
    Resource exhaustion raises rather than emitting an accepted partial bound.
    """
    v,e,gs,hs,d=candidate
    first=next(iter(models.values()));names=list(models);p=len(first.C)
    center,radius,us,means=domain;horizon=len(us)
    if type(max_symbolic_states) is not int or max_symbolic_states<1:
        raise ValueError('Positive symbolic-state budget required')
    exact=mul(d,e)==first.C and all(m.operator.pullback(e)==mul(gs[s],e) and mul(e,m.B)==hs[s] for s,m in models.items())
    if exact:
        envelopes=[[q(0)]*p for _ in range(horizon+1)]
        engine='exact_common_closure';states=1
        worst=(q(0),0,0,(),1)
    elif _commute(models,gs):
        engine='commuting_count_lattice'
        root=(0,)*len(names)
        # a,b are row blocks C A_suffix and D G_suffix. Commutation makes
        # them independent of suffix order; input contributions still aren't.
        cache={root:(first.C,d)};layers=[[root]]
        transitions={}
        for depth in range(horizon):
            layer=[]
            for count in layers[-1]:
                a,b=cache[count]
                for index,s in enumerate(names):
                    after=list(count);after[index]+=1;after=tuple(after)
                    if after not in cache:
                        if len(cache)>=max_symbolic_states:raise OverflowError('Switching symbolic-state budget exhausted')
                        cache[after]=(models[s].operator.pullback(a),mul(b,gs[s]));layer.append(after)
                    transitions[count,s]=sub(mul(a,models[s].B),mul(b,hs[s]))
            layers.append(layer)
        initial={count:sub(a,mul(b,e)) for count,(a,b) in cache.items()}
        states=len(cache);envelopes=[];worst=None
