from dataclasses import dataclass
from .rational import q, matrix, row_basis, rref, pivot_coordinates, mul, encoded, mv, addv
from .krylov import krylov


@dataclass(frozen=True)
class SparseOperator:
    n: int
    entries: tuple

    @classmethod
    def from_entries(cls, n, entries):
        if type(n) is not int or n < 1:
            raise ValueError("Positive operator dimension required")
        values = {}
        for i, j, value in entries:
            if type(i) is not int or type(j) is not int or not 0 <= i < n or not 0 <= j < n:
                raise ValueError("Invalid sparse index")
            values[i, j] = values.get((i, j), q(0)) + q(value)
        return cls(n, tuple((i, j, value) for (i, j), value in sorted(values.items()) if value))

    def pullback(self, rows):
        if any(len(row) != self.n for row in rows):
            raise ValueError("Wrong row width")
        out = []
        for row in rows:
            result = [q(0)]*self.n
            for i, j, value in self.entries:
                result[j] += row[i]*value
            out.append(tuple(result))
        return tuple(out)

    def step(self, x):
        if len(x) != self.n:
            raise ValueError("Wrong state size")
        out = [q(0)]*self.n
        for i, j, value in self.entries:
            out[i] += value*q(x[j])
        return tuple(out)


def compile_sparse(operator, B, C, max_rank=128):
    """Observable closure by labeled Krylov search, then one final reduction.

    The incremental echelon tests each pullback once instead of re-reducing
    the whole span every round; coordinates in the final reduced basis are
    read off its pivot columns.
    """
    b, c = matrix(B), matrix(C)
    if len(b) != operator.n or len(c[0]) != operator.n or max_rank < 1:
        raise ValueError("Invalid input/target dimensions or rank limit")
    try:
        rows, labels = krylov([(i, row) for i, row in enumerate(c)],
                              {"A": lambda v: operator.pullback((v,))[0]}, limit=max_rank)
    except OverflowError:
        raise OverflowError("Observable rank exceeded sparse compilation limit") from None
    if not rows:
        raise ValueError("Need a nonzero target")
    e, pivots = rref(rows)
    ea = operator.pullback(e)
    ranks = [len(row_basis(c))]
    for depth in range(1, max(len(w) for _, w in labels)+1):
        ranks.append(sum(1 for _, w in labels if len(w) <= depth))
    return {"schema": "dynacomp.sparse/1", "n": operator.n,
            "entries": [[i, j, str(v)] for i, j, v in operator.entries],
            "B": encoded(b), "C": encoded(c), "E": encoded(e),
            "G": encoded([pivot_coordinates(row, e, pivots) for row in ea]),
            "H": encoded(mul(e, b)), "D": encoded([pivot_coordinates(row, e, pivots) for row in c]),
            "ranks": ranks}


def replay_sparse(packet):
    if packet.get("schema") != "dynacomp.sparse/1":
        raise ValueError("Unknown schema")
    op = SparseOperator.from_entries(packet["n"], packet["entries"])
    b, c, e, g, h, d = (matrix(packet[k]) for k in ("B", "C", "E", "G", "H", "D"))
    if len(b) != op.n or len(e[0]) != op.n or len(row_basis(e)) != len(e):
        raise ValueError("Invalid dimensions or dependent encoder")
    if op.pullback(e) != mul(g, e) or mul(e, b) != h or mul(d, e) != c:
        raise ValueError("Sparse reduction identities fail")
    return True
","dynacomp/sparse_family.py":""""Common sparse observable closure, including time-varying affine families."""
from .uniform import SparseLinearModel
from .krylov import krylov
from .rational import matrix,rref,pivot_coordinates,mul,encoded,row_basis


def compile_sparse_family(modes,C,max_rank=128):
    if not isinstance(modes,dict) or not modes or any(not isinstance(name,str) or not name for name in modes):
        raise ValueError("Nonempty named mode dictionary required")
    models={name:SparseLinearModel.from_spec({**spec,"C":C}) for name,spec in modes.items()}
    first=next(iter(models.values()))
    n,m=first.operator.n,len(first.B[0])
    if any(model.operator.n!=n or len(model.B[0])!=m for model in models.values()) or type(max_rank) is not int or not 1<=max_rank<=n:
        raise ValueError("Matching mode/input dimensions and rank budget in [1,n] required")
    rows,labels=krylov([(i,row) for i,row in enumerate(first.C)],
                      {name:(lambda v,op=model.operator:op.pullback((v,))[0]) for name,model in models.items()},limit=max_rank)
    if not rows:
        raise ValueError("Nonzero target required")
    e,pivots=rref(rows)
    return {"schema":"dynacomp.sparse-family/1","modes":{name:model.spec() for name,model in models.items()},
            "C":encoded(first.C),"E":encoded(e),"D":encoded([pivot_coordinates(row,e,pivots) for row in first.C]),
            "G":{name:encoded([pivot_coordinates(row,e,pivots) for row in model.operator.pullback(e)]) for name,model in models.items()},
            "H":{name:encoded(mul(e,model.B)) for name,model in models.items()},
            "experiments":[{"output":i,"word":list(word)} for i,word in labels],
            "rank":len(e),"max_rank":max_rank,
            "coverage":"all initial states and input words under arbitrary time-varying linear combinations of the supplied mode/input pairs; output preservation does not establish stability"}


def replay_sparse_family(packet):
    if packet.get("schema")!="dynacomp.sparse-family/1":
        raise ValueError("Unknown sparse family schema")
    modes=packet["modes"]
    if not isinstance(modes,dict) or not modes or set(packet["G"])!=set(modes) or set(packet["H"])!=set(modes):
        raise ValueError("Mode counts disagree")
    c,e,d=map(matrix,(packet[k] for k in ("C","E","D")))
    rank=packet["rank"]
    n=len(e[0])
    if type(rank) is not int or type(packet["max_rank"]) is not int or not 1<=rank<=packet["max_rank"]<=n or len(e)!=rank or len(row_basis(e))!=rank or mul(d,e)!=c:
        raise ValueError("Invalid rank, encoder or target identity")
    channels=None
    for name,spec in modes.items():
        model=SparseLinearModel.from_spec(spec)
        if model.operator.n!=n or model.C!=c or (channels is not None and len(model.B[0])!=channels):
            raise ValueError("Mode dimensions or targets disagree")
        channels=len(model.B[0])
        if model.operator.pullback(e)!=mul(matrix(packet["G"][name]),e) or mul(e,model.B)!=matrix(packet["H"][name]):
            raise ValueError("Sparse family transition or input identity fails")
    return True
","dynacomp/spectral.py":""""Infinite spectral families -> rational finite dynamics with analytic tails.

Supported source semantics are explicit formulas, not arbitrary asserted tail
bounds. Ramanujan identities are mathematical inputs from the cited paper;
replay checks executable arithmetic and bounds, not a formal proof of that paper.
"""
from fractions import Fraction
from functools import lru_cache
from .rational import q, mv, matrix, addv
from .enclosures import sqrt_integer, log_rational, pi_interval, exp_negative, precision
from .uniform import SparseLinearModel
from .validated import validated_box, replay_validated

PAPER = "https://arxiv.org/html/2610.10578v1"


def _upper(value, bits):
    """Round a nonnegative budget upward to keep receipts bounded in size."""
    scale = 1 << bits
    return Fraction((q(value)*scale).__ceil__(), scale)


def _integer(value, name, low=1, high=4096):
    if type(value) is not int or not low <= value <= high:
        raise ValueError(f"{name} must be an integer in [{low},{high}]")
    return value


def _nonnegative(value):
    value = q(value)
    if value < 0:
        raise ValueError("Nonnegative amplitude/domain required")
    return value


def character5(n):
    return (0, 1, -1, -1, 1)[n % 5]


def ramanujan_coefficients(count):
    """Return exact (a,b) with c_N = a + b sqrt(5), N=1,...,count.

    Divisor sieves implement equation (41), independently of continued-fraction
    evaluation. Fractions retain all cancellations and coefficient signs.
    """
    _integer(count, "Coefficient count")
    harmonic = [Fraction(0) for _ in range(count+1)]
    direct = harmonic.copy()
    reverse = harmonic.copy()
    for divisor in range(1, count+1):
        inv = Fraction(1, divisor)
        for n in range(divisor, count+1, divisor):
            harmonic[n] += inv
            direct[n] += character5(divisor)*inv
            reverse[n] += character5(n//divisor)*inv
    return tuple((-harmonic[n]/2
                  - (reverse[n//5]/2 if n % 5 == 0 else 0)
                  + (harmonic[n//25]/2 if n % 25 == 0 else 0),
                  direct[n]/2) for n in range(1, count+1))


def _field_interval(a, b, root):
    values = (a+b*root[0], a+b*root[1])
    return min(values), max(values)


def _midpoint(interval):
    lo, hi = interval
    return (lo+hi)/2, (hi-lo)/2


@lru_cache(maxsize=32)
def _constants(bits):
    root = sqrt_integer(5, bits)
    pi = pi_interval(bits)
    return root, (8/pi[1]**2, 8/pi[0]**2)


def _source(family):
    """Canonicalize source formulas; reject unnoticed/unsupported parameters."""
    kind = family.get("kind")
    fields = {
        "ramanujan_log": {"kind", "start"},
        "power_moments": {"kind", "start", "power", "amplitude"},
        "heat_rod": {"kind", "dt", "initial_amplitude", "input_bound"},
    }
    if kind not in fields or set(family)-fields[kind]:
        raise ValueError("Unsupported spectral family or parameter")
    if kind == "heat_rod":
        dt = q(family.get("dt", "1/10"))
        if dt <= 0:
            raise ValueError("Positive sample interval required")
        return {"kind": kind, "dt": str(dt),
                "initial_amplitude": str(_nonnegative(family.get("initial_amplitude", 1))),
                "input_bound": str(_nonnegative(family.get("input_bound", 1)))}
    result = {"kind": kind, "start": _integer(family.get("start", 1), "Starting moment", high=128)}
    if kind == "power_moments":
        result.update(power=_integer(family.get("power", 0), "Coefficient power", low=0, high=128),
                      amplitude=str(q(family.get("amplitude", 1))))
    return result


def _build(family, modes, bits):
    """Build midpoint dynamics and independently accounted all-time budgets."""
    family = _source(family)
    _integer(modes, "Modes")
    precision(bits)
    kind = family["kind"]
    entries, b, c, center, radius, modal = [], [], [], [], [], []
    coefficient_error = Fraction(0)
    if kind in ("ramanujan_log", "power_moments"):
        start = family["start"]
        if kind == "ramanujan_log":
            root = sqrt_integer(5, bits)
            pairs = ramanujan_coefficients(modes)
            weights = [_field_interval(a, b, root) for a, b in pairs]
            exponent = 2*start
            # Integral comparison for a decreasing log-weighted p-series.
            log_hi = log_rational(modes, bits)[1]
            tail = (root[1]+3)/2*Fraction(1, modes**(exponent-1))*((1+log_hi)/(exponent-1)+Fraction(1, (exponent-1)**2))
            obstruction = "Assuming the cited Theorem 4: infinitely many nonzero poles; no exact fixed finite-dimensional time-invariant linear realization of the full moment sequence."
        else:
            amplitude, power = q(family["amplitude"]), family["power"]
            weights = [(amplitude/Fraction(k**power),)*2 for k in range(1, modes+1)]
            exponent = power+2*start
            tail = abs(amplitude)*Fraction(1, (exponent-1)*modes**(exponent-1))
            obstruction = "Nonzero amplitude gives infinitely many distinct poles; zero amplitude is identically zero."
        for i, weight in enumerate(weights):
            k = i+1
            pole = Fraction(1, k*k)
            mid, rad = _midpoint(weight)
            initial = pole**start
            entries.append([i, i, str(pole)])
            b.append(["0"])
            c.append(str(mid))
            center.append(str(initial))
            radius.append("0")
            coefficient_error = _upper(coefficient_error+rad*initial, bits)
            modal.append({"index": k, "pole_interval": [str(pole)]*2,
                          "weight_interval": [str(v) for v in weight]})
        domain = {"initial_center": center, "initial_radius": radius, "input_bound": "0"}
        budgets = {"omitted_initial": str(_upper(tail, bits)), "omitted_forcing": "0",
                   "retained_coefficient_and_sampling": str(coefficient_error)}
        semantics = "Unforced normalized moment at index start+t, every integer t>=0; input must be zero."
    else:
        dt = q(family["dt"])
        initial, forcing = q(family["initial_amplitude"]), q(family["input_bound"])
        scale_interval = _constants(bits)[1]
        scale, scale_radius = _midpoint(scale_interval)
        for i in range(modes):
            k = 2*i+1
            pole_interval = exp_negative(k*k*dt, bits)
            pole, pole_radius = _midpoint(pole_interval)
            rho = pole_interval[1]
            if rho >= 1:
                raise ValueError("Precision cannot separate the slowest heat pole from one; increase bits or dt")
            # The sampled source has exact DC gain 1/k^2 for each mode.
            gain = (1-pole)/(k*k)
            weight = scale/(k*k)
            weight_radius = scale_radius/(k*k)
            state_size = initial+forcing/Fraction(k*k)
            # All-time difference of two scalar filters with tied DC gains.
            state_error = (initial*pole_radius/(1-rho)
                           + forcing*pole_radius/Fraction(k*k)*
                           (1/(1-rho)+(1-pole)/(1-rho)**2))
            coefficient_error = _upper(coefficient_error+weight_radius*state_size+abs(weight)*state_error, bits)
            entries.append([i, i, str(pole)])
            b.append([str(gain)])
            c.append(str(weight))
            center.append("0")
            radius.append(str(initial))
            modal.append({"index": k, "pole_interval": [str(v) for v in pole_interval],
                          "weight_interval": [str(v/Fraction(k*k)) for v in scale_interval]})
        # Convexity over cells centered on the omitted odd integers gives
        # sum_{j>=m} (2j+1)^-p <= (2m)^(1-p)/(2(p-1)).
        tail_initial = scale_interval[1]*initial/Fraction(4*modes)
        tail_forcing = scale_interval[1]*forcing/Fraction(48*modes**3)
        budgets = {"omitted_initial": str(_upper(tail_initial, bits)), "omitted_forcing": str(_upper(tail_forcing, bits)),
                   "retained_coefficient_and_sampling": str(coefficient_error)}
        domain = {"initial_center": center, "initial_radius": radius, "input_bound": str(forcing)}
        semantics = ("Spatial mean of theta_t=theta_xx+u(t) on (0,pi), zero boundary temperatures; "
                     "constant initial field a with |a|<=initial_amplitude, |u(t)|<=input_bound. "
                     "Midpoint model assumes zero-order-held inputs of duration dt. Tail bound itself covers measurable bounded inputs continuously.")
        obstruction = "The unrestricted heat input/output map has infinitely many visible odd poles; restricted-domain truncation errors are recorded separately."
    total = sum(q(value) for value in budgets.values())
    model = {"n": modes, "entries": entries, "B": b, "C": [c]}
    return family, model, domain, modal, budgets, total, semantics, obstruction


def compile_spectral(family, modes, tolerance, bits=80):
    """Create a rational model whose source error is bounded for all future samples."""
    tolerance = _nonnegative(tolerance)
    family, model, domain, modal, budgets, total, semantics, obstruction = _build(family, modes, bits)
    return {"schema": "dynacomp.spectral/1", "family": family, "modes": modes, "bits": bits,
            "model": model, "domain": domain, "modal_enclosures": modal, "error_budget": budgets,
            "all_time_upper": str(total), "tolerance": str(tolerance),
            "status": "tolerance_met" if total <= tolerance else "not_certified",
            "source_semantics": semantics, "exact_realization_obstruction": obstruction,
            "source_reference": PAPER if family["kind"] == "ramanujan_log" else "Analytic spectral formula derived in docs/SPECTRAL.md",
            "claim": "Analytic infinite source -> exact rational midpoint model, all future samples; runtime floating roundoff and physical calibration excluded."}


def replay_spectral(packet):
    """Reconstruct every bound and retained coefficient from the source formula."""
    if packet.get("schema") != "dynacomp.spectral/1":
        raise ValueError("Unknown spectral schema")
    fresh = compile_spectral(packet["family"], packet["modes"], packet["tolerance"], packet["bits"])
    if fresh != packet:
        raise ValueError("Spectral source, enclosure, domain, budget or status differs")
    return True


def search_spectral(family, tolerance, max_modes=256, bits=80):
    """Geometric budgeted search. Success is certified; no rank optimality claim."""
    _integer(max_modes, "Maximum modes")
    modes, history = 1, []
    while True:
        packet = compile_spectral(family, modes, tolerance, bits)
        history.append({"modes": modes, "all_time_upper": packet["all_time_upper"], "status": packet["status"]})
        if packet["status"] == "tolerance_met" or modes == max_modes:
            return packet, history
        modes = min(max_modes, modes*2)


def spectral_error_at(packet, step):
    """A refined source-only upper bound at a specified sample/index."""
    replay_spectral(packet)
    _integer(step, "Step", low=0, high=1000000)
    budget = packet["error_budget"]
    family = packet["family"]
    if family["kind"] == "heat_rod":
        rho = exp_negative((2*packet["modes"]+1)**2*q(family["dt"]), packet["bits"])[1]
    else:
        rho = Fraction(1, (packet["modes"]+1)**2)
    return (q(budget["omitted_initial"])*rho**step+q(budget["omitted_forcing"])
            + q(budget["retained_coefficient_and_sampling"]))


def compress_spectral_modes(packet, keep, tolerance):
    """Keep selected zero-based modal coordinates with an all-time guarantee.

    This uses scalar DC gains, not an arbitrary projected-model stability
    inference. Distinct rational poles mean no exact generic closure is lost
    silently: every deleted contribution is charged to the output budget.
    """
    replay_spectral(packet)
    keep = list(keep)
    if not keep or any(type(i) is not int or not 0 <= i < packet["modes"] for i in keep) or len(set(keep)) != len(keep):
        raise ValueError("Distinct nonempty zero-based modal indices required")
    tolerance = _nonnegative(tolerance)
    model, domain = packet["model"], packet["domain"]
    poles = [q(entry[2]) for entry in model["entries"]]
    c = [q(v) for v in model["C"][0]]
    removed = Fraction(0)
    selected = set(keep)
    for i in range(packet["modes"]):
        if i in selected:
            continue
        size = abs(q(domain["initial_center"][i]))+q(domain["initial_radius"][i])
        if q(domain["input_bound"]):
            size += abs(q(model["B"][i][0]))*q(domain["input_bound"])/(1-poles[i])
        removed = _upper(removed+abs(c[i])*size, packet["bits"])
    e = [[str(int(i == j)) for j in range(packet["modes"])] for i in keep]
    g = [[str(poles[i] if i == j else 0) for j in keep] for i in keep]
    h = [model["B"][i] for i in keep]
    d = [[model["C"][0][i] for i in keep]]
    total = q(packet["all_time_upper"])+removed
    return {"schema": "dynacomp.spectral-subset/1", "source": packet, "keep": keep,
            "E": e, "G": g, "H": h, "D": d, "rank": len(keep),
            "removed_modes_upper": str(removed), "combined_all_time_upper": str(total),
            "tolerance": str(tolerance), "status": "tolerance_met" if total <= tolerance else "not_certified",
            "claim": "Infinite source -> selected rational modes at every future sample; analytic source and deleted-mode budgets added; no arbitrary-projection or rank-optimality claim."}


def replay_spectral_subset(packet):
    if packet.get("schema") != "dynacomp.spectral-subset/1":
        raise ValueError("Unknown spectral subset schema")
    if compress_spectral_modes(packet["source"], packet["keep"], packet["tolerance"]) != packet:
        raise ValueError("Modal selection, all-time budget or acceptance differs")
    return True


def compose_spectral(packet, E, G, H, D, horizon, tolerance, **options):
    """Combine the infinite-source budget with any finite reduced model.

    Finite acceptance uses an enclosing initial box (heat's correlated initial
    field is deliberately enlarged), independent bounded ZOH input samples.
    A failed finite lower witness does not by itself refute the infinite source.
    """
    replay_spectral(packet)
    _integer(horizon, "Horizon", low=0, high=10000)
    tolerance = _nonnegative(tolerance)
    source_error = q(packet["all_time_upper"])
    domain = packet["domain"]
    finite = validated_box(SparseLinearModel.from_spec(packet["model"]), E, G, H, D,
                           domain["initial_center"], domain["initial_radius"],
                           [[domain["input_bound"]]]*horizon,
                           max(Fraction(0), tolerance-source_error), **options)
    combined = source_error+q(finite["certificate"]["worst_upper"])
    return {"schema": "dynacomp.spectral-composition/1", "source": packet, "finite": finite,
            "tolerance": str(tolerance), "combined_upper": str(combined), "horizon": horizon,
            "status": "tolerance_met" if combined <= tolerance and finite["status"] == "tolerance_met" else "not_certified",
            "claim": "Infinite analytic source -> supplied reduction at samples 0..horizon; source-tail and finite-reduction errors added; no all-time claim for second-stage reduction."}


def replay_spectral_composition(packet):
    if packet.get("schema") != "dynacomp.spectral-composition/1":
        raise ValueError("Unknown spectral composition schema")
    replay_spectral(packet["source"])
    replay_validated(packet["finite"])
    finite = packet["finite"]
    fresh = compose_spectral(packet["source"], *(finite[k] for k in ("E", "G", "H", "D")),
                             packet["horizon"], packet["tolerance"],
                             precisions=(finite["certificate"]["bits"],),
                             require_contraction=finite["require_contraction"])
    expected = fresh["finite"]
    # Precision search history is diagnostic; arithmetic/status replayed above.
    fresh["finite"] = finite
    if fresh != packet:
        raise ValueError("Composed domain, source, bound or status differs")
    # Explicitly tie the independently checked finite packet to this source.
    for key in ("model", "initial_center", "initial_radius", "input_radii", "input_centers", "tolerance", "certificate", "status", "rank"):
        if expected[key] != finite[key]:
            raise ValueError("Finite certificate is not for the declared infinite-source domain")
    return True


def simulate_spectral(packet, inputs, initial_amplitude=0, allow_unaccepted=False):
    """Exact rational execution with source-domain and horizon guards.

    initial_amplitude selects the common initial rod field, not arbitrary
    independent modal values. Moment sources have their prescribed initial
    state and require initial_amplitude=0 and every supplied input zero.
    """
    if type(allow_unaccepted) is not bool:
        raise ValueError("Boolean acceptance override required")
    readers = {"dynacomp.spectral/1": replay_spectral,
               "dynacomp.spectral-subset/1": replay_spectral_subset,
               "dynacomp.spectral-composition/1": replay_spectral_composition}
    schema = packet.get("schema")
    if schema not in readers:
        raise ValueError("Unknown spectral execution schema")
    readers[schema](packet)
    if packet["status"] != "tolerance_met" and not allow_unaccepted:
        raise ValueError("Declared tolerance not certified")
    source = packet if schema == "dynacomp.spectral/1" else packet["source"]
    inputs = tuple(q(u) for u in inputs)
    if schema == "dynacomp.spectral-composition/1" and len(inputs) > packet["horizon"]:
        raise ValueError("Execution exceeds certified second-stage horizon")
    bound = q(source["domain"]["input_bound"])
    if any(abs(u) > bound for u in inputs):
        raise ValueError("Input outside infinite-source domain")
    initial = q(initial_amplitude)
    if source["family"]["kind"] == "heat_rod":
        if abs(initial) > q(source["family"]["initial_amplitude"]):
            raise ValueError("Initial field outside infinite-source domain")
        state = (initial,)*source["modes"]
    else:
        if initial:
            raise ValueError("Moment source has a fixed prescribed initial state")
        state = tuple(q(v) for v in source["domain"]["initial_center"])
    if schema == "dynacomp.spectral/1":
        poles = tuple(q(row[2]) for row in source["model"]["entries"])
        b, c = matrix(source["model"]["B"]), matrix(source["model"]["C"])
        def advance(x, u):
            return tuple(a*v+row[0]*u for a, v, row in zip(poles, x, b))
    else:
        reduced = packet["finite"] if schema == "dynacomp.spectral-composition/1" else packet
        state = mv(matrix(reduced["E"]), state)
        g, h, c = (matrix(reduced[key]) for key in ("G", "H", "D"))
        def advance(x, u):
            return addv(mv(g, x), mv(h, (u,)))
    outputs = [mv(c, state)]
    for u in inputs:
        state = advance(state, u)
        outputs.append(mv(c, state))
    return tuple(outputs)
","dynacomp/stability.py":""""Exact stability decisions and rationally certified quadratic metrics.

Decision: the characteristic polynomial is computed over Q (Faddeev-LeVerrier)
and tested by the Schur-Cohn recursion (discrete time, all eigenvalues in the
open unit disk) or by Schur-Cohn after a Cayley transform (continuous time,
all eigenvalues in the open left half-plane). No eigenvalue is approximated.

Certificate: a rational symmetric P with P > 0 and gamma P - A^T P A > 0 for a
rational gamma < 1 (discrete), or A^T P + P A + 2 sigma P < 0 (continuous).
Floating-point Smith iteration only proposes P; acceptance is an exact
Sylvester (LDL^T pivot) test. A stable matrix always has such a P, but a
proposal can fail at finite precision; failure is reported, never hidden.
"""
from fractions import Fraction
from math import isqrt
from .upoly import primitive
from .rational import matrix, mul, transpose, identity, sub, q, encoded, inverse


def charpoly(A):
    """Coefficients of det(zI - A), lowest degree first, by Faddeev-LeVerrier."""
    a = matrix(A)
    n = len(a)
    if len(a[0]) != n:
        raise ValueError("Expected a square matrix")
    coefficients = [Fraction(1)]
    m = tuple(tuple(Fraction(0) for _ in range(n)) for _ in range(n))
    for k in range(1, n+1):
        shifted = tuple(tuple(m[i][j] + (coefficients[-1] if i == j else 0) for j in range(n)) for i in range(n))
        m = mul(a, shifted)
        coefficients.append(-sum(m[i][i] for i in range(n))/k)
    # coefficients[k] multiplies z^(n-k).
    return tuple(reversed(coefficients))


def schur_cohn(p):
    """Decide whether every root of real p lies in the open unit disk.

    Schur-Cohn: p is Schur stable iff |p_0| < |p_n| and
    (p_n p(z) - p_0 p*(z)) / z is Schur stable, where p* reverses p.
    Returns (stable, steps), with the failing step if unstable.
    """
    p = [q(c) for c in p]
    while p and not p[-1]:
        p.pop()
    if not p:
        raise ValueError("Zero polynomial")
    steps = []
    while len(p) > 1:
        p = list(primitive(p))  # scaling preserves roots and keeps integers small
        a0, an = p[0], p[-1]
        ok = abs(a0) < abs(an)
        steps.append({"degree": len(p)-1, "abs_constant_below_abs_leading": ok})
        if not ok:
            return False, steps
        reduced = [an*x - a0*y for x, y in zip(p, reversed(p))]
        p = reduced[1:]
    return True, steps


def schur_stable(A):
    stable, steps = schur_cohn(charpoly(A))
    return {"stable": stable, "criterion": "Schur-Cohn on the exact characteristic polynomial",
            "charpoly": [str(c) for c in charpoly(A)], "steps": steps}


def cayley(A):
    """(I - A)^(-1) (I + A); None when 1 is an eigenvalue (then A is not Hurwitz)."""
    a = matrix(A)
    n = len(a)
    try:
        return mul(inverse(sub(identity(n), a)), tuple(tuple(x + (i == j) for j, x in enumerate(row)) for i, row in enumerate(a)))
    except ValueError:
        return None


def hurwitz_stable(A):
    """Continuous time: Re(lambda) < 0 iff |(1+lambda)/(1-lambda)| < 1."""
    c = cayley(A)
    if c is None:
        return {"stable": False, "criterion": "eigenvalue 1 makes I - A singular", "steps": []}
    stable, steps = schur_cohn(charpoly(c))
    return {"stable": stable, "criterion": "Schur-Cohn after the Cayley transform", "steps": steps}


def positive_definite(M):
    """Exact Sylvester test by symmetric elimination: every pivot must be positive."""
    a = [list(row) for row in matrix(M)]
    n = len(a)
    if len(a[0]) != n or any(a[i][j] != a[j][i] for i in range(n) for j in range(i)):
        raise ValueError("Expected a symmetric matrix")
    for k in range(n):
        pivot = a[k][k]
        if pivot <= 0:
            return False
        for i in range(k+1, n):
            if a[i][k]:
                f = a[i][k]/pivot
                for j in range(k+1, n):
                    a[i][j] -= f*a[k][j]
    return True


def _float(a):
    return [[float(x) for x in row] for row in a]


def _fmul(a, b):
    bt = list(zip(*b))
    return [[sum(x*y for x, y in zip(row, col)) for col in bt] for row in a]


def spectral_radius_estimate(a, doublings=40):
    """Float estimate from ||A^(2^j)||^(2^-j); a proposal aid only."""
    f = _float(a)
    estimate = None
    for j in range(doublings):
        norm = max(sum(abs(x) for x in row) for row in f)
        if norm == 0:
            return 0.0
        estimate = norm**(1/2**j)
        if norm > 1e150 or norm < 1e-150:
            break
        f = _fmul(f, f)
    return estimate


def _smith(a, continuous=False, doublings=48, scale=1.0):
    """Float proposal for sum_k (A^T/s)^k (A/s)^k; a scale s just above the
    spectral radius yields A^T P A <= s^2 (P - I), so gamma near s^2."""
    n = len(a)
    f = [[x/scale for x in row] for row in _float(a)]
    p = [[float(i == j) for j in range(n)] for i in range(n)]
    power = f
    for _ in range(doublings):
        pt = [list(r) for r in zip(*power)]
        p = [[x+y for x, y in zip(r, s)] for r, s in zip(p, _fmul(_fmul(pt, p), power))]
        power = _fmul(power, power)
        if max(abs(x) for row in power for x in row) < 1e-30:
            break
        if max(abs(x) for row in p for x in row) > 1e200:
            return None
    return p


def _rationalize(p, denominator):
    n = len(p)
    r = [[Fraction((p[i][j]+p[j][i])/2).limit_denominator(denominator) for j in range(n)] for i in range(n)]
    for i in range(n):
        for j in range(i):
            r[i][j] = r[j][i]
    return tuple(tuple(row) for row in r)


def _sym(m):
    return tuple(tuple((m[i][j]+m[j][i])/2 for j in range(len(m))) for i in range(len(m)))


def contraction_holds(A, P, gamma):
    """gamma P - A^T P A > 0 exactly."""
    a, p = matrix(A), matrix(P)
    apa = mul(mul(transpose(a), p), a)
    return positive_definite(tuple(tuple(gamma*x - y for x, y in zip(r, s)) for r, s in zip(p, apa)))


def _best_gamma(a, p, bits=24):
    """Smallest dyadic gamma in (0, 1] found by bisection with an exact acceptance test."""
    if not contraction_holds(a, p, Fraction(1)):
        return None
    lo, hi = Fraction(0), Fraction(1)
    for _ in range(bits):
        mid = (lo+hi)/2
        if contraction_holds(a, p, mid):
            hi = mid
        else:
            lo = mid
    return hi


def quadratic_certificate(A, denominators=(2**12, 2**20, 2**32, 2**48), bits=24):
    """Discover and exactly accept P > 0, A^T P A < gamma P with gamma < 1."""
    a = matrix(A)
    decision = schur_stable(a)
    if not decision["stable"]:
        return {"schema": "dynacomp.quadratic-metric/1", "status": "not_schur_stable", "decision": decision}
    rho = spectral_radius_estimate(a) or 0.0
    best = None
    for scale in sorted({1.0, min(1.0, rho + (1-rho)/2), min(1.0, rho + (1-rho)/8), min(1.0, rho + (1-rho)/32)}):
        if scale <= 0:
            continue
        proposal = _smith(a, scale=scale)
        for d in denominators if proposal is not None else ():
            p = _rationalize(proposal, d)
            if not positive_definite(p):
                continue
            gamma = _best_gamma(a, p, bits)
            if gamma is not None and gamma < 1:
                if best is None or gamma < best[1]:
                    best = (p, gamma)
                break
    if best is not None:
        p, gamma = best
        return {"schema": "dynacomp.quadratic-metric/1", "status": "certified", "A": encoded(a),
                "P": encoded(p), "gamma": str(gamma), "decision": decision,
                "claim": "x^T P x decreases by at least the factor gamma per step"}
    return {"schema": "dynacomp.quadratic-metric/1", "status": "proposal_failed", "decision": decision,
            "claim": "A is Schur stable, but no rational proposal was accepted at the tried precisions"}


def replay_quadratic(packet):
    if packet.get("schema") != "dynacomp.quadratic-metric/1" or packet.get("status") != "certified":
        raise ValueError("Need a certified quadratic metric packet")
    a, p, gamma = matrix(packet["A"]), matrix(packet["P"]), q(packet["gamma"])
    if not 0 <= gamma < 1:
        raise ValueError("Contraction factor must lie in [0, 1)")
    if not positive_definite(p):
        raise ValueError("P is not positive definite")
    if not contraction_holds(a, p, gamma):
        raise ValueError("gamma P - A^T P A is not positive definite")
    return True


def common_quadratic_certificate(modes, denominators=(2**12, 2**20, 2**32), bits=20):
    """One P contracting every mode: stability under arbitrary switching.

    The proposal sums the per-mode Smith matrices; a common P need not exist
    even when every mode is stable, so failure is not proof of instability.
    """
    mats = {str(k): matrix(v) for k, v in modes.items()}
    total = None
    for name, a in mats.items():
        if not schur_stable(a)["stable"]:
            return {"schema": "dynacomp.common-quadratic/1", "status": "mode_unstable", "mode": name}
        s = _smith(a)
        if s is None:
            return {"schema": "dynacomp.common-quadratic/1", "status": "proposal_failed"}
        total = s if total is None else [[x+y for x, y in zip(r, t)] for r, t in zip(total, s)]
    for d in denominators:
        p = _rationalize(total, d)
        if not positive_definite(p):
            continue
        gammas = [_best_gamma(a, p, bits) for a in mats.values()]
        if all(g is not None and g < 1 for g in gammas):
            return {"schema": "dynacomp.common-quadratic/1", "status": "certified",
                    "modes": {k: encoded(a) for k, a in mats.items()}, "P": encoded(p),
                    "gamma": str(max(gammas)),
                    "claim": "x^T P x contracts by gamma under every mode, hence under every switching sequence"}
    return {"schema": "dynacomp.common-quadratic/1", "status": "proposal_failed",
            "claim": "no common quadratic function accepted; switching stability is undecided"}


def replay_common_quadratic(packet):
    if packet.get("schema") != "dynacomp.common-quadratic/1" or packet.get("status") != "certified":
        raise ValueError("Need a certified common quadratic packet")
    p, gamma = matrix(packet["P"]), q(packet["gamma"])
    if not 0 <= gamma < 1 or not positive_definite(p):
        raise ValueError("Invalid metric or factor")
    for name, a in packet["modes"].items():
        if not contraction_holds(matrix(a), p, gamma):
            raise ValueError(f"Mode {name} does not contract")
    return True


def sqrt_up(x, bits=48):
    """Rational upper bound of sqrt(x) for rational x >= 0, within about 2^-bits relative."""
    x = q(x)
    if x < 0:
        raise ValueError("Negative argument")
    if not x:
        return Fraction(0)
    scale = 4**bits
    n = x.numerator*x.denominator*scale
    r = isqrt(n)
    if r*r < n:
        r += 1
    return Fraction(r, x.denominator*2**bits)


def continuous_certificate(A, **options):
    """P > 0 with A^T P + P A < 0, proposed through the Cayley transform.

    If C = (I - A)^(-1) (I + A) satisfies C^T P C < P then A^T P + P A < 0;
    acceptance nevertheless checks the continuous inequality directly.
    """
    a = matrix(A)
    decision = hurwitz_stable(a)
    if not decision["stable"]:
        return {"schema": "dynacomp.continuous-metric/1", "status": "not_hurwitz_stable", "decision": decision}
    discrete = quadratic_certificate(cayley(a), **options)
    if discrete["status"] == "certified":
        p = matrix(discrete["P"])
        if _negative_lyapunov(a, p):
            return {"schema": "dynacomp.continuous-metric/1", "status": "certified", "A": encoded(a),
                    "P": encoded(p), "decision": decision,
                    "claim": "d/dt x^T P x < 0 for every nonzero x, so x' = A x is exponentially stable"}
    return {"schema": "dynacomp.continuous-metric/1", "status": "proposal_failed", "decision": decision}


def _negative_lyapunov(a, p):
    m = mul(transpose(a), p)
    s = tuple(tuple(-(m[i][j] + m[j][i]) for j in range(len(a))) for i in range(len(a)))
    return positive_definite(p) and positive_definite(s)


def replay_continuous(packet):
    if packet.get("schema") != "dynacomp.continuous-metric/1" or packet.get("status") != "certified":
        raise ValueError("Need a certified continuous metric packet")
    if not _negative_lyapunov(matrix(packet["A"]), matrix(packet["P"])):
        raise ValueError("P > 0 and A^T P + P A < 0 do not both hold")
    return True
","dynacomp/stable_proposals.py":""""Optional Lyapunov-coordinate discovery with exact reduced contraction.

The full metric and basis are floating proposals. Only supplied reduced
matrices passing I-G^T G > 0 exactly claim reduced stability. Output accuracy
needs separate validated_box acceptance. No full-system stability proof here.
"""
from fractions import Fraction
from .uniform import as_sparse
from .rational import encoded
from .validated import euclidean_contraction


class StableProposalContext:
    """Prepare one numerical metric and extend a nested proposal basis."""
    def __init__(self,model,horizon):
        import numpy as np
        from scipy.linalg import solve_discrete_lyapunov,cholesky,solve_triangular
        self.model=as_sparse(model);self.horizon=horizon;n=self.model.operator.n
        if type(horizon) is not int or horizon<0:raise ValueError('Nonnegative integer horizon required')
        a=np.zeros((n,n))
        for i,j,v in self.model.operator.entries:a[i,j]=float(v)
        b=np.asarray(self.model.B,dtype=float);c=np.asarray(self.model.C,dtype=float)
        if not np.isfinite(a).all() or not np.isfinite(b).all() or not np.isfinite(c).all():raise ValueError('Source not representable in finite binary64')
        p=solve_discrete_lyapunov(a.T,np.eye(n));l=cholesky((p+p.T)/2,lower=False)
        li=solve_triangular(l,np.eye(n));self.at=l@a@li;self.bt=l@b;self.ct=c@li
        _,singular,vh=np.linalg.svd(self.ct,full_matrices=False)
        count=int(np.sum(singular>max(self.ct.shape)*np.finfo(float).eps*(singular[0] if len(singular) else 0)))
        if not count:raise ValueError('Nonzero numerical target required')
        self.basis=vh[:count].T;self.target_rank=count;self.pulls=[c]
        for _ in range(horizon):self.pulls.append(self.pulls[-1]@a)
        self.a,self.b,self.c,self.l,self.li=a,b,c,l,li
        self.condition=float(np.linalg.cond(p));self.metric_preparations=1

    def propose(self,rank):
        import numpy as np
        if type(rank) is not int or not self.target_rank<=rank<=self.model.operator.n:raise ValueError('Adequate rank budget in [1,n] required')
        a,b,c,l,li=self.a,self.b,self.c,self.l,self.li
        basis=self.basis
        while basis.shape[1]<rank:
            g=basis.T@self.at@basis;h=basis.T@self.bt;d=self.ct@basis;e=basis.T@l;dg=d
            residuals=[];forcing=[]
            for ca in self.pulls:
                residuals.append(ca-dg@e);forcing.append(ca@b-dg@h);dg=dg@g
            scores=[np.sum(abs(v),axis=1)+sum((np.sum(abs(f),axis=1) for f in forcing[:t]),start=np.zeros(len(c))) for t,v in enumerate(residuals)]
            t,k=max(((t,k) for t in range(len(scores)) for k in range(len(c))),key=lambda pair:scores[pair[0]][pair[1]])
            row=residuals[t][k]@li
            v=row-basis@(basis.T@row);v-=basis@(basis.T@v)
            threshold=1e-12*max(1,float(np.linalg.norm(row)))
            if np.linalg.norm(v)<=threshold:
                found=False
                for ca in self.pulls:
                    for row in ca@li:
                        v=row-basis@(basis.T@row);v-=basis@(basis.T@v)
                        if np.linalg.norm(v)>1e-12*max(1,float(np.linalg.norm(row))):found=True;break
                    if found:break
                if not found:break
            basis=np.column_stack([basis,v/np.linalg.norm(v)])
        self.basis=basis;basis=basis[:,:rank]
        g=basis.T@self.at@basis;h=basis.T@self.bt;d=self.ct@basis;e=basis.T@l
        if not all(np.isfinite(x).all() for x in (e,g,h,d)):raise OverflowError('Nonfinite proposal')
        def bind(x):return tuple(tuple(Fraction(float(v)) for v in row) for row in x)
        e,g,h,d=map(bind,(e,g,h,d));stable=euclidean_contraction(g)
        return {'E':encoded(e),'G':encoded(g),'H':encoded(h),'D':encoded(d),'rank':len(g),
                'reduced_contraction_certified':stable,'proposal':'Lyapunov-coordinate output-visible enrichment; binary64 matrices bound as exact dyadics',
                'full_metric_condition_estimate':self.condition,
                'claim':'reduced stability only if exact contraction accepted; accuracy requires independent box certificate'}


def stable_observable_proposal(model,horizon,rank,context=None):
    model=as_sparse(model)
    if type(rank) is not int or not 1<=rank<=model.operator.n:raise ValueError('Rank in [1,n] required')
    if context is None:context=StableProposalContext(model,horizon)
    if context.model!=model or context.horizon!=horizon:raise ValueError('Proposal context source or horizon differs')
    return context.propose(rank)
","dynacomp/structure.py":""""Discover target-preserving aggregate partitions from sparse interactions."""
from .rational import q
from .finite import partition


def aggregate_partition(operator, initial_labels, max_groups=None):
    """Coarsest refinement with exact closed group sums.

    Columns with equal aggregate contributions to every current group stay
    together. This is aggregate closure, not a claim of graph isomorphism.
    """
    if len(initial_labels) != operator.n:
        raise ValueError("One initial label per coordinate required")
    classes = partition(initial_labels)
    if max_groups is not None and (type(max_groups) is not int or max_groups < 1):
        raise ValueError("Positive group budget required")
    rounds = []
    while True:
        groups = max(classes)+1
        if max_groups is not None and groups > max_groups:
            raise OverflowError("Aggregate group budget exceeded; no exact compression accepted")
        contributions = [[q(0)]*groups for _ in range(operator.n)]
        for i, j, value in operator.entries:
            contributions[j][classes[i]] += value
        signatures = [(classes[j], tuple(contributions[j])) for j in range(operator.n)]
        refined = partition(signatures)
        if max_groups is not None and max(refined)+1 > max_groups:
            raise OverflowError("Aggregate group budget exceeded; no exact compression accepted")
        if refined == classes:
            break
        rounds.append({"before": groups, "after": max(refined)+1})
        classes = refined
    E = [[int(classes[j] == c) for j in range(operator.n)] for c in range(max(classes)+1)]
    return {"classes": list(classes), "E": E, "rounds": rounds,
            "claim": "closed aggregate partition; minimal among refinements of initial labels"}
","dynacomp/switched.py":""""Multi-mode exact closure: switched linear systems and weighted automata over Q.

A switched system applies one of several updates A_s at each step. A reduction
must survive every mode sequence, so its row space must be invariant under all
A_s simultaneously. A weighted automaton (alpha, {A_s}, eta) assigns the word
w = s1...sk the weight alpha A_s1 ... A_sk eta; probabilistic automata, hidden
Markov models and rational series are special cases. The same span closure
yields Schutzenberger minimization and Tzeng-style equivalence checking with
a shortest counterexample word.
"""
from .krylov import krylov, vecmat, matvec
from .rational import matrix, mul, coordinates, encoded, rref, q


def _modes(modes, n=None):
    if not modes:
        raise ValueError("Need at least one mode")
    out = {}
    for name, a in modes.items():
        a = matrix(a)
        if len(a) != len(a[0]) or (n is not None and len(a) != n):
            raise ValueError("Mode matrices must be square and share a dimension")
        n = len(a)
        out[str(name)] = a
    return out, n


def compile_switched(modes, C, inputs=None):
    """Smallest row space containing C and invariant under every mode.

    Each encoder row is c_i A_w for a recorded word w: the experiment it
    represents. Identities: E A_s = G_s E, E B_s = H_s, D E = C.
    """
    a, n = _modes(modes)
    c = matrix(C)
    if len(c[0]) != n:
        raise ValueError("Target width must match state dimension")
    b = {}
    if inputs is not None:
        for name in a:
            b[name] = matrix(inputs[name])
            if len(b[name]) != n:
                raise ValueError("Input matrix height must match state dimension")
    rows, labels = krylov([(i, row) for i, row in enumerate(c)],
                          {s: (lambda v, m=m: vecmat(v, m)) for s, m in a.items()})
    if not rows:
        raise ValueError("Zero-only targets need no state; request a nonzero target")
    G = {s: [list(coordinates(vecmat(r, m), rows)) for r in rows] for s, m in a.items()}
    packet = {"schema": "dynacomp.switched/1", "arithmetic": "rational",
              "modes": {s: encoded(m) for s, m in a.items()}, "C": encoded(c),
              "E": encoded(rows), "G": {s: encoded(g) for s, g in G.items()},
              "D": encoded([coordinates(r, rows) for r in c]),
              "experiments": [{"output": i, "word": list(w)} for i, w in labels]}
    if b:
        packet["inputs"] = {s: encoded(m) for s, m in b.items()}
        packet["H"] = {s: encoded(mul(rows, m)) for s, m in b.items()}
    return packet


def replay_switched(packet):
    if packet.get("schema") != "dynacomp.switched/1":
        raise ValueError("Unknown schema")
    a, n = _modes(packet["modes"])
    c, e, d = matrix(packet["C"]), matrix(packet["E"]), matrix(packet["D"])
    if len(e[0]) != n or len(rref(e)[1]) != len(e):
        raise ValueError("E must have full row rank and correct width")
    if set(packet["G"]) != set(a):
        raise ValueError("Need one reduced update per mode")
    for s, m in a.items():
        if mul(e, m) != mul(matrix(packet["G"][s]), e):
            raise ValueError(f"Transition identity fails for mode {s}")
    if "inputs" in packet:
        if set(packet["inputs"]) != set(a) or set(packet["H"]) != set(a):
            raise ValueError("Need one input matrix per mode")
        for s in a:
            if mul(e, matrix(packet["inputs"][s])) != matrix(packet["H"][s]):
                raise ValueError(f"Input identity fails for mode {s}")
    if mul(d, e) != c:
        raise ValueError("Target identity DE=C fails")
    return True


class WeightedAutomaton:
    def __init__(self, alpha, modes, eta):
        self.modes, n = _modes(modes)
        self.alpha = tuple(q(x) for x in alpha)
        self.eta = tuple(q(x) for x in eta)
        if len(self.alpha) != n or len(self.eta) != n:
            raise ValueError("Initial and final vectors must match dimension")
        self.n = n

    @classmethod
    def from_spec(cls, spec):
        return cls(spec["alpha"], spec["modes"], spec["eta"])

    def weight(self, word):
        v = self.alpha
        for s in word:
            v = vecmat(v, self.modes[s])
        return sum(x*y for x, y in zip(v, self.eta))

    def spec(self):
        return {"alpha": [str(x) for x in self.alpha], "eta": [str(x) for x in self.eta],
                "modes": {s: encoded(m) for s, m in self.modes.items()}}


def minimize_automaton(aut):
    """Forward (reachable) then backward (observable) quotient.

    Result order equals the Hankel rank of the series, so it is minimal among
    all weighted automata over Q with the same word weights. The packet carries
    prefix and suffix words whose Hankel block is nonsingular.
    """
    fwd, _ = krylov([(0, aut.alpha)], {s: (lambda v, m=m: vecmat(v, m)) for s, m in aut.modes.items()})
    if not fwd:
        return {"schema": "dynacomp.automaton/1", "status": "zero_series", "automaton": aut.spec()}
    M = {s: tuple(coordinates(vecmat(v, m), fwd) for v in fwd) for s, m in aut.modes.items()}
    a1 = coordinates(aut.alpha, fwd)
    eta1 = matvec(fwd, aut.eta)
    bwd, _ = krylov([(0, eta1)], {s: (lambda v, m=m: matvec(m, v)) for s, m in M.items()})
    if not bwd:
        return {"schema": "dynacomp.automaton/1", "status": "zero_series", "automaton": aut.spec()}
    # Columns P = bwd^T: M_s P = P N_s, eta1 = P e.
    N = {s: tuple(zip(*(coordinates(matvec(m, v), bwd) for v in bwd))) for s, m in M.items()}
    e = coordinates(eta1, bwd)
    alpha_min = tuple(sum(a1[i]*bwd[k][i] for i in range(len(a1))) for k in range(len(bwd)))
    minimal = WeightedAutomaton(alpha_min, N, e)
    prefixes = krylov([(0, minimal.alpha)], {s: (lambda v, m=m: vecmat(v, m)) for s, m in N.items()})[1]
    suffixes = krylov([(0, minimal.eta)], {s: (lambda v, m=m: matvec(m, v)) for s, m in N.items()})[1]
    return {"schema": "dynacomp.automaton/1", "status": "minimized", "arithmetic": "rational",
            "automaton": aut.spec(), "forward_basis": encoded(fwd),
            "forward_modes": {s: encoded(m) for s, m in M.items()},
            "forward_alpha": [str(x) for x in a1], "forward_eta": [str(x) for x in eta1],
            "backward_basis": encoded(bwd), "minimal": minimal.spec(),
            "order": len(bwd), "original_order": aut.n,
            "hankel_prefixes": [list(w) for _, w in prefixes],
            "hankel_suffixes": [list(reversed(w)) for _, w in suffixes]}


def replay_automaton(packet):
    """Check both quotient identities and the Hankel lower bound on the original."""
    if packet.get("schema") != "dynacomp.automaton/1" or packet.get("status") != "minimized":
        raise ValueError("Need a minimized automaton packet")
    aut = WeightedAutomaton.from_spec(packet["automaton"])
    small = WeightedAutomaton.from_spec(packet["minimal"])
    fwd, bwd = matrix(packet["forward_basis"]), matrix(packet["backward_basis"])
    M, _ = _modes(packet["forward_modes"])
    a1 = tuple(q(x) for x in packet["forward_alpha"])
    eta1 = tuple(q(x) for x in packet["forward_eta"])
    r, s = len(fwd), len(bwd)
    if set(M) != set(aut.modes) or set(small.modes) != set(aut.modes):
        raise ValueError("Alphabets differ")
    if len(fwd[0]) != aut.n or len(bwd[0]) != r or len(a1) != r or len(eta1) != r or small.n != s:
        raise ValueError("Certificate dimensions do not match")
    if vecmat(a1, fwd) != aut.alpha or matvec(fwd, aut.eta) != eta1:
        raise ValueError("Forward boundary identities fail")
    for x, m in aut.modes.items():
        if mul(fwd, m) != mul(M[x], fwd):
            raise ValueError("Forward identity fails")
    P = tuple(zip(*bwd))
    for x, m in M.items():
        if mul(m, P) != mul(P, small.modes[x]):
            raise ValueError("Backward identity fails")
    if matvec(P, small.eta) != eta1 or vecmat(a1, P) != small.alpha:
        raise ValueError("Backward boundary identities fail")
    pre = [tuple(w) for w in packet["hankel_prefixes"]]
    suf = [tuple(w) for w in packet["hankel_suffixes"]]
    if len(pre) != s or len(suf) != s or any(x not in aut.modes for w in pre+suf for x in w):
        raise ValueError("Hankel words must be square of minimal order over the alphabet")
    hankel = tuple(tuple(aut.weight(u+v) for v in suf) for u in pre)
    if len(rref(hankel)[1]) != s:
        raise ValueError("Hankel block is singular: minimality not established")
    return True


def check_equivalence(first, second):
    """Decide whether two weighted automata assign every word the same weight.

    Explores the joint row span of (alpha1 A1_w, alpha2 A2_w) in shortlex order,
    testing every visited word. The first difference found is a shortest
    distinguishing word. Otherwise the span itself is an equivalence certificate.
    """
    if set(first.modes) != set(second.modes):
        raise ValueError("Automata must share an alphabet")
    letters = list(first.modes)
    n1 = first.n
    final = first.eta + tuple(-x for x in second.eta)

    def step(v, s):
        return vecmat(v[:n1], first.modes[s]) + vecmat(v[n1:], second.modes[s])

    def visit(label, v):
        if sum(x*y for x, y in zip(v, final)):
            return label
        return None

    result = krylov([(0, first.alpha + second.alpha)],
                    {s: (lambda v, s=s: step(v, s)) for s in letters}, visit=visit)
    pair = {"first": first.spec(), "second": second.spec()}
    if isinstance(result[0], int):
        word = list(result[1])
        return {"schema": "dynacomp.equivalence/1", "equivalent": False, **pair, "word": word,
                "weights": [str(first.weight(word)), str(second.weight(word))]}
    basis = result[0]
    if not basis:
        return {"schema": "dynacomp.equivalence/1", "equivalent": True, **pair,
                "basis": [], "G": {s: [] for s in letters}, "start": []}
    G = {s: encoded([coordinates(step(v, s), basis) for v in basis]) for s in letters}
    return {"schema": "dynacomp.equivalence/1", "equivalent": True, **pair,
            "basis": encoded(basis), "G": G,
            "start": [str(x) for x in coordinates(first.alpha + second.alpha, basis)]}


def replay_equivalence(packet):
    if packet.get("schema") != "dynacomp.equivalence/1":
        raise ValueError("Unknown schema")
    first = WeightedAutomaton.from_spec(packet["first"])
    second = WeightedAutomaton.from_spec(packet["second"])
    if set(first.modes) != set(second.modes):
        raise ValueError("Automata must share an alphabet")
    if not packet["equivalent"]:
        word = packet["word"]
        if any(s not in first.modes for s in word) or first.weight(word) == second.weight(word):
            raise ValueError("Counterexample word does not distinguish")
        return True
    if not packet["basis"]:
        if any(first.alpha) or any(second.alpha):
            raise ValueError("Empty span certifies only two zero initial vectors")
        return True
    basis = matrix(packet["basis"])
    n1, n = first.n, first.n + second.n
    if len(basis[0]) != n:
        raise ValueError("Basis width must be the joint dimension")
    start = tuple(q(x) for x in packet["start"])
    if vecmat(start, basis) != first.alpha + second.alpha:
        raise ValueError("Start vector is not in the certified span")
    final = first.eta + tuple(-x for x in second.eta)
    if any(matvec(basis, final)):
        raise ValueError("Certified span does not annihilate the weight difference")
    for s in first.modes:
        g = matrix(packet["G"][s])
        for row, coefficients in zip(basis, g):
            image = vecmat(row[:n1], first.modes[s]) + vecmat(row[n1:], second.modes[s])
            if vecmat(coefficients, basis) != image:
                raise ValueError(f"Span is not invariant under letter {s}")
    return True
","dynacomp/thermal.py":""""Discrete heated-plate scenario workbench built on sparse uniform compilation.

Temperatures are excess above a fixed ambient; units are model-defined. Heat
stencil coefficients are per step. No continuum discretization error or real
installation validation is claimed by the algebraic output certificates.
"""
import argparse
import json
from pathlib import Path
from .rational import q,matrix,mv,addv,encoded
from .sparse import SparseOperator
from .uniform import SparseLinearModel,uniform_enrichment,replay_uniform,output_box_range
from .sparse_family import compile_sparse_family,replay_sparse_family


def plate_model(grid=12,conductance="1/8",loss="1/100"):
    if type(grid) is not int or grid<2 or grid%2:
        raise ValueError("Positive even grid size at least two required")
    k,l=q(conductance),q(loss)
    if k<0 or l<0 or 4*k+l>1:
        raise ValueError("Nonnegative conductance/loss with 4*k+loss <= 1 required")
    n=grid*grid;entries=[]
    for r in range(grid):
        for c in range(grid):
            near=[(r+dr,c+dc) for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<grid and 0<=c+dc<grid]
            i=r*grid+c
            entries.append((i,i,1-k*len(near)-l))
            entries.extend((i,rr*grid+cc,k) for rr,cc in near)
    middle={grid//2-1,grid//2};corners={0,grid-1}
    b=matrix([[q(int(i//grid in middle and i%grid in middle))/4] for i in range(n)])
    c=matrix([[q(int(i//grid in corners and i%grid in corners))/4 for i in range(n)]])
    return SparseLinearModel(SparseOperator.from_entries(n,entries),b,c)


def _simulate(model,packet,x0,inputs):
    e,g,h,d=map(matrix,(packet[k] for k in ('E','G','H','D')))
    x=tuple(q(v) for v in x0);z=mv(e,x)
    full,reduced=[mv(model.C,x)],[mv(d,z)]
    for u in inputs:
        x=addv(model.operator.step(x),mv(model.B,u))
        z=addv(mv(g,z),mv(h,u))
        full.append(mv(model.C,x));reduced.append(mv(d,z))
    return full,reduced


def workbench(grid=12,steps=20,tolerance="1/10",max_rank=None,threshold=21):
    if type(steps) is not int or steps<0:
        raise ValueError("Nonnegative integer horizon required")
    model=plate_model(grid)
    n=model.operator.n
    center,radius=[20]*n,[2]*n
    inputs,means=[[1]]*steps,[[1]]*steps
    approximate=uniform_enrichment(model,center,radius,inputs,tolerance,input_centers=means,max_rank=max_rank,strategy='prefix')
    assert replay_uniform(approximate)
    ranges=output_box_range(model,center,radius,inputs,means)
    classifications=[]
    for lo,hi in zip(ranges['lower'],ranges['upper']):
        classifications.append('all_below_threshold' if q(hi[0])<q(threshold) else 'all_at_or_above_threshold' if q(lo[0])>=q(threshold) else 'threshold_crossing_possible')
    scenarios=[]
    for name,initial,word in [('nominal',center,means),('heater_outage',center,[[0]]*steps),('upper_box_corner',[22]*n,[[2]]*steps)]:
        full,reduced=_simulate(model,approximate,initial,word)
        errors=[abs(a[0]-b[0]) for a,b in zip(full,reduced)]
        assert all(error<=q(bound) for error,bound in zip(errors,approximate['certificate']['bound']))
        scenarios.append({'name':name,'full_corner_mean':encoded(full),'reduced_corner_mean':encoded(reduced),
                          'max_actual_reduction_error':str(max(errors))})
    modes={}
    for name,conductance in [('low','1/16'),('high','1/8')]:
        mode=plate_model(grid,conductance)
        modes[name]=mode.spec()
    family=compile_sparse_family(modes,model.C,n)
    assert replay_sparse_family(family)
    # Test an interior, time-varying conductance word in exact arithmetic.
    e,d=matrix(family['E']),matrix(family['D'])
    x=tuple(q((7*i)%11)/10 for i in range(n));z=mv(e,x)
    low,high=plate_model(grid,'1/16'),plate_model(grid,'1/8')
    for t in range(steps):
        lam=q((t*7)%13)/12
        u=(q(int(t%3==0)),)
        xlow,xhigh=low.operator.step(x),high.operator.step(x)
        x=addv(tuple((1-lam)*a+lam*b for a,b in zip(xlow,xhigh)),mv(model.B,u))
        gl,gh=matrix(family['G']['low']),matrix(family['G']['high'])
        hl,hh=matrix(family['H']['low']),matrix(family['H']['high'])
        z=addv(tuple((1-lam)*a+lam*b for a,b in zip(mv(gl,z),mv(gh,z))),tuple((1-lam)*a+lam*b for a,b in zip(mv(hl,u),mv(hh,u))))
        assert mv(model.C,x)==mv(d,z)
    summary={'schema':'dynacomp.thermal-workbench/1','grid':grid,'full_states':n,'horizon':steps,
             'approximate_rank':approximate['rank'],'approximate_status':approximate['status'],
             'uniform_worst_reduction_error':approximate['certificate']['worst_bound'],
             'temperature_semantics':'mean of four corners, excess above ambient; per-step model units',
             'fixed_nominal_conductance':'1/8','threshold':str(q(threshold)),
             'sharp_fixed_model_temperature_ranges':ranges,'threshold_classification':classifications,'scenarios':scenarios,
             'robust_exact_family_rank':family['rank'],'robust_conductance_interval':['1/16','1/8'],
             'robust_exact_switching_checks':steps,
             'scope':'approximation/range guarantee fixes conductance at 1/8; separate exact family covers any time-varying conductance in [1/16,1/8]; no continuum or physical installation validation'}
    return approximate,family,summary


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--grid',type=int,default=12)
    parser.add_argument('--steps',type=int,default=20)
    parser.add_argument('--tolerance',default='1/10')
    parser.add_argument('--max-rank',type=int)
    parser.add_argument('--threshold',default='21')
    parser.add_argument('--output-dir',type=Path,required=True)
    args=parser.parse_args()
    try:
        approximate,family,report=workbench(args.grid,args.steps,args.tolerance,args.max_rank,args.threshold)
        args.output_dir.mkdir(parents=True,exist_ok=True)
        for filename,packet in [('approximate_plan.json',approximate),('robust_family.json',family),('report.json',report)]:
            (args.output_dir/filename).write_text(json.dumps(packet,indent=2)+'\n')
        print(json.dumps({key:report[key] for key in ('full_states','approximate_rank','approximate_status','uniform_worst_reduction_error','robust_exact_family_rank')}))
    except (ValueError,KeyError,TypeError,OverflowError,OSError) as exc:
        parser.exit(2,f'dynacomp-thermal: {exc}\n')


if __name__=='__main__':
    main()
","dynacomp/thermal_numeric.py":""""Optional batched thermal execution in a numerically orthogonal basis.

QR changes coordinates within the rationally certified subspace. Binary64 QR
and evolution introduce rounding not covered by the exact algebraic bound.
"""
import numpy as np
from scipy.sparse import csr_matrix
from .rational import q


class ThermalEvolution:
    """Executor for a validated model/plan pair; columns are scenarios."""
    def __init__(self,model,packet,engine='reduced'):
        if engine not in ('full','reduced'):
            raise ValueError("Engine must be full or reduced")
        self.n=model.operator.n;self.m=len(model.B[0]);self.p=len(model.C)
        rows,cols,values=zip(*model.operator.entries) if model.operator.entries else ([],[],[])
        a=csr_matrix((np.asarray(values,dtype=float),(rows,cols)),shape=(self.n,self.n))
        b=np.asarray(model.B,dtype=float);c=np.asarray(model.C,dtype=float)
        if engine=='full':
            self.q=None;self.a,self.b,self.c=a,b,c
        else:
            e=np.asarray([[float(q(v)) for v in row] for row in packet['E']])
            self.q=np.linalg.qr(e.T,mode='reduced')[0]
            self.a=self.q.T@(a@self.q)
            self.b=self.q.T@b;self.c=c@self.q

    def simulate(self,initial,inputs):
        initial,inputs=np.asarray(initial,dtype=float),np.asarray(inputs,dtype=float)
        if initial.ndim!=2 or initial.shape[0]!=self.n or initial.shape[1]<1 or inputs.ndim!=3 or inputs.shape[1:]!=(self.m,initial.shape[1]) or not np.isfinite(initial).all() or not np.isfinite(inputs).all():
            raise ValueError("Finite initial [nodes,scenarios] and input [steps,channels,scenarios] arrays required")
        state=initial.copy() if self.q is None else self.q.T@initial
        output=np.empty((len(inputs)+1,self.p,initial.shape[1]))
        output[0]=self.c@state
        for t,u in enumerate(inputs):
            state=self.a@state+self.b@u
            output[t+1]=self.c@state
        if not np.isfinite(output).all():
            raise OverflowError("Nonfinite numerical outputs")
        return output


def run_thermal_batch(packet,initial,inputs,engine='reduced'):
    """Public convenience path validates the packet and its box domain."""
    from .uniform import SparseLinearModel,replay_uniform
    replay_uniform(packet)
    model=SparseLinearModel.from_spec(packet['model'])
    initial,inputs=np.asarray(initial,dtype=float),np.asarray(inputs,dtype=float)
    runner=ThermalEvolution(model,packet,engine)
    # Validate shapes before broadcasting domain bounds.
    if initial.ndim!=2 or initial.shape[0]!=model.operator.n or inputs.ndim!=3 or inputs.shape[1:]!=(len(model.B[0]),initial.shape[1]) or inputs.shape[0]!=len(packet['input_radii']):
        raise ValueError("Batch dimensions or horizon differ from certified domain")
    if not np.isfinite(initial).all() or not np.isfinite(inputs).all():
        raise ValueError("Finite scenario values required")
    from fractions import Fraction
    # Interpret binary64 values as exact rationals for box membership, so a
    # rounded decimal endpoint cannot accidentally admit an outside value.
    for i,(c,r) in enumerate(zip(packet['initial_center'],packet['initial_radius'])):
        low,high=q(c)-q(r),q(c)+q(r)
        if any(not low<=Fraction(float(value))<=high for value in initial[i]):
            raise ValueError("Scenario lies outside the certified initial box")
    for t,(centers,radii) in enumerate(zip(packet['input_centers'],packet['input_radii'])):
        for k,(c,r) in enumerate(zip(centers,radii)):
            low,high=q(c)-q(r),q(c)+q(r)
            if any(not low<=Fraction(float(value))<=high for value in inputs[t,k]):
                raise ValueError("Scenario lies outside a certified input box")
    return runner.simulate(initial,inputs)
","dynacomp/uniform.py":""""Sharp finite-horizon box errors and general-direction enrichment.

Every output error is a known linear function of the initial state and the
independent input boxes. Its exact range follows from absolute coefficient
sums, with a retained attaining witness. Sparse target pullbacks are cached;
no full-state matrix powers or full-state reconstruction envelope is needed.
"""
from dataclasses import dataclass
from .rational import q, matrix, mul, sub, mv, addv, transpose, inverse, identity, encoded
from .sparse import SparseOperator
from .krylov import Echelon


@dataclass(frozen=True)
class SparseLinearModel:
    operator: SparseOperator
    B: tuple
    C: tuple

    @classmethod
    def from_spec(cls, spec):
        op = SparseOperator.from_entries(spec["n"], spec["entries"])
        b,c = matrix(spec["B"]),matrix(spec["C"])
        if len(b)!=op.n or len(c[0])!=op.n:
            raise ValueError("Expected B[n,m] and C[p,n]")
        return cls(op,b,c)

    def spec(self):
        return {"n":self.operator.n,"entries":[[i,j,str(v)] for i,j,v in self.operator.entries],
                "B":encoded(self.B),"C":encoded(self.C)}


def as_sparse(model):
    if isinstance(model,SparseLinearModel):
        return model
    n=len(model.A)
    return SparseLinearModel(SparseOperator.from_entries(n,[(i,j,v) for i,row in enumerate(model.A) for j,v in enumerate(row) if v]),model.B,model.C)


def _domain(model,center,radius,input_radii,input_centers):
    center,radius=tuple(q(v) for v in center),tuple(q(v) for v in radius)
    if len(center)!=model.operator.n or len(radius)!=model.operator.n or any(v<0 for v in radius):
        raise ValueError("Initial box needs n coordinates and nonnegative radii")
    us=tuple(tuple(q(v) for v in row) for row in input_radii)
    m=len(model.B[0])
    if any(len(row)!=m or any(v<0 for v in row) for row in us):
        raise ValueError("Input radii must have m nonnegative coordinates")
    centers=tuple(tuple(q(v) for v in row) for row in input_centers) if input_centers is not None else tuple((q(0),)*m for _ in us)
    if len(centers)!=len(us) or any(len(row)!=m for row in centers):
        raise ValueError("One matching input center per time required")
    return center,radius,us,centers


def _pullbacks(model,horizon):
    rows=[model.C]
    for _ in range(horizon):
        rows.append(model.operator.pullback(rows[-1]))
    return rows


def _project(model,rows):
    e=matrix(rows)
    v=mul(transpose(e),inverse(mul(e,transpose(e))))
    g=mul(model.operator.pullback(e),v)
    return v,e,g,mul(e,model.B),mul(model.C,v)


def _kernels(model,e,g,h,d,pullbacks):
    dg=d
    state,forcing=[],[]
    for ca in pullbacks:
        state.append(sub(ca,mul(dg,e)))
        forcing.append(sub(mul(ca,model.B),mul(dg,h)))
        dg=mul(dg,g)
    return state,forcing


def _sign(x):
    return int(x>0)-int(x<0)


def _bound(model,candidate,domain,pullbacks):
    v,e,g,h,d=candidate
    center,radius,us,centers=domain
    state,forcing=_kernels(model,e,g,h,d,pullbacks)
    envelopes,central=[],[]
    for t,kernel in enumerate(state):
        mean=list(mv(kernel,center))
        uncertain=[sum(abs(a)*r for a,r in zip(row,radius)) for row in kernel]
        for j in range(t):
            lag=forcing[t-1-j]
            mean=list(addv(mean,mv(lag,centers[j])))
            uncertain=[a+sum(abs(v)*r for v,r in zip(row,us[j])) for a,row in zip(uncertain,lag)]
        central.append(mean)
        envelopes.append(tuple(abs(a)+b for a,b in zip(mean,uncertain)))
    t,output=max(((t,k) for t in range(len(envelopes)) for k in range(len(model.C))),key=lambda pair:envelopes[pair[0]][pair[1]])
    orientation=-1 if central[t][output]<0 else 1
    x0=tuple(c+orientation*_sign(a)*r for c,a,r in zip(center,state[t][output],radius))
    word=[]
    for j,(u,c) in enumerate(zip(us,centers)):
        coefficients=forcing[t-1-j][output] if j<t else (q(0),)*len(u)
        word.append(tuple(v+orientation*_sign(a)*r for v,a,r in zip(c,coefficients,u)))
    signed=central[t][output]+orientation*(envelopes[t][output]-abs(central[t][output]))
    cert={"schema":"dynacomp.sharp-box-bound/1","arithmetic":"rational",
          "coverage":"all initial states and independently chosen inputs in the declared componentwise boxes",
          "bound":[str(max(row)) for row in envelopes],"output_bounds":encoded(envelopes),
          "worst_bound":str(envelopes[t][output]),
          "attaining_witness":{"time":t,"output":output,"x0":[str(v) for v in x0],"inputs":encoded(word) if word else [],"signed_error":str(signed)},
          "claim":"sharp componentwise and worst-horizon output-error suprema for the fixed full and reduced models; excludes floating-point rounding"}
    return cert,state,forcing


def sharp_box_bound(model,V,E,G,H,initial_center,initial_radius,input_radii,input_centers=None):
    model=as_sparse(model)
    v,e,g,h=map(matrix,(V,E,G,H))
    n,r=model.operator.n,len(g)
    if len(v)!=n or len(v[0])!=r or len(e)!=r or len(e[0])!=n or len(g[0])!=r or len(h)!=r or len(h[0])!=len(model.B[0]) or mul(e,v)!=identity(r):
        raise ValueError("Expected V[n,r], E[r,n], G[r,r], H[r,m] and EV=I")
    domain=_domain(model,initial_center,initial_radius,input_radii,input_centers)
    return _bound(model,(v,e,g,h,mul(model.C,v)),domain,_pullbacks(model,len(domain[2])))[0]


def uniform_enrichment(model,initial_center,initial_radius,input_radii,tolerance,input_centers=None,max_rank=None,seed_rows=None,strategy="worst_kernel"):
    """Grow general rational directions with sharp box-uniform acceptance.

    Worst-kernel enrichment adds a missing output sensitivity at the worst
    time. If that row is dependent, it falls back to the first missing target
    pullback. Prefix strategy always chooses the latter. No monotonic error
    or globally optimal rank claim is made. Finite-horizon closure suffices.
    """
    model=as_sparse(model)
    n=model.operator.n
    domain=_domain(model,initial_center,initial_radius,input_radii,input_centers)
    tol=q(tolerance)
    budget=n if max_rank is None else max_rank
    if tol<0 or type(budget) is not int or not 1<=budget<=n or strategy not in ("worst_kernel","prefix"):
        raise ValueError("Nonnegative tolerance, rank budget in [1,n] and valid strategy required")
    span=Echelon()
    for row in model.C:
        span.add(row)
    if seed_rows is not None:
        for row in matrix(seed_rows):
            if len(row)!=n:
                raise ValueError("Seed directions need n coordinates")
            span.add(row)
    if not len(span) or len(span)>budget:
        raise ValueError("Nonzero targets and sufficient initial rank budget required")
    pullbacks=_pullbacks(model,len(domain[2]))
    history=[]
    while True:
        candidate=_project(model,[row for _,row in span.rows])
        cert,state,forcing=_bound(model,candidate,domain,pullbacks)
        history.append({"rank":len(span),"worst_bound":cert["worst_bound"],"worst_time":cert["attaining_witness"]["time"],"worst_output":cert["attaining_witness"]["output"]})
        if q(cert["worst_bound"])<=tol:
            status="tolerance_met"
            break
        if len(span)>=budget:
            status="rank_budget_exhausted"
            break
        witness=cert["attaining_witness"]
        t,k=witness["time"],witness["output"]
        chosen=None
        if strategy=="worst_kernel" and any(span.reduce(state[t][k])):
            chosen=state[t][k]
            label={"kind":"worst_output_kernel","time":t,"output":k}
        if chosen is None:
            for depth,ca in enumerate(pullbacks):
                for output,row in enumerate(ca):
                    if any(span.reduce(row)):
                        chosen=row
                        label={"kind":"target_pullback","time":depth,"output":output}
                        break
                if chosen is not None:
                    break
        if chosen is None:
            raise ArithmeticError("Finite-horizon target span should have zero kernels")
        history[-1]["added_direction"]=label
        assert span.add(chosen)
    v,e,g,h,d=candidate
    center,radius,us,centers=domain
    return {"schema":"dynacomp.uniform-enrichment/1","model":model.spec(),"status":status,"tolerance":str(tol),"max_rank":budget,"rank":len(e),"strategy":strategy,
            "initial_center":[str(x) for x in center],"initial_radius":[str(x) for x in radius],
            "input_radii":encoded(us) if us else [],"input_centers":encoded(centers) if centers else [],
            "V":encoded(v),"E":encoded(e),"G":encoded(g),"H":encoded(h),"D":encoded(d),
            "certificate":cert,"history":history,
            "claim":"general-direction projection with sharp fixed-model box-uniform output-error acceptance; enrichment is heuristic"}


def replay_uniform(packet):
    """Recompute projection and exact box certificate, without enrichment."""
    if packet.get("schema")!="dynacomp.uniform-enrichment/1":
        raise ValueError("Unknown uniform enrichment schema")
    model=SparseLinearModel.from_spec(packet["model"])
    v,e,g,h,d=map(matrix,(packet[k] for k in ("V","E","G","H","D")))
    rank=packet["rank"]
    if type(rank) is not int or type(packet["max_rank"]) is not int or not 1<=rank<=packet["max_rank"]<=model.operator.n or len(e)!=rank or len(e[0])!=model.operator.n:
        raise ValueError("Invalid dimensions or budget")
    if _project(model,e)!=(v,e,g,h,d):
        raise ValueError("Projection identities fail")
    certificate=sharp_box_bound(model,v,e,g,h,packet["initial_center"],packet["initial_radius"],packet["input_radii"],packet["input_centers"])
    if certificate!=packet["certificate"]:
        raise ValueError("Stored bound or attaining witness does not match")
    tol=q(packet["tolerance"])
    expected="tolerance_met" if q(certificate["worst_bound"])<=tol else "rank_budget_exhausted"
    if tol<0 or packet["status"]!=expected or (expected=="rank_budget_exhausted" and rank!=packet["max_rank"]):
        raise ValueError("Invalid acceptance status")
    # Also execute the worst-case witness as a separate acceptance check.
    witness=certificate["attaining_witness"]
    x=tuple(q(v) for v in witness["x0"])
    z=mv(e,x)
    for u in witness["inputs"][:witness["time"]]:
        x=addv(model.operator.step(x),mv(model.B,u))
        z=addv(mv(g,z),mv(h,u))
    actual=mv(model.C,x)[witness["output"]]-mv(d,z)[witness["output"]]
    if actual!=q(witness["signed_error"]) or abs(actual)!=q(certificate["worst_bound"]):
        raise ValueError("Attaining witness does not attain the bound")
    return True


def output_box_range(model,initial_center,initial_radius,input_radii,input_centers=None):
    """Sharp full-model output intervals at each time for independent boxes.

    These are ranges of the output itself, distinct from reduction error.
    Different output/time extrema may require different admissible inputs.
    """
    model=as_sparse(model)
    center,radius,us,centers=_domain(model,initial_center,initial_radius,input_radii,input_centers)
    ca=_pullbacks(model,len(us))
    cb=[mul(row,model.B) for row in ca]
    means,widths=[],[]
    for t,row in enumerate(ca):
        mean=mv(row,center)
        width=tuple(sum(abs(v)*r for v,r in zip(output,radius)) for output in row)
        for j in range(t):
            kernel=cb[t-1-j]
            mean=addv(mean,mv(kernel,centers[j]))
            width=addv(width,tuple(sum(abs(v)*r for v,r in zip(output,us[j])) for output in kernel))
        means.append(mean);widths.append(width)
    return {"schema":"dynacomp.output-box-range/1","center":encoded(means),"radius":encoded(widths),
            "lower":encoded(tuple(tuple(a-b for a,b in zip(mean,width)) for mean,width in zip(means,widths))),
            "upper":encoded(tuple(tuple(a+b for a,b in zip(mean,width)) for mean,width in zip(means,widths))),
            "coverage":"sharp individual time/output intervals for a fixed model and independently chosen state/input boxes; not a simultaneous trajectory enclosure with independently attainable endpoints"}
","dynacomp/upoly.py":""""Univariate polynomials over Q: coefficient tuples, lowest degree first.

Includes Sturm sequences for exact real-root counting and isolation, and a
rational-root finder that needs no integer factorization.
"""
from fractions import Fraction
from math import lcm, gcd
from .rational import q


def trim(p):
    p = [q(x) for x in p]
    while p and not p[-1]:
        p.pop()
    return tuple(p)


def const(c):
    return trim([c])


def add(p, r):
    n = max(len(p), len(r))
    return trim([(p[i] if i < len(p) else 0) + (r[i] if i < len(r) else 0) for i in range(n)])


def neg(p):
    return tuple(-x for x in p)


def sub(p, r):
    return add(p, neg(r))


def scale(p, c):
    return trim([x*c for x in p])


def mul(p, r):
    if not p or not r:
        return ()
    out = [Fraction(0)]*(len(p)+len(r)-1)
    for i, a in enumerate(p):
        if a:
            for j, b in enumerate(r):
                out[i+j] += a*b
    return trim(out)


def degree(p):
    return len(p)-1


def divmod_(p, d):
    if not d:
        raise ZeroDivisionError("Polynomial division by zero")
    p, quotient = list(p), [Fraction(0)]*max(len(p)-len(d)+1, 1)
    while len(p) >= len(d) and p:
        c = p[-1]/d[-1]
        shift = len(p)-len(d)
        quotient[shift] = c
        for i, x in enumerate(d):
            p[shift+i] -= c*x
        p = list(trim(p))
    return trim(quotient), trim(p)


def monic(p):
    return scale(p, 1/p[-1]) if p else ()


def pgcd(p, r):
    while r:
        p, r = r, divmod_(p, r)[1]
    return monic(p)


def derivative(p):
    return trim([i*x for i, x in enumerate(p)][1:])


def evaluate(p, x):
    x, total = q(x), Fraction(0)
    for c in reversed(p):
        total = total*x + c
    return total


def primitive(p):
    """Integer coefficients with gcd 1 and positive leading coefficient."""
    if not p:
        return ()
    m = lcm(*(c.denominator for c in p))
    ints = [int(c*m) for c in p]
    g = gcd(*ints)
    sign = 1 if ints[-1] > 0 else -1
    return tuple(Fraction(sign*c//g) for c in ints)


def squarefree(p):
    if degree(p) < 1:
        return primitive(p)
    return primitive(divmod_(p, pgcd(p, derivative(p)))[0])


def sturm(p):
    seq = [p, derivative(p)]
    while seq[-1]:
        r = neg(divmod_(seq[-2], seq[-1])[1])
        if not r:
            break
        seq.append(r)
    return seq


def _variations(seq, x):
    signs = [s for s in (evaluate(p, x) for p in seq) if s]
    return sum((a > 0) != (b > 0) for a, b in zip(signs, signs[1:]))


def root_bound(p):
    """Cauchy bound: every real root lies strictly inside (-b, b)."""
    return 1 + max(abs(c/p[-1]) for c in p[:-1]) if degree(p) > 0 else Fraction(1)


def count_roots(p, lo, hi, seq=None):
    """Distinct real roots in (lo, hi] of a squarefree p."""
    seq = seq or sturm(p)
    return _variations(seq, lo) - _variations(seq, hi)


def isolate(p, width=None):
    """Disjoint (lo, hi] intervals each holding one real root of squarefree p."""
    if degree(p) < 1:
        return []
    seq, b = sturm(p), root_bound(p)
    stack, out = [(-b, b)], []
    while stack:
        lo, hi = stack.pop()
        k = count_roots(p, lo, hi, seq)
        if k == 0:
            continue
        if k == 1 and (width is None or hi-lo <= width):
            out.append((lo, hi))
            continue
        mid = (lo+hi)/2
        stack.extend([(mid, hi), (lo, mid)])
    return sorted(out)


def real_roots(p):
    """Exact rational roots and isolating intervals for irrational real roots.

    A rational root N/L of an integer polynomial with leading coefficient L
    makes L*x an integer, so refining each interval below width 1/L leaves at
    most one integer candidate. No factorization of coefficients is needed.
    """
    p = squarefree(p)
    if degree(p) < 1:
        return [], []
    lead = abs(int(p[-1]))
    rational, irrational = [], []
    for lo, hi in isolate(p, width=Fraction(1, 2*lead)):
        candidates = [Fraction(N, lead) for N in range(int((lo*lead)//1), int((hi*lead)//1)+2)]
        hit = [x for x in candidates if lo < x <= hi and not evaluate(p, x)]
        if hit:
            rational.append(hit[0])
        else:
            irrational.append((lo, hi))
    return rational, irrational


def encode(p):
    return [str(c) for c in p]


def parse(entry):
    """A rational scalar, or a list of coefficients from lowest degree."""
    if isinstance(entry, (list, tuple)):
        return trim(entry)
    return const(entry)
","dynacomp/validated.py":""""Rigorous finite-horizon box brackets using bounded-precision integer rows.

This accepts a supplied encoder and reduced dynamics; EV=I is not required.
Exact inequalities concern those supplied matrices, not runtime roundoff.
Outward radii track every coefficient conversion and integer dot rounding.
"""
from fractions import Fraction
from .rational import q,matrix,encoded,mul,transpose,identity,sub
from .uniform import as_sparse,_domain,_sign,SparseLinearModel
from .stability import positive_definite


def _nearest(x,scale):
    y=x*scale
    return (2*y.numerator+y.denominator)//(2*y.denominator)


def _quantize(rows,scale):
    centers=[];radii=[]
    for row in rows:
        c=[_nearest(v,scale) for v in row]
        centers.append(c);radii.append([int(Fraction(a,scale)!=v) for a,v in zip(c,row)])
    return centers,radii


def _columns(rows,scale):
    c,r=_quantize(rows,scale)
    return [[(i,a,b) for i,(a,b) in enumerate(zip(col,rad)) if a or b] for col,rad in zip(zip(*c),zip(*r))]


def _advance(row,columns,scale):
    x,r=row;centers=[];radii=[]
    for col in columns:
        dot=spread=0
        for i,a,b in col:
            dot+=x[i]*a
            spread+=abs(x[i])*b+r[i]*(abs(a)+b)
        center=(2*dot+scale)//(2*scale)
        # |exact product-center/scale| <= spread/scale^2 plus
        # the exact distance of the rounded integer dot from its midpoint.
        radius=(spread+abs(dot-center*scale)+scale-1)//scale
        centers.append(center);radii.append(radius)
    return centers,radii


def _subtract(a,b):
    return [x-y for x,y in zip(a[0],b[0])],[x+y for x,y in zip(a[1],b[1])]


class BoxKernelCache:
    """Reuse source output pullbacks and input kernels across candidate models."""
    def __init__(self,model,horizon):
        if type(horizon) is not int or horizon<0:raise ValueError('Nonnegative integer horizon required')
        self.model=as_sparse(model);self.horizon=horizon;self._cache={}
        self.source_passes=0

    def source(self,bits):
        if bits not in self._cache:
            scale=1<<bits;model=self.model
            columns=[[] for _ in range(model.operator.n)]
            for i,j,v in model.operator.entries:
                c=_nearest(v,scale);r=int(Fraction(c,scale)!=v)
                if c or r:columns[j].append((i,c,r))
            bcols=_columns(model.B,scale);c,r=_quantize(model.C,scale)
            rows=list(zip(c,r));states=[];forcing=[]
            for t in range(self.horizon+1):
                states.append(rows);forcing.append([_advance(row,bcols,scale) for row in rows])
                if t<self.horizon:rows=[_advance(row,columns,scale) for row in rows]
            self._cache[bits]=(states,forcing);self.source_passes+=1
        return self._cache[bits]


def _dimensions(model,E,G,H,D):
    e,g,h,d=map(matrix,(E,G,H,D));n=model.operator.n;r=len(g);m=len(model.B[0]);p=len(model.C)
    if len(e)!=r or len(e[0])!=n or len(g[0])!=r or len(h)!=r or len(h[0])!=m or len(d)!=p or len(d[0])!=r:
        raise ValueError('Expected E[r,n], G[r,r], H[r,m], D[p,r]')
    return e,g,h,d


def _bracket(cache,e,g,h,d,domain,bits):
    scale=1<<bits;states,forcing=cache.source(bits)
    ec,gc,hc=_columns(e,scale),_columns(g,scale),_columns(h,scale)
    dc,dr=_quantize(d,scale);rows=list(zip(dc,dr));ks=[];js=[]
    for t in range(cache.horizon+1):
        ks.append([_subtract(full,_advance(reduced,ec,scale)) for full,reduced in zip(states[t],rows)])
        js.append([_subtract(full,_advance(reduced,hc,scale)) for full,reduced in zip(forcing[t],rows)])
        if t<cache.horizon:rows=[_advance(row,gc,scale) for row in rows]
    center,radius,us,means=domain;bounds=[];lowers=[];best=None
    for t in range(cache.horizon+1):
        upper_row=[];lower_row=[]
        for output in range(len(d)):
            x,r=ks[t][output]
            mean=sum(a*c for a,c in zip(x,center));mean_error=sum(a*abs(c) for a,c in zip(r,center))
            width_hi=sum((abs(a)+b)*v for a,b,v in zip(x,r,radius))
            width_signed_lo=sum((abs(a)-b)*v for a,b,v in zip(x,r,radius))
            for j in range(t):
                k,s=js[t-1-j][output]
                mean+=sum(a*c for a,c in zip(k,means[j]));mean_error+=sum(a*abs(c) for a,c in zip(s,means[j]))
                width_hi+=sum((abs(a)+b)*v for a,b,v in zip(k,s,us[j]))
                width_signed_lo+=sum((abs(a)-b)*v for a,b,v in zip(k,s,us[j]))
            upper=(abs(mean)+mean_error+width_hi)/scale
            # This lower endpoint is attained by the sign corner of the
            # midpoint kernels. Ambiguous coefficient signs subtract radii.
            lower=max(q(0),(abs(mean)-mean_error+width_signed_lo)/scale)
            upper_row.append(upper);lower_row.append(lower)
            if best is None or lower>best[0]:best=(lower,t,output,1 if mean>=0 else -1)
        bounds.append(upper_row);lowers.append(lower_row)
    low,t,output,orientation=best;x,r=ks[t][output]
    x0=[str(c+orientation*_sign(a)*v) for c,a,v in zip(center,x,radius)]
    inputs=[]
    for j in range(cache.horizon):
        row=js[t-1-j][output][0] if j<t else [0]*len(us[j])
        inputs.append([str(c+orientation*_sign(a)*v) for c,a,v in zip(means[j],row,us[j])])
    return {'schema':'dynacomp.dyadic-box-bracket/1','bits':bits,'output_upper':encoded(bounds),'output_attained_lower':encoded(lowers),
            'worst_upper':str(max(max(row) for row in bounds)),'worst_attained_lower':str(low),
            'witness':{'time':t,'output':output,'orientation':orientation,'x0':x0,'inputs':inputs,'absolute_error_at_least':str(low)},
            'claim':'encloses the sharp worst error; lower endpoint reached or exceeded by the supplied corner; finite horizon; evolution rounding excluded'}


def euclidean_contraction(G):
    g=matrix(G)
    if len(g[0])!=len(g):raise ValueError('Square reduced operator required')
    return positive_definite(sub(identity(len(g)),mul(transpose(g),g)))


def validated_box(model,E,G,H,D,initial_center,initial_radius,input_radii,tolerance,input_centers=None,
                  precisions=(64,96,128,192),slack='1/1000000',cache=None,require_contraction=False):
    model=as_sparse(model);e,g,h,d=_dimensions(model,E,G,H,D)
    domain=_domain(model,initial_center,initial_radius,input_radii,input_centers);tol=q(tolerance);gap=q(slack)
    if tol<0 or gap<0:raise ValueError('Nonnegative tolerance and slack required')
    precisions=tuple(precisions)
    if not precisions or any(type(b) is not int or not 8<=b<=4096 for b in precisions):raise ValueError('Precision bits must be integers in [8,4096]')
    if type(require_contraction) is not bool:raise ValueError('Boolean contraction requirement expected')
    if cache is None:cache=BoxKernelCache(model,len(domain[2]))
    if cache.model!=model or cache.horizon!=len(domain[2]):raise ValueError('Cache source or horizon differs')
    stable=euclidean_contraction(g) if require_contraction else None
    history=[]
    for bits in precisions:
        certificate=_bracket(cache,e,g,h,d,domain,bits)
        lo,hi=q(certificate['worst_attained_lower']),q(certificate['worst_upper'])
        history.append({'bits':bits,'lower':str(lo),'upper':str(hi)})
        if hi<=tol:status='tolerance_met' if stable is not False else 'stability_not_certified';break
        if lo>tol:status='refuted';break
        status='undecided'
        if hi-lo<=gap:break
    center,radius,us,means=domain
    return {'schema':'dynacomp.validated-box/1','model':model.spec(),'E':encoded(e),'G':encoded(g),'H':encoded(h),'D':encoded(d),
            'initial_center':[str(v) for v in center],'initial_radius':[str(v) for v in radius],
            'input_radii':encoded(us) if us else [],'input_centers':encoded(means) if means else [],'tolerance':str(tol),
            'require_contraction':require_contraction,'reduced_contraction_certified':stable,'status':status,'rank':len(g),
            'certificate':certificate,'precision_history':history,
            'claim':'supplied encoder and reduced model accepted over stated boxes; no EV identity or physical-model validation implied'}


def replay_validated(packet):
    if packet.get('schema')!='dynacomp.validated-box/1':raise ValueError('Unknown validated-box schema')
    model=SparseLinearModel.from_spec(packet['model'])
    fresh=validated_box(model,packet['E'],packet['G'],packet['H'],packet['D'],packet['initial_center'],packet['initial_radius'],
                        packet['input_radii'],packet['tolerance'],input_centers=packet['input_centers'],
                        precisions=(packet['certificate']['bits'],),require_contraction=packet['require_contraction'])
    for key in ('certificate','status','rank','reduced_contraction_certified'):
        if fresh[key]!=packet[key]:raise ValueError('Validated certificate or acceptance differs: '+key)
    return True
","dynacomp/validated_numeric.py":""""Reusable numerical execution of the actual validated encoder/dynamics."""
import copy
import numpy as np
from .rational import q
from .uniform import SparseLinearModel,_domain
from .validated import replay_validated
from .prepared import PreparedSwitching


class PreparedValidated:
    def __init__(self,packet,engine='reduced',allow_unaccepted=False):
        if engine not in ('full','reduced'):raise ValueError('Full or reduced engine required')
        self.packet=copy.deepcopy(packet)
        if self.packet.get('schema')!='dynacomp.validated-box/1':raise ValueError('Unknown validated plan')
        if engine=='reduced':
            replay_validated(self.packet)
            if self.packet['status']!='tolerance_met' and not allow_unaccepted:raise ValueError('Reduced plan has not met tolerance')
        model=SparseLinearModel.from_spec(self.packet['model'])
        _domain(model,self.packet['initial_center'],self.packet['initial_radius'],self.packet['input_radii'],self.packet['input_centers'])
        self.n,self.m,self.p=model.operator.n,len(model.B[0]),len(model.C);self.horizon=len(self.packet['input_radii'])
        self.encoder=None
        if engine=='full':
            # Sampled external matrices are dense; dense BLAS is the baseline.
            self.a=np.zeros((self.n,self.n))
            for i,j,v in model.operator.entries:self.a[i,j]=float(v)
            self.b=np.asarray(model.B,dtype=float);self.c=np.asarray(model.C,dtype=float)
        else:
            def array(name):return np.asarray([[float(q(v)) for v in row] for row in self.packet[name]])
            self.encoder=array('E');self.a=array('G');self.b=array('H');self.c=array('D')
        values=(self.a,self.b,self.c) if self.encoder is None else (self.a,self.b,self.c,self.encoder)
        if any(not np.isfinite(v).all() for v in values):raise OverflowError('Nonfinite numerical matrices')
        pairs=[PreparedSwitching._float_endpoints(q(c)-q(r),q(c)+q(r)) for c,r in zip(self.packet['initial_center'],self.packet['initial_radius'])]
        self.initial_lower=np.asarray([lo for lo,hi in pairs])[:,None];self.initial_upper=np.asarray([hi for lo,hi in pairs])[:,None]
        pairs=[[PreparedSwitching._float_endpoints(q(c)-q(r),q(c)+q(r)) for c,r in zip(center,radius)] for center,radius in zip(self.packet['input_centers'],self.packet['input_radii'])]
        self.input_lower=np.asarray([[lo for lo,hi in row] for row in pairs]).reshape(self.horizon,self.m,1)
        self.input_upper=np.asarray([[hi for lo,hi in row] for row in pairs]).reshape(self.horizon,self.m,1)
        self.cache_stats={'packet_replays':int(engine=='reduced'),'batches':0,'initial_fields_encoded':0}

    def simulate(self,initial,inputs):
        initial,inputs=np.asarray(initial,dtype=float),np.asarray(inputs,dtype=float)
        if initial.ndim==1:initial=initial[:,None]
        if inputs.ndim!=3 or inputs.shape[:2]!=(self.horizon,self.m) or inputs.shape[2]<1:raise ValueError('Wrong input dimensions or certified horizon')
        count=inputs.shape[2]
        if initial.ndim!=2 or initial.shape[0]!=self.n or initial.shape[1] not in (1,count):raise ValueError('Wrong initial dimensions')
        if not np.isfinite(initial).all() or not np.isfinite(inputs).all():raise ValueError('Finite batch required')
        if (initial<self.initial_lower).any() or (initial>self.initial_upper).any() or (inputs<self.input_lower).any() or (inputs>self.input_upper).any():raise ValueError('Batch outside certified boxes')
        state=initial.copy() if self.encoder is None else self.encoder@initial
        if state.shape[1]==1 and count!=1:state=np.repeat(state,count,axis=1)
        output=np.empty((self.horizon+1,self.p,count));output[0]=self.c@state
        for t,u in enumerate(inputs):state=self.a@state+self.b@u;output[t+1]=self.c@state
        if not np.isfinite(output).all():raise OverflowError('Nonfinite numerical output')
        self.cache_stats['batches']+=1
        if self.encoder is not None:self.cache_stats['initial_fields_encoded']+=initial.shape[1]
        return output
","dynacomp/zonotope.py":""""Sharp output-error bounds over correlated (zonotopic) scenario domains.

Box domains treat every coordinate and every time independently. Physical
uncertainty is usually correlated: one unknown ambient offset shifts every
cell, a heater runs at one unknown but constant level. A zonotope expresses
this: the scenario (x0, u_0, ..., u_(T-1)) equals a centre plus sum_g xi_g w_g
with |xi_g| <= 1, where a generator w_g may touch any coordinates and times.

The error at time t, output i, is a linear functional L of the scenario, so
its exact supremum is |L(centre)| + sum_g |L(w_g)|, attained at
xi_g = orientation * sign(L(w_g)). Boxes are the special case of one
generator per coordinate and time. Every zonotope inside a box has a bound no
larger than the box's, and usually much smaller.
"""
from .rational import q, matrix, mv, addv, encoded, identity, mul
from .uniform import as_sparse, _kernels, _pullbacks, _project, SparseLinearModel


def _gen(raw, n, m, horizon):
    x = {int(k): q(v) for k, v in (raw.get("x0") or {}).items()}
    u = {}
    for t, vec in (raw.get("inputs") or {}).items():
        t = int(t)
        if not 0 <= t < horizon or len(vec) != m:
            raise ValueError("Generator input entries need a valid time and m coordinates")
        u[t] = tuple(q(v) for v in vec)
    if any(not 0 <= k < n for k in x):
        raise ValueError("Generator state index out of range")
    return x, u


def box_generators(n, radius=None, input_radii=()):
    """One generator per coordinate and time: the box as a zonotope."""
    gens = []
    if radius is not None:
        gens += [{"x0": {k: r}} for k, r in enumerate(radius) if q(r)]
    for t, row in enumerate(input_radii):
        for k, r in enumerate(row):
            if q(r):
                vec = [0]*len(row)
                vec[k] = r
                gens.append({"inputs": {t: vec}})
    return gens


def _serialize(gens):
    return [{"x0": {str(k): str(v) for k, v in x.items()}, "inputs": {str(t): [str(a) for a in vec] for t, vec in u.items()}}
            for x, u in gens]


def sharp_zonotope_bound(model, V, E, G, H, x0_center, input_centers, generators):
    model = as_sparse(model)
    v, e, g, h = map(matrix, (V, E, G, H))
    n, m = model.operator.n, len(model.B[0])
    if mul(e, v) != identity(len(g)):
        raise ValueError("Need EV = I")
    c = tuple(q(x) for x in x0_center)
    a = [tuple(q(x) for x in row) for row in input_centers]
    horizon = len(a)
    if len(c) != n or any(len(row) != m for row in a):
        raise ValueError("Centre dimensions do not match the model")
    gens = [_gen(raw, n, m, horizon) for raw in generators]
    d = mul(model.C, v)
    state, forcing = _kernels(model, e, g, h, d, _pullbacks(model, horizon))
    table, best = [], None
    for t, kernel in enumerate(state):
        row_bounds = []
        for i, krow in enumerate(kernel):
            mean = sum(x*y for x, y in zip(krow, c))
            mean += sum(sum(x*y for x, y in zip(forcing[t-1-j][i], a[j])) for j in range(t))
            coeffs = []
            for gx, gu in gens:
                value = sum(krow[k]*w for k, w in gx.items())
                value += sum(sum(x*y for x, y in zip(forcing[t-1-j][i], vec)) for j, vec in gu.items() if j < t)
                coeffs.append(value)
            bound = abs(mean) + sum(abs(x) for x in coeffs)
            row_bounds.append(bound)
            if best is None or bound > best[0]:
                best = (bound, t, i, mean, coeffs)
        table.append(row_bounds)
    bound, t, i, mean, coeffs = best
    orientation = -1 if mean < 0 else 1
    signs = [orientation*((x > 0) - (x < 0)) for x in coeffs]
    x0 = list(c)
    word = [list(row) for row in a]
    for s, (gx, gu) in zip(signs, gens):
        for k, w in gx.items():
            x0[k] += s*w
        for j, vec in gu.items():
            word[j] = [p + s*w for p, w in zip(word[j], vec)]
    return {"schema": "dynacomp.zonotope-bound/1", "arithmetic": "rational",
            "model": model.spec(), "V": encoded(v), "E": encoded(e), "G": encoded(g), "H": encoded(h),
            "x0_center": [str(x) for x in c], "input_centers": encoded(a) if a else [],
            "generators": _serialize(gens), "generator_count": len(gens),
            "bound": [str(max(row)) for row in table], "worst_bound": str(bound),
            "worst_bound_approximately": f"{float(bound):.9g}",
            "attaining_witness": {"time": t, "output": i, "x0": [str(x) for x in x0],
                                  "inputs": encoded(word) if word else [],
                                  "generator_signs": signs,
                                  "signed_error": str(orientation*bound)},
            "claim": "sharp per-time supremum over the zonotope of initial states and input words, with an attaining scenario"}


def replay_zonotope(packet):
    """Recompute the bound and simulate the witness through both models exactly."""
    if packet.get("schema") != "dynacomp.zonotope-bound/1":
        raise ValueError("Unknown schema")
    model = SparseLinearModel.from_spec(packet["model"])
    v, e, g, h = (matrix(packet[k]) for k in ("V", "E", "G", "H"))
    fresh = sharp_zonotope_bound(model, v, e, g, h, packet["x0_center"], packet["input_centers"], packet["generators"])
    if fresh != packet:
        raise ValueError("Stored bound or witness does not match recomputation")
    w = packet["attaining_witness"]
    x = tuple(q(a) for a in w["x0"])
    z = mv(e, x)
    for u in w["inputs"][:w["time"]]:
        x = addv(model.operator.step(x), mv(model.B, u))
        z = addv(mv(g, z), mv(h, u))
    d = mul(model.C, v)
    actual = mv(model.C, x)[w["output"]] - mv(d, z)[w["output"]]
    if actual != q(w["signed_error"]) or abs(actual) != q(packet["worst_bound"]):
        raise ValueError("Witness does not attain the bound")
    return True
