$('#model-file').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>65536)throw Error('Choose a model JSON file smaller than 64 KB.');custom=JSON.parse(await file.text());const source=custom.model||custom;if(!source.A||!source.B||!source.C)throw Error('This model needs the A, B and C arrays used by DynaComp.');example='custom';document.querySelectorAll('[data-example]').forEach(x=>x.classList.remove('selected'));$('#update-status').textContent='Your model is ready. Choose settings and calculate.';}catch(e){$('#update-status').textContent=e.message;}};
