","engine-worker.mjs":"import {loadPyodide} from 'https://cdn.jsdelivr.net/pyodide/v0.29.5/full/pyodide.mjs';
let runtime;
async function prepare(bundle){
 if(runtime)return runtime;
 self.postMessage({status:'preparing'});
 const py=await loadPyodide();py.FS.mkdirTree('/model/dynacomp');
 for(const [name,source] of Object.entries(bundle.engine_files)){
  if(!/^dynacomp\/[a-z_]+\.py$/.test(name))throw Error('Unsupported engine file path');
  const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(source))),x=>x.toString(16).padStart(2,'0')).join('');
  if(digest!==bundle.source_hashes[name])throw Error('Engine source did not match its public digest');
  py.FS.writeFile('/model/'+name,source);
 }
 // Activate only the portable package namespace. Desktop native-library
 // initialization is not executed in WebAssembly; the mathematical modules
 // below remain the original source-bound DynaComp implementations.
 await py.runPythonAsync("import sys,types,json\npkg=types.ModuleType('dynacomp');pkg.__path__=['/model/dynacomp'];sys.modules['dynacomp']=pkg\nfrom dynacomp.explorer import scenario");
 runtime=py;return py;
}
self.onmessage=async event=>{try{const py=await prepare(event.data.bundle);py.globals.set('request_json',JSON.stringify(event.data.request));const raw=await py.runPythonAsync('json.dumps(scenario(json.loads(request_json)))');self.postMessage({status:'complete',result:JSON.parse(raw)});}catch(e){self.postMessage({status:'error',message:String(e)});}};
","icon.svg":"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 192 192"><rect width="192" height="192" rx="40" fill="#163b44"/><path d="M30 140Q75 120 95 80T165 45" fill="none" stroke="#a8d7bd" stroke-width="12"/><path d="M30 140Q75 120 95 80T165 45" fill="none" stroke="white" stroke-width="3" stroke-dasharray="8 9"/></svg>","index.html":"<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#163b44"><link rel="manifest" href="/manifest.webmanifest"><link rel="icon" href="/icon.svg"><link rel="stylesheet" href="/style.css"><title>DynaComp · What happens next?</title></head><body><header><a class="brand" href="/">◒ <span>DynaComp</span></a><nav><a href="https://our-apps.towre676.chatgpt.site">All our apps</a><button id="install">Get it on your phone</button></nav></header><main><section class="intro"><div class="eyebrow">EXPLORE WHAT HAPPENS NEXT</div><h1>A simpler model.<br>The answer you care about.</h1><p>Choose something to follow, change a few settings, and see whether a smaller model gives you the same answer.</p><p id="update-status" class="status" role="status">Opening your workspace…</p></section><section class="choose" aria-label="Choose an example"><button class="example selected" data-example="warmth"><span class="symbol">☀</span><strong>Warm connected rooms</strong><small>Follow warmth as it spreads.</small></button><button class="example" data-example="supplies"><span class="symbol">▦</span><strong>Move supplies</strong><small>Follow stock across connected places.</small></button><label class="example upload"><span class="symbol">↥</span><strong>Bring your own model</strong><small>Open a saved DynaComp JSON model.</small><input id="model-file" type="file" accept=".json,application/json"></label></section><div class="workspace"><section class="panel controls"><h2>What would you like to know?</h2><label for="output">Follow</label><select id="output"><option value="whole">The whole system’s average</option><option value="one">One room or place</option></select><label for="start">Starting level <output id="start-value">20</output></label><input id="start" type="range" min="0" max="60" value="20"><label for="strength">Added each step <output id="strength-value">2</output></label><input id="strength" type="range" min="0" max="10" value="2" step="0.5"><label for="steps">How far ahead? <output id="steps-value">16 steps</output></label><input id="steps" type="range" min="4" max="32" value="16"><label for="accuracy">How close should it stay?</label><select id="accuracy"><option value="0">Keep the answer exactly</option><option value="0.1">Allow up to 0.1 output units</option><option value="1">Allow up to 1 output unit</option><option value="5">Allow up to 5 output units</option></select><button id="run" class="primary">See what happens <span>→</span></button><button id="cancel" hidden>Stop this calculation</button><p class="hint">These examples are teaching models. They are not measurements of your home or supply chain.</p></section><section class="panel results"><div class="result-heading"><h2 id="result-title">Your comparison</h2><span class="badge" id="result-badge">Ready when you are</span></div><div id="chart" class="chart"><div class="empty"><svg viewBox="0 0 500 180" aria-hidden="true"><path d="M10 145 Q90 90 150 105 T285 57 T485 30" fill="none" stroke="#a9c9c7" stroke-width="5"/><path d="M10 145 Q90 90 150 105 T285 57 T485 30" fill="none" stroke="#317e79" stroke-width="2" stroke-dasharray="8 7"/></svg><p>Two models. One answer to compare.</p></div></div><div class="legend"><span><i class="original"></i> Original model</span><span><i class="smaller"></i> Smaller model</span></div><div id="numbers" class="numbers"></div><p id="explanation">The smaller model keeps the information needed for your chosen output. A matching result can require fewer values to update.</p><div class="actions"><button id="save" disabled>Save this run</button><button id="export" disabled>Download results</button></div><details id="details"><summary>How this answer was obtained</summary><p id="scope"></p><p>Calculations run on this device through the actual DynaComp Python library. Inputs and results stay here. The chart uses rounded display coordinates; exported results retain exact fractions.</p><pre id="technical"></pre></details></section></div><section class="saved panel"><div class="result-heading"><h2>Your saved runs</h2><button id="clear">Clear saved runs</button></div><div id="saved-list">Your saved comparisons will appear here.</div></section><section class="about"><h2>Which app should I use?</h2><p><strong>DynaComp</strong> helps predict change while keeping only the information needed for your chosen output. <strong>PerfectPower</strong> counts and explores exact possibilities. <strong>NFL PerfectPower</strong> helps you understand games, historical results and market prices. <strong>Pokepolis</strong> is the game world.</p><a href="https://our-apps.towre676.chatgpt.site">Visit the app collection →</a></section><section class="downloads panel"><h2>Take it with you</h2><p>Use this page on your phone and add it to your home screen. Keep the full software, worked examples and mathematics together in the complete source download.</p><div class="actions"><a class="button" id="source-download" href="https://github.com/towre676-cloud/DynaComp/archive/refs/heads/main.zip">Complete software ZIP</a><a id="monograph" href="https://github.com/towre676-cloud/DynaComp/blob/main/docs/EXPLORER_AND_LIVE_APPS.md">Read how it works</a></div><p class="hint">Large numerical imports and native performance trials use the downloadable desktop Python package. The browser workspace supports small exact sampled models.</p></section></main><footer><span>DynaComp · Clear questions, accountable answers.</span><a href="https://our-apps.towre676.chatgpt.site">All apps & downloads</a></footer><script src="/app.js"></script></body></html>
